/* ÇEVİRİ bs · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("bs","olay",{
"OLAYLAR_P0049:1587-01-01:0":{"b": ["Osnovan Gorijski ejalet — izravna osmanska uprava na zapadu Kartlija", "9a7c8bc5"], "d": ["Godine 1578. gruzijski begovi u krajevima Gorija i Muhranija pokorili su se Osmanlijama. Godine 1587. na zapadu Kartlija osnovan je Gorijski ejalet i oblast je vezana za izravnu osmansku upravu. Gorijska tvrđava, izgubljena tokom pobune Gruzijca Simona, povraćena je 1601; osmanska uprava okončana je 1603. pohodom šaha Abasa.", "7ee17c2b"]},
"OLAYLAR_P0049:1595-01-01:0":{"b": ["Prepadi Mihaila Hrabrog na dunavske tvrđave — spaljen Rusčuk, zauzeta Braila, opljačkana Silistra", "d0b83f6a"], "d": ["Vlaški vojvoda Mihail Hrabri, koji se pridružio Svetoj ligi, u zimu 1594-95. navalio je na tvrđave i gradove pod izravnom osmanskom upravom duž Dunava. Prema članku Rusčuk u TDV, u februaru 1595. tvrđavu nije uspio zauzeti, ali je zauzeo i spalio grad. Prema članku Braila, zauzeo je Brailu na lijevoj obali Dunava i grad je ostao u njegovim rukama do 1601; i članak Murat III piše da je vlaška vojska spalila brailsku tvrđavu i prodrla do Silistre. Prema popisnom zapisu pomenutom u članku Silistra, vlaška vojska je u proljeće 1595. prešla Dunav i opljačkala Silistru; gradska tvrđava je srušena i dugo se nije mogla koristiti. Istog ljeta Kodža Sinan-paša krenut će na pohod na Vlašku.", "c115852f"]},
"OLAYLAR_P0049:1603-01-01:0":{"b": ["Šah Abas povratio Tbilisi — kraj osmanske uprave u Kartliju i Kahetiji", "a6995ea8"], "d": ["Šah Abas I 1603. povratio je Tbilisi od Osmanlija i proglasio Kartli kanatom; i u Kahetiji je uspostavljena safavidska uprava. Tako je okončana osmanska uprava u istočnoj Gruziji, koja je počela pohodom Lala Mustafa-paše 1578; Tbilisi će u osmanske ruke ponovo prijeći tek 1723.", "e37dcbfc"]},
"OLAYLAR_P0049:1640-01-01:0":{"b": ["Imeretske, gurijske i megrelske jedinice srušile tvrđavu Faš (Poti)", "3c3d4ed7"], "d": ["Tvrđavu Faš 1640. su sravnile sa zemljom imeretske jedinice, u kojima su učestvovali knezovi Gurije i Megrelije. Osmansko prisustvo na ušću Rionija prekinuto je do ponovne gradnje tvrđave 1724.", "2bb31f58"]},
"OLAYLAR_P0049:1711-04-09:0":{"b": ["Počeo pohod na Prut — vojska krenula iz Istanbula u Rusko-osmanskom ratu 1710-1711.", "3161364b"], "d": ["Ruski napad na osmanske teritorije, nepoštivanje odredaba Istanbulskog mira iz 1700. od strane cara Petra i poticaji krimskog kana Devlet Giraja naveli su Ahmeda III da objavi rat Rusiji. Prema članku Ahmed III u TDV, taj rat, kasnije nazvan pohod na Prut, faktički je počeo polaskom osmanske vojske iz Istanbula 9. aprila 1711. Vojska pod komandom Baltadži Mehmed-paše spojila se s krimskim snagama i napredovala prema rijeci Prut; pohod će u julu završiti stiskanjem ruske vojske na obali Pruta.", "49618c54"]},
"OLAYLAR_P0049:1724-03-01:0":{"b": ["Počela ponovna gradnja tvrđave Faš (Poti)", "0afbc4b0"], "d": ["Po odluci donesenoj 23. decembra 1723. ponovna gradnja srušene tvrđave Faš počela je u martu 1724; gradnja je završena 1729.", "e9e6b3d8"]},
"OLAYLAR_P0049:1724-05-06:0":{"b": ["Hoj, Kapan i oblast Karadaga ponovo prešli pod osmansku upravu", "c52c94d1"], "d": ["Tokom iranskog pohoda započetog 1723, Hoj te oblasti Kapan i Karadag 6. maja 1724. ponovo su prešli pod osmansku upravu i 1728. upisani u osmanski popis. Atlas smatra da je i Kotur, 40 km jugozapadno od Hoja, tog dana prešao od Safavida Osmanlijama (lanac preuzet od Hoja: Uluerler 2015, Turkish Studies 10/5, s. 6; dan svojstven Koturu nije u izvoru — deklarirana približnost).", "eb5141eb"]},
"OLAYLAR_P0049:1733-08-17:0":{"b": ["Nadir ušao u Šemahu — središte Širvana izašlo iz osmanske vlasti", "778a4988"], "d": ["Nadir je 17. augusta 1733. ušao u Šemahu, koja je Istanbulskim ugovorom od 24. juna 1724. zajedno sa središnjim dijelom Širvana pripala osmanskom udjelu. Osmanska uprava na Kavkazu zatim se brzo raspala; Gandža i Tbilisi izgubljeni su 1735.", "4ab61a36"]},
"OLAYLAR_P0049:1787-07-27:0":{"b": ["Ultimatum ruskom izaslaniku — posljednji korak ka Rusko-osmanskom ratu 1787-1792.", "cb389693"], "d": ["Napetost koja je trajala od ruske aneksije Krima 1783. prekinuta je kada se shvatilo da je ruski konzulat u Aleksandriji huškao mamelučke begove u Egiptu protiv Osmanlija. Prema članku Abdulhamid I u TDV, reisul-kuttab Sulejman Fejzi-efendija 27. jula 1787. uručio je ruskom izaslaniku u Istanbulu ultimatum od sedam tačaka. Ne čekajući ruski odgovor, donesena je odluka o ratu i za nekoliko sedmica on je objavljen; cilj rata bio je povrat Krima.", "04debfa8"]},
"OLAYLAR_P0049:1809-11-27:0":{"b": ["Ruske snage zauzele tvrđavu Faš (Poti) — izgubljeno ušće Rionija", "c1241b5a"], "d": ["Tokom Rusko-osmanskog rata 1806-1812. ruski napad u maju 1809. nije uspio; no tvrđava je 27. novembra 1809. predata Rusima.", "84e0aac2"]},
"OLAYLAR_P0049:1812-12-19:0":{"b": ["Po Bukureštanskom miru tvrđava Faš (Poti) vraćena Osmanlijama", "6a3a8a0a"], "d": ["Po Bukureštanskom miru iz 1812. tvrđava Faš 19. decembra 1812. predata je Osmanskoj državi.", "d59bceb8"]},
"OLAYLAR_P0049:1828-06-26:0":{"b": ["Tvrđava Faš (Poti) po drugi put prešla u ruske ruke — Jedrenskim mirom ostala Rusiji", "682d58f0"], "d": ["Na početku Rusko-osmanskog rata 1828-1829. tvrđava Faš 26. juna 1828. predata je Rusima. Jedrenskim mirom od 14. septembra 1829. s Ahalcihom, Ahalkalakijem i Anapom i Poti je prepušten Rusiji.", "364c160c"]},
"OLAYLAR_P0049:1915-07-25:0":{"b": ["Englezi okupirali Nasiriju — eufratski front", "669b979e"], "d": ["Britanske snage, koje su napredovale iz Basre duž Eufrata, 24. jula 1915. porazile su osmanske jedinice i sljedećeg dana okupirale Nasiriju. Basra je pala u novembru 1914; Nasirija je pak još oko osam mjeseci ostala u osmanskim rukama.", "bd125229"]},
"OLAYLAR_P0049:1919-04-29:0":{"b": ["Italijanska okupacija Antalije", "328331da"], "d": ["Dok su se nakon Mudroskog primirja države Antante smještale u okupacione zone u Anadoliji, Italija se usmjerila na jugozapadnu Anadoliju. Prema članku Antalija u TDV, grad i okolinu su, pozivajući se na odredbe primirja, 29. aprila 1919. okupirali Italijani. Okupacija će trajati oko dvije godine.", "41127caf"]},
"OLAYLAR_P0049:1920-02-11:0":{"b": ["Oslobođenje Maraša — Francuzi ispraznili grad", "a57d884e"], "d": ["Maraš, koji su Englezi okupirali 22. februara 1919, sporazumom dviju država 29. oktobra 1919. prepušten je Francuzima. Ponašanje Armenaca u francuskim jedinicama i skidanje turske zastave s tvrđave podigli su stanovništvo na ustanak; u gradu su se organizirali Društvo za odbranu prava i Nacionalne snage. Prema članku Kahramanmaraš u TDV, na kraju sukoba Francuzi su 11. februara 1920. počeli prazniti grad i povlačiti se prema Islahiji, a Maraš je oslobođen 11-12. februara. Gradu je 1925. dodijeljena medalja nezavisnosti.", "d3bff1ef"]},
"OLAYLAR_P0049:1920-04-11:0":{"b": ["Oslobođenje Urfe — francuski garnizon napustio grad", "c889488c"], "d": ["U Urfi, koju su u martu 1919. okupirali Englezi, a oko sedam mjeseci kasnije Francuzi, stanovništvo se 7. februara 1920. podiglo na ustanak protiv okupacionih snaga. Prema članku Šanliurfa u TDV, nakon dva mjeseca borbi Francuzi su 10. aprila 1920. pod uslovima sporazuma pristali isprazniti Urfu i sljedećeg dana napustili grad.", "88526a6f"]},
"OLAYLAR_P0049:1920-09-28:0":{"b": ["Počela operacija na Istočnom frontu — Kazim Karabekir krenuo u ofanzivu protiv Armenije", "151678df"], "d": ["Budući da je Sèvreski ugovor Erzurum, Trabzon, Van, Bitlis i Bingöl ostavio Armeniji i da su armenski napadi u oblasti rasli, vlada Velike narodne skupštine Turske 20. septembra 1920. dozvolila je operaciju. Prema članku Kazim Karabekir u TDV, komandant Istočnog fronta Karabekir izdao je naredbu o napadu svojim jedinicama koje su držale prijevoje planine Soganli i 28. septembra započeo istočnu operaciju. Zauzeti su Sarikamiš, Gole i Kagizman; operacija će se mjesec dana kasnije nastaviti oslobađanjem Karsa.", "add8f41a"]},
"OLAYLAR_P0049:1920-10-30:0":{"b": ["Oslobođenje Karsa — Istočni front ušao u Kars", "4e578071"], "d": ["Prema članku Kars u TDV, Kazim Karabekir-paša ušao je u Kars 30. oktobra 1920. i grad je oslobođen armenske uprave kojoj su Englezi 1919. prepustili kontrolu. Članak Karabekir naglašava da je to drugo oslobođenje Karsa: grad je prvi put uzet od Armenaca u aprilu 1918. Istočni front je napredujući 7. novembra zauzeo Gjumri; rat je okončan Gjumrijskim mirom od 3. decembra 1920.", "1841f6d3"]},
"OLAYLAR_P0049:1920-11-07:0":{"b": ["Zauzimanje Gjumrija — Istočni front napredovao u unutrašnjost Armenije", "cfddf791"], "d": ["Jedinice Kazim Karabekir-paše, koji je nastavio operaciju nakon oslobađanja Karsa, 7. novembra 1920. zauzele su Gjumri. Pregovori s Armencima, koji su pristali na primirje, vođeni su u Gjumriju i rat je okončan Gjumrijskim mirom potpisanim 3. decembra 1920.", "4c34b9ce"]},
"OLAYLAR_P0049:1920-11-12:0":{"b": ["Zauzimanje Igdira", "6e952d2e"], "d": ["Pet dana nakon zauzimanja Gjumrija, Istočni front je 12. novembra 1920. zauzeo i Igdir. Igdir je Gjumrijskim mirom od 3. decembra 1920. prepušten Turskoj.", "f96469bd"]},
"OLAYLAR_P0049:1921-02-09:0":{"b": ["Kraj odbrane Antepa — grad nakon deset mjeseci otpora prepušten Francuzima", "e080af8b"], "d": ["Antep, u koji su Englezi ušli 17. decembra 1918, 5. novembra 1919. prepušten je Francuzima; prvi otpor na liniji Antep-Kilis vodio je Šahin-beg. Prema članku Gaziantep u TDV, stanovništvo grada opiralo se francuskim snagama od 1. aprila 1920. do 7. februara 1921; kada je otpor slomljen, snage u odbrani povukle su se, a Francuzi su 9. februara zavladali gradom. Velika narodna skupština Turske je tri dana prije toga, 6. februara 1921, gradu koji je deset mjeseci izdržao okupaciju dala počasno zvanje gazije. Antep će nakon Ankarskog sporazuma biti ispražnjen 25. decembra 1921.", "086ee824"]},
"OLAYLAR_P0049:1921-02-23:0":{"b": ["Oslobođenje Ardahana i Artvina", "b9e50d5e"], "d": ["Nakon Gjumrijskog mira Istočni front okrenuo se dijelu triju sandžaka (elviye-i selâse) koji je bio u rukama Gruzije. Prema članku Ardahan u TDV, na kraju borbe s gruzijskim i armenskim četama 23. februara 1921. s Artvinom je oslobođen i ardahanski sandžak. Članak Kazim Karabekir piše da su tim potezom povraćeni teritoriji triju sandžaka osim kadiluka Čuruksu, Adžare i Batuma.", "1ee51ba4"]},
"OLAYLAR_P0049:1921-03-16:0":{"b": ["Moskovski ugovor — Velika narodna skupština Turske i Sovjetska Rusija odredile istočnu granicu", "78d46573"], "d": ["Vlada Velike narodne skupštine Turske i Sovjetska Rusija 16. marta 1921. potpisale su Moskovski ugovor. Prema članku Kars u TDV, ovim ugovorom i graničnim uređenjem Karskog ugovora od 13. oktobra 1921. Kars je ostao unutar granica nove turske države. Prema članku Ahiska, Ahalcihe je ovim ugovorom vezan za Tifliski okrug Gruzijske Sovjetske Socijalističke Republike. Istočna granica konačno će se utvrditi sedam mjeseci kasnije Karskim ugovorom potpisanim s republikama Južnog Kavkaza. Ovim su ugovorom Batum i Adžara (Hulo, Sarpi, Murvaneti, Makhalak'auri) prepušteni sovjetskoj Gruziji.", "7951b57b"]},
"OLAYLAR_P0049:1921-06-01:0":{"b": ["Italijani počeli prazniti Antaliju", "f7a4eaa7"], "d": ["Prema članku Antalija u TDV, italijanska okupacija, koja je trajala od 29. aprila 1919, okončana je kada su Italijani 1. juna 1921. počeli prazniti grad. Antalija i okolina tako su oslobođene okupacije ne čekajući vojni ishod Nacionalne borbe.", "ffd82d73"]},
"OLAYLAR_P0050:1527-01-01:0":{"b": ["Cetinski sabor — hrvatski plemići nakon Mohača izabrali Habsburgovca Ferdinanda za kralja Hrvatske", "55fc9d7e"], "d": ["Kada je smrću ugarsko-hrvatskog kralja Ludovika II kod Mohača prijestolje ostalo prazno, hrvatski plemići sastali su se 31. decembra 1526. u Cetinu i na Novu godinu proglasili austrijskog nadvojvodu Ferdinanda kraljem. Po izrazu TDV, Hrvati su taj izbor izvršili nezavisno od ugarskih plemića; izborna isprava temeljila se na obrazloženju da se pred osmanskim upadima ne treba odvojiti od kršćanske države. Tako su hrvatske tvrđave susjedne osmanskoj Bosni vezane za krunu dinastije Habsburg; prema TDV, kada su Habsburzi 1530-ih počeli uređivati hrvatsku graničnu oblast, glavno središte te linije postao je Bihać.", "5e7c69d8"]},
"OLAYLAR_P0050:1527-01-01:1":{"b": ["Kratkotrajna osmanska uprava nad Bihaćem — nakon Mohača i pada Jajca", "fd4118fe"], "d": ["Nakon pobjede kod Mohača Osmanlije su u Bosni zauzele Jajce, središte ugarske tampon-oblasti, i Banju Luku. Prema članku Bihać u TDV, u godini nakon Mohača, poslije zauzimanja tvrđave Jajce, Bihać je na kratko vrijeme ponovo prešao pod osmansku upravu. Kada i kako je tvrđava izgubljena, nije zapisano u izvoru; TDV samo navodi da su 1530-ih, uređujući hrvatsku graničnu oblast, Habsburzi Bihać, koji je bio u kršćanskim rukama, učinili glavnim središtem. Trajno osvajanje Bihaća ostvarit će se 1592. pohodom bosanskog beglerbega Hasan-paše.", "3421f09a"]},
"OLAYLAR_P0050:1814-01-28:0":{"b": ["Kraj francuske uprave u Dubrovniku — austrijske snage ušle u grad, nekadašnjeg osmanskog haračara", "38d42444"], "d": ["Prema TDV, Francuzi su 27. maja 1806. zauzećem grada okončali Dubrovačku Republiku, koja je od 1365. bila pod osmanskom zaštitom. U zimu 1813-1814. stanovništvo grada pobunilo se protiv Francuza; austrijski general-major Milutinović, koji je 3. januara 1814. s dva hrvatska bataljona došao u Gruž, opsjeo je garnizon; nakon četverodnevnog bombardovanja francuski garnizon poslao je generalu poslanika. U zoru 28. januara austrijske i britanske jedinice krenule su iz Gruža na grad; 31. januara u oblasti je počela djelovati privremena austrijska uprava. Pripajanje grada austrijskim teritorijima konačno je potvrđeno na Bečkom kongresu 1815.", "bb94e4af"]},
"OLAYLAR_P0050:1882-03-06:0":{"b": ["Proglašenje Kraljevine Srbije — nekadašnja osmanska vazalna kneževina pretvorena u kraljevinu", "7d90e712"], "d": ["Kneževina Srbija, koja je 1878. stekla nezavisnost i iste godine uzela i Niš, koji je bio u osmanskim rukama, u doba Milana Obrenovića pretvorena je u kraljevinu. Prvim članom zakona donesenog u Beogradu kneževina je proglašena Kraljevinom Srbijom, a knez Milan postao je kralj pod imenom Milan I; zakon je istog dana objavljen u službenim Srpskim novinama. Tako je Srbija, koja je do 1878. bila kneževina vezana za Osmanlije, na Balkanu zauzela mjesto s kraljevskom titulom. Tim je proglasom cijela Kneževina Srbija (Beograd, Niš, Jagodina, Vranje, Leskovac, Prokuplje, Pirot i dr.) postala Kraljevina Srbija.", "a2849d70"]},
"OLAYLAR_P0050:1920-07-01:0":{"b": ["U Palestini uspostavljena britanska civilna mandatna uprava — kraj vojne uprave na teritorijima uzetim od Osmanlija", "c0d7b76a"], "d": ["Kada je 1917. general Allenby zauzeo Gazu, a zatim Jerusalem, okončana je četiri stotine godina duga osmanska vlast u Palestini; Jerusalem je od 1917. do 1920. ostao pod britanskom vojnom upravom. Konferencija u San Remu 1920. dala je Palestinu pod britanski mandat; Engleska je od jula 1920. u oblasti uspostavila civilnu mandatnu upravu i počela zemljom upravljati preko visokog komesara. Na čelu civilne uprave bio je visoki komesar Herbert Samuel. Arapski ustanci i jevrejsko-arapski sukobi, koji su počeli iste godine, obilježit će cijelo mandatno razdoblje. Tim događajem Tiberija (Palestina) prešla je pod britansku civilnu mandatnu upravu.", "bc1ec892"]},
"OLAYLAR_P0050:1922-03-15:0":{"b": ["Proglašena Kraljevina Egipat — sultan Ahmed Fuad uzeo titulu kralja", "c6ad08d1"], "d": ["Engleska je 18. decembra 1914. jednostrano ukinula suverena prava Osmanske države nad Egiptom i uzela zemlju pod protektorat. Kako pregovori Engleske i Egipta nakon rata nisu dali rezultat, Engleska je 28. februara 1922. opet jednostranom deklaracijom proglasila Egipat nezavisnom državom. Sultan Ahmed Fuad 15. marta 1922. uzeo je titulu kralja (melik) i u Egiptu je proglašena monarhija. TDV tu nezavisnost smatra formalnom; ustav kraljevinskog poretka stupit će na snagu 19. aprila 1923.", "f9b00023"]},
"OLAYLAR_P0051:1480-01-01:0":{"b": ["Tvrđava Hadžibej (Kačibej) izlazi iz litvanskih ruku", "382b51e3"], "d": ["Luku Kačibej na sjeverozapadnoj obali Crnog mora početkom 15. stoljeća utvrdio je litvanski veliki knez Vytautas. Godine 1480. tvrđava je izašla iz litvanskih ruku i dobila ime Hadžibej. Obala je krajem 15. stoljeća prešla pod kontrolu Krimskog kanata, potčinjenog Osmanlijama; izravno vezivanje oblasti za osmansku upravnu organizaciju pak je 1538.", "cea3442c"]},
"OLAYLAR_P0051:1570-01-01:0":{"b": ["Gramota Ivana IV donskim kozacima — prvi pouzdani zapis o Donskoj kozačkoj hordi", "16c0732e"], "d": ["Podaci o postojanju kozaka na Donu počinju od sredine 16. stoljeća. Prema ruskoj vojnoj enciklopediji, starina Donske kozačke horde računa se od 1570: te je godine car Ivan IV poslao gramotu kozacima koji su živjeli na Sjevernom Doncu, tražeći da pomognu Ivanu Novosiljcevu, poslanom preko Azova kao poslanik osmanskom sultanu, i obećao da će ih zauzvrat nagraditi. To je prvi pouzdani zapis o službi donskih kozaka Moskovskoj državi. Glavno središte kozaka bilo je najprije Gornji Razdori, a zatim Čerkask.", "3ce37828"]},
"OLAYLAR_P0051:1585-01-01:0":{"b": ["Moskva podigla u Voronježu istureni garnizon prema stepi", "89c941fe"], "d": ["Krajem 16. stoljeća današnja Slobodska Ukrajina i gornji sliv Dona bili su pusta divlja stepa kojom su Tatari prolazili u pohodima na Moskvu. Moskovska vlada u toj je stepi podigla niz isturenih garnizona; Voronjež je kao jedan od njih osnovan 1585. Tvrđava je narednih desetljeća s Belgorodom i Kurskom bila jedna od prvih karika južne odbrambene linije Moskve.", "ceb11b6b"]},
"OLAYLAR_P0051:1596-01-01:0":{"b": ["Moskva podigla Belgorod, Oskol i Kursk kao istureni garnizone u stepi", "4ff3e225"], "d": ["Moskovska vlada, pomjerajući južnu granicu naprijed radi odbrane od krimskih upada, 1596. osnovala je Belgorod, Oskol i Kursk kao garnizonske tačke u divljoj stepi. Belgorod je od tog vremena bio gradić-tvrđava i u narednom stoljeću postao središte Belgorodske odbrambene linije duge 300 kilometara.", "50cb899c"]},
"OLAYLAR_P0052:1884-01-01:0":{"b": ["Siirtski sandžak prenesen iz Dijarbekira u Bitliski vilajet — i kadiluk Eruh i selo Širnak vezani za Bitlis", "3922d040"], "d": ["Kada se nakon Tanzimata prešlo sa sistema ejaleta na sistem vilajeta, siirtski sandžak, koji je ostao vezan za Dijarbekirski vilajet, 1884. prenesen je u Bitliski vilajet. Prema članku Širnak u TDV, teritoriji na kojima se nalazi današnji Širnak tako su se našli unutar kadiluka Eruh, vezanog za siirtski sandžak Bitliskog vilajeta. Širnak je tada bio malo selo kadiluka Eruh; njegovo ime pojavljuje se u zapisima krajem XIX stoljeća, a status središta kadiluka stekao je tek u prvim godinama Republike. Ti su teritoriji nakon Čaldiranskog pohoda 1514. pripojeni Osmanlijama i upravljani u okviru siirtskog sandžaka Dijarbekirskog ejaleta.", "1539b089"]},
"OLAYLAR_P0053:1624-01-01:0":{"b": ["Mosul i Kirkuk prelaze u safavidske ruke — nakon pada Bagdada", "86e176c8"], "d": ["Šah Abas, koji je na kraju događaja započetih pobunom Bekir-subašija zauzeo Bagdad, poslao je svog zapovjednika Karčakaj-hana sa snagama na Mosul i Kirkuk. Mosulski namjesnik Čerkez Ahmed-paša mogao je braniti grad nekoliko dana; kao i Kirkuk, i Mosul je prešao pod iransku vlast, a za namjesnika je postavljen Kasim-han. Kada se Sipahi Mali Ahmed, koji je komandovao prethodnicom Hafiz Ahmed-paše, pojavio pred Mosulom, Kasim-han je napustio grad i povukao se u Bagdad, no protivakcijom šaha Abasa Mosul je 1624. ponovo prešao u ruke Safavida.", "81474bd6"]},
"OLAYLAR_P0053:1625-01-01:0":{"b": ["Oslobođenje Mosula od Safavida — bagdadski pohod Hafiz Ahmed-paše", "1f9ca4a1"], "d": ["Murat IV poslao je na Bagdad vojsku pod komandom velikog vezira Hafiz Ahmed-paše. Dok je vojska bila u okolini Dijarbekira, prethodnica karamanskog beglerbega Čerkez Hasana gonila je do Kirkuka pristaše Irana okupljene u Altinkopruu i stavila pod kontrolu oblast, uključujući Kirkuk; ni ovaj put Safavidi nisu mogli dugo zadržati Mosul. Hafiz Ahmed-paša početkom septembra stigao je najprije u Mosul, zatim u Kirkuk i 13. novembra 1625. opsjeo Bagdad; opsada je ostala bez rezultata i Bagdad je ostao u safavidskim rukama. Članak Kirkuk u TDV povrat grada od Safavida pak vezuje za 1630. i Husrev-pašu.", "ad32f3ae"]},
"OLAYLAR_P0053:1630-03-16:0":{"b": ["Husrev-paša ponovo podigao tvrđavu Gulanber u Šehrizoru — Šehrizorski beglerbegluk", "9511853c"], "d": ["Veliki vezir Husrev-paša, koji je krenuo na bagdadski pohod, nakon dugog boravka u Mosulu zbog jakih padavina okrenuo se Šehrizoru. Počela je ponovna gradnja tvrđave Gulanber, koja je tokom invazije šaha Abasa po njegovoj naredbi srušena; Šehrizor je ponovo postao sjedište beglerbegluka, a u tvrđavi je kao beglerbeg ostavljen Arnaut Mustafa-paša. Husrev-paša pokorio je plemena u oblasti, zauzeo tvrđavu Mihriban i 5. maja 1630. blizu te tvrđave nanio safavidskoj vojsci teške gubitke.", "ff2c7cea"]},
"OLAYLAR_P0055:1369-01-01:0":{"b": ["Timurtaš-beg u dolini Tundže zauzeo Kizildžaagač Jenidžesi (Elhovo) i Jambol", "2c2aebea"], "d": ["Tokom operacije koju je Murat I vodio protiv Bugarske i Bizanta, Kara Timurtaš-beg poslan je u dolinu Tundže; zauzeo je Kizildžaagač Jenidžesi i Jambol i s obilnim plijenom vratio se u Edirne.", "e2ca7962"]},
"OLAYLAR_P0055:1371-09-26:0":{"b": ["Kneževina Dejanovića (Kostadinova zemlja) postala osmanski vazal", "54b8dd6c"], "d": ["Kada se porazom na Marici (Čirmen) srpska država raspala, braća Jovan i Konstantin Dejanović osnovali su vlastitu kneževinu sa središtem u Velbuždu (kasnije Ćustendil), koja je obuhvatala krajeve Štipa, Strumice, Dojrana i Velesa. Nakon što je Jovan ubrzo umro, Konstantin je priznao vlast Murata I i postao osmanski vazal; kneževina je s tom vezom živjela poluzavisno. Kada je Konstantin 1395. poginuo na Rovinama u redovima Bajazida I Munje, njegova je zemlja bez borbe prešla pod osmansku upravu i postala sandžak pod imenom Kostadin-ili.", "25fd68b1"]},
"OLAYLAR_P0055:1412-01-01:0":{"b": ["Srpski despot Stefan Lazarević zauzeo Pirot (Šehirköy)", "87e1ecb3"], "d": ["Dok je u doba Fetreta trajala borba između Musa-čelebije, koji je vladao Rumelijom, i njegovog brata Mehmeda Čelebije, srpski despot Stefan Lazarević zauzeo je tvrđavu Pirot na putu između Niša i Sofije i zadržao je uprkos Musa-čelebijinom napadu. Sljedeće godine, smrću Muse, Mehmed Čelebija službeno je prepustio tvrđavu svom vazalu Stefanu; Osmanlije su Pirot povratile tek 1428, nakon Lazarevićeve smrti.", "f50a8066"]},
"OLAYLAR_P0055:1538-01-01:0":{"b": ["Andrea Doria zauzeo Herceg Novi (Castelnuovo)", "a8276ff1"], "d": ["Andrea Doria, zapovjednik savezničke flote ujedinjene protiv Osmanlija, zauzeo je tvrđavu Herceg Novi (Castelnuovo) na jadranskoj obali južno od Dalmacije. Iste su godine i Mlečani u Dalmaciji zauzeli neke gradiće u osmanskim rukama, a osmanske snage uzvratile su drugim tvrđavama. Tvrđava je godinu kasnije povraćena; budući da je osmanski suverenitet pravno trajao, taj se međurazdoblje na karti prikazuje šrafiranim okupacionim slojem.", "a9462728"]},
"OLAYLAR_P0055:1539-08-10:0":{"b": ["Barbarosa Hajrudin-paša povratio Herceg Novi (Castelnuovo)", "1e5b49ae"], "d": ["Osmanlije, koje su nakon pobjede kod Preveze preuzele nadmoć i na srednjem Sredozemlju, okrenule su se tvrđavi Nova (Castelnuovo) na jadranskoj obali, koju je godinu ranije zauzeo Andrea Doria. Na kraju operacije koju su zajedno vodili Barbarosa Hajrudin-paša i bosanski sandžakbeg Gazi Husrev-beg tvrđava je povraćena i okupacija okončana.", "29e2c28b"]},
"OLAYLAR_P0055:1798-12-25:0":{"b": ["Desaixov pohod na Gornji Egipat — francuska divizija stigla do Minje, Asjuta i Girge", "8ff8e4fe"], "d": ["Dok je Napoleon boravio u Kairu, divizija generala Desaixa, goneći memlučke snage, napredovala je na jug dolinom Nila: 21. decembra 1798. stigla je u Minju, na Božić u Asjut, a 29. decembra u Girgu. Tim maršem, kojim je u februaru 1799. stigla do Asuana, dolina između Kaira i Asuana ušla je pod francusku kontrolu.", "96ddd684"]},
"OLAYLAR_P0055:1799-02-18:0":{"b": ["Napoleon okupirao Ariš — početak sirijskog pohoda", "69dc52ce"], "d": ["Francuska vojska koja je okupirala Egipat, marširajući na Siriju, zauzela je Ariš na obali Sinaja.", "8feb359c"]},
"OLAYLAR_P0055:1799-12-28:0":{"b": ["Ariš povraćen od Francuza", "c25e48a7"], "d": ["Ariš, koji je Napoleon okupirao u februaru 1799, potkraj decembra iste godine povratila je vojska velikog vezira Jusuf Zija-paše.", "3bde687a"]},
"OLAYLAR_P0056:1739-08-28:0":{"b": ["Poraz kod Stavučana i predaja Hotina Rusima (Rusko-osmanski rat 1736-1739)", "657d82d2"], "d": ["U pohodu 1739. glavna ruska vojska pod komandom maršala Münnicha, prošavši preko poljske zemlje, ušla je u Moldaviju i kod Stavučana blizu Hotina nanijela težak poraz vojsci seraskera Veli-paše. Odmah nakon te bitke tvrđava Hotin predala se Rusima, a ruske snage su početkom septembra ušle u Jaši. No kako je Austrija sklopila odvojeni mir, rat je okončan Beogradskim mirom potpisanim istog mjeseca.", "2e7457b9"]},
"OLAYLAR_P0056:1769-01-01:0":{"b": ["Ruska vojska prešla Dnjestar i ušla u Moldaviju (Rusko-osmanski rat 1768-1774)", "938bd834"], "d": ["Oko šest mjeseci nakon objave rata glavna ruska vojska pod komandom kneza Golicina okupila se u Podoliji. Na poziv moldavskog mitropolita Dositeja da se Moldavija uzme pod rusku zaštitu, Golicin je prešao Dnjestar i prije marša na Jaši pokušao zauzeti Hotin. Taj prvi pokušaj nije uspio i vojska se zbog nestašice hrane vratila u Podoliju; Hotin je pao tek u septembru 1769.", "df52a8ec"]},
"OLAYLAR_P0056:1788-01-01:0":{"b": ["Ruska ukrajinska vojska kod Mogiljova prešla Dnjestar i ušla u Moldaviju (Rusko-osmanski rat 1787-1792)", "822c7361"], "d": ["U ratu koji je počeo osmanskom objavom rata 1787, Rusija je formirala dvije vojske: dok je Potemkinova vojska opsjedala Očakov, ukrajinska vojska Rumjanceva trebala je između Dnjestra i Buga prijetiti Benderu i održavati vezu s Austrijom. Rumjancev je jednu kolonu izdvojio za pomoć Austrijancima koji su opsjedali Hotin, a s glavnim snagama kod Mogiljova prešao je Dnjestar i ušao u Moldaviju. Tako je počeo moldavski krak ruske operacije koja će se protezati do Izmaila i Dunava.", "7c701213"]},
"OLAYLAR_P0056:1806-11-23:0":{"b": ["Ruska vojska bez objave rata prešla Dnjestar i počela okupirati Dunavske kneževine (Rusko-osmanski rat 1806-1812)", "2094a4d9"], "d": ["U oktobru 1806. generalu Michelsonu data je naredba da okupira Moldaviju i Vlašku; rat još nije bio službeno objavljen. Ruske snage počele su prelaziti Dnjestar, a zapovjednici tvrđava Hotin, Bender, Akerman i Kilija predali su svoje tvrđave bez borbe. Samo se muhafiz Izmaila nije pokorio ruskim nagovaranjima. Objava rata Visoke porte uslijedila je nakon te okupacije.", "c770c2b4"]},
"OLAYLAR_P0056:1806-11-30:0":{"b": ["Rusi zauzeli Akerman (1806)", "25aed8d6"], "d": ["Sedmicu nakon što je ruska vojska bez objave rata prešla Dnjestar, Akerman su zauzele snage kneza Kantakuzina; Tatari u gradu napustili su ga. Akerman je Bukureštanskim mirom 1812. zajedno s Besarabijom prepušten Rusiji.", "1e7e3f9e"]},
"OLAYLAR_P0056:1806-12-25:0":{"b": ["Miloradovič ušao u Bukurešt — ruska okupacija Vlaške", "62e4a8e1"], "d": ["Kada je ruska vojska ušla u Moldaviju, ruščučki muhafiz Mustafa-paša poslao je snagu u Bukurešt i ta je snaga zauzela grad. Odred generala Miloradoviča istjerao ih je iz grada; osmanska snaga povukla se u Đurđu. Bukurešt je od tog datuma do Bukureštanskog mira 1812. ostao pod ruskom okupacijom.", "217aa20b"]},
"OLAYLAR_P0056:1810-06-10:0":{"b": ["Predaja Silistre Rusima", "d687d04b"], "d": ["Silistra, koja je u jesen 1809. izdržala Bagrationovu opsadu, u pohodu 1810. po naređenju vrhovnog komandanta Kamenskog ponovo je opsjednuta. Opsadni radovi, započeti krajem maja, trajali su nekoliko dana i tvrđava se predala pod uslovom da garnizon slobodno izađe. Istih dana jurišom je zauzet Pazardžik, a pao je i Hezargrad. Rusi su Silistru držali godinu dana; u proljeće 1811. Kutuzov je digao zidine u zrak i napustio tvrđavu.", "56cdb224"]},
"OLAYLAR_P0056:1810-10-01:0":{"b": ["Predaja Nikopolja i Kule (Turnu) Rusima bez otpora", "e297a862"], "d": ["Nakon predaje Rusčuka i Đurđua vrhovni komandant Kamenski krenuo je duž rijeke na zapad da zauzme dunavske tvrđave do srbijanske granice. Nikopolj i Kula na suprotnoj obali predali su se bez otpora; ruski odredi zauzeli su Plevnu, Loveč i Sevlijevo i srušili njihova utvrđenja. Rusi su Nikopolj držali šest mjeseci i u aprilu 1811. napustili ga dignuvši tvrđavu u zrak.", "f77715d7"]},
"OLAYLAR_P0056:1811-07-04:0":{"b": ["Bitka kod Rusčuka i Kutuzovljevo rušenje Rusčuka i povlačenje na lijevu obalu Dunava", "6af4bf85"], "d": ["Veliki vezir, koji je početkom juna krenuo iz Šumena, napao je rusku vojsku pred Rusčukom, bio poražen i povukao se na utvrđeni položaj na jugu. Kutuzov je, uprkos dobijenoj bici, ostanak u Rusčuku smatrao opasnim; dao je srušiti utvrđenja tvrđave i sve svoje snage prebacio na lijevu obalu Dunava. Veliki vezir ponovo je zauzeo ispražnjeni Rusčuk. Tako je ruski posjed grada, koji je Kamenski nakon krvave opsade preuzeo 26. septembra 1810, trajao devet mjeseci. Prema zapisu TDV, Kutuzov je prije odlaska naredio da se dignu u zrak utvrđenja oko grada i srednjovjekovna tvrđava; u požaru koji je izbio potpuno je srušeno dvanaest od trideset osam džamija koje su 1810. bile u gradu i dva od osam mesdžida. Prelazak osmanske vojske preko Dunava u jesen iste godine završit će opsadom kod Slobozije.", "3b247b6b"]},
"OLAYLAR_P0056:1828-05-07:0":{"b": ["Ruski 6. pješadijski korpus prešao Prut i ušao u Dunavske kneževine (Rusko-osmanski rat 1828-1829)", "9d9aaaad"], "d": ["Nakon ruske objave rata vojska maršala Wittgensteina krenula je u akciju. 6. pješadijski korpus prešao je Prut i ušao u Moldaviju i Vlašku, a njegova prethodnica pod komandom generala Geismara uputila se u Malu Vlašku. Nekoliko dana kasnije 7. korpus opsjeo je Brailu; 3. korpus pripremao se za prelazak Dunava između Izmaila i Renija. Dunavske kneževine ostat će pod ruskom okupacijom do 1834.", "cba5d549"]},
"OLAYLAR_P0056:1829-06-30:0":{"b": ["Predaja Silistre Dibiču — ruska okupacija koja će trajati do 1836.", "55e28ab1"], "d": ["Na početku pohoda 1829. novi ruski vrhovni komandant Dibič za prvi cilj izabrao je Silistru. Garnizon se uporno opirao opsadnim radovima koje je vodio general Schilder; Dibič je dio snaga ostavio u opsadi i krenuo iza leđa velikom veziru. Opsada se nastavila i tvrđava se predala. Rusi su Silistru držali i nakon rata, do 1836.", "4c1a9e8e"]},
"OLAYLAR_P0056:1836-01-01:0":{"b": ["Rusi ispraznili Silistru", "4fe2afaf"], "d": ["Nakon Jedrenskog mira 1829. Rusi nisu ispraznili Silistru i tvrđavu su držali do 1836. Nakon povlačenja ruskih vojnika namjesnik Selim-paša dao je usred napola razrušenog grada sagraditi veliku džamiju s jednom kupolom.", "39444f60"]},
"OLAYLAR_P0056:1853-07-03:0":{"b": ["Ruska vojska prešla Prut i počela okupirati Dunavske kneževine (Vlašku i Moldaviju) — put prema Krimskom ratu", "77862041"], "d": ["Kada je Visoka porta odbila zahtjeve Menšikova u sporu o svetim mjestima u Jerusalemu, car Nikola I naredio je okupaciju Dunavskih kneževina vezanih za Osmanlije 'kao zalog dok Turska ne zadovolji naše opravdane zahtjeve'. Prethodnica vojske pod komandom kneza Gorčakova prešla je Prut i dvanaest dana kasnije ušla u Bukurešt; za njom se glavnina u tri kolone raširila po kneževinama. Ta okupacija bez objave rata dovela je do diplomatske krize u Evropi, a u oktobru 1853. i do osmanske objave rata; Rusi su kneževine ispraznili tek u ljeto 1854. pod pritiskom Austrije.", "04443242"]},
"OLAYLAR_P0057:1442-01-16:0":{"b": ["Mušašaije se naselile u Haviziju — počela mušašaijska uprava u Huzistanu", "674d0173"], "d": ["Muhammed b. Felah, koji se pojavio s tvrdnjom da je mehdija, nakon što se učvrstio među plemenima Meadi, sljedeće je godine uspio da se nastani u Haviziji, pod timuridskom kontrolom. Grad je postao središte mušašaijske dinastije koja će vladati u Huzistanu.", "53937c8f"]},
"OLAYLAR_P0057:1508-05-02:0":{"b": ["Šah Ismail potčinio Haviziju — mušašaije postale safavidski namjesnici", "7e245f4d"], "d": ["Šah Ismail dao je ubiti neke pripadnike mušašaijske dinastije, koje je optužio za zindikluk (krivovjerje), i oblast Havizije potčinio vlastitoj upravi. Mušašaijski poglavari otada su opstajali kao namjesnici potčinjeni Safavidima.", "ee776160"]},
"OLAYLAR_P0057:1534-01-01:0":{"b": ["Tvrđave Pasin, Šuregel i Oltu uzete od Safavida — između Erzuruma i Karsa", "68f297aa"], "d": ["Tokom pohoda sultana Sulejmana Zakonodavca na dva Iraka od Safavida su uzete tvrđave Pasin, Šuregel i Oltu između Erzuruma i Karsa.", "06909003"]},
"OLAYLAR_P0057:1557-04-02:0":{"b": ["Ozdemir-paša zauzeo luku Masavu", "4cc1d4ad"], "d": ["Beglerbeg Habeškog ejaleta Ozdemir-paša, nakon što je zauzeo otoke Dahlak, 2. aprila 1557. zauzeo je grad Masavu na suprotnoj obali; zatim je i Arkiko ušao pod osmansku upravu. Tako je glavna luka Abesinije prema Crvenom moru prešla u osmanske ruke.", "7c5e89f0"]},
"OLAYLAR_P0057:1793-01-31:0":{"b": ["Grofovija Nica pripojena Francuskoj", "a140cab2"], "d": ["Nakon pripojenja Savoje u novembru 1792, francuski Nacionalni konvent 31. januara 1793. potvrdio je pripojenje Francuskoj Grofovije Nice, koja je pripadala Kraljevini Sardiniji; oblast je postala departman Alpes-Maritimes. Nica se nakon Napoleonovog poraza Prvim pariškim mirom od 30. maja 1814. vratila Sardiniji.", "b313c90b"]},
"OLAYLAR_P0057:1917-01-09:0":{"b": ["Bitka kod Rafaha — britansko-anzačka konjica zauzela položaje kod Magruntaina i Rafah", "5053c8ef"], "d": ["Anzačka konjička divizija, Brigada Carskog devinog korpusa i jedna britanska brigada yeomanryja iz Egipatskih ekspedicionih snaga, koje su prešle Sinaj, napale su osmanski položaj utvrđen redutama kod Magruntaina, oko kilometar južno od Rafaha. Nakon teške borbe probojem Novozelanđana i devinih jedinica slomljena je osmanska odbrana; položaj i obližnji Rafah zauzeti su i britanske snage stigle su do palestinske granice.", "7f90289f"]},
"OLAYLAR_P0057:1918-03-12:0":{"b": ["Zimska operacija Kazima Karabekira: s Erzurumom povraćen i Hasankale (Pasinler)", "27df4879"], "d": ["Osmanske snage pod komandom Kazim Karabekir-paše, koji je nakon raspada ruske vojske krenuo u operaciju na istoku, uprkos teškim zimskim uslovima povratile su Erzindžan, Erzurum i Hasankale istočno od Erzuruma; napredovanje se 25. aprila 1918. proteglo do Karsa.", "80a72c73"]},
"OLAYLAR_P0057:1919-01-23:0":{"b": ["Englezi okupirali Eskišehir", "8e349037"], "d": ["Nakon Mudroskog primirja države Antante počele su stavljati pod kontrolu željeznička čvorišta Anadolije. Prema članku Eskišehir u TDV, grad su 23. januara 1919. okupirali Englezi. Britanske jedinice ispraznile su Eskišehir 20. marta 1920.", "5bb8774d"]},
"OLAYLAR_P0057:1919-05-11:0":{"b": ["Italijani se iskrcali na jugozapadne obale Anadolije — Marmaris, Bodrum, Kušadasi", "15d6fb7a"], "d": ["Italija, koja se povukla s Pariške mirovne konferencije protestirajući protiv progrčkog stava saveznika, nakon Antalije iskrcala je vojsku na jugozapadne obale. Prema TDV, 5. maja pod italijansku okupaciju pao je Marmaris, 11. maja Bodrum, 13. maja Kušadasi. Istih dana i Grci su se iskrcali kod Fethije; suparništvo dviju država oko zapadne Anadolije pripremilo je put okupaciji Izmira.", "82266143"]},
"OLAYLAR_P0057:1919-05-26:0":{"b": ["Grčke snage ušle u Manisu i Ajdin", "a4230775"], "d": ["Grčka vojska, koja se 15. maja iskrcala u Izmiru, ubrzo se raširila u unutrašnjost. Prema članku Manisa u TDV, grčke snage ušle su u grad 26. maja 1919; prema članku Ajdin, Ajdin je okupiran sljedećeg dana, 27. maja. Okupacija Manise trajat će do septembra 1922.", "514ead8b"]},
"OLAYLAR_P0057:1919-06-28:0":{"b": ["Italijanska okupacija Burdura — povlačenje čete usmjerene na Ispartu", "874e9d6d"], "d": ["Italijani, koji su okupirali Antaliju, napredovali su prema unutrašnjosti. Prema članku Isparta u TDV, italijanske jedinice 28. juna okupirale su Burdur, a 15. augusta s jednom četom vojnika uputile se na Ispartu. Kada je stanovništvo Isparte odbilo prijedlog o predaji oružja i javilo da će se opirati, Italijani su se sljedećeg dana povukli.", "35806188"]},
"OLAYLAR_P0057:1919-06-30:0":{"b": ["Kratkotrajno oslobođenje Ajdina i ponovna okupacija 4. jula", "753c739f"], "d": ["Protiv grčke okupacije u okolini Odemiša, Nazillija i Ajdina organizirale su se nacionalne snage. Prema članku Ajdin u TDV, grad okupiran 27. maja 1919. nakratko je oslobođen 30. juna, ali je 4. jula ponovo pao pod grčku okupaciju. Grad je zatim ostao pod okupacijom do 7. septembra 1922.", "a0031b01"]},
"OLAYLAR_P0057:1919-07-23:0":{"b": ["Italijanska okupacija Muğle", "a4f5a926"], "d": ["Italija je okupaciju na jugozapadnim obalama proširila prema unutrašnjosti. Prema članku Muğla u TDV, grad je 23. jula 1919. pao pod italijansku okupaciju. Okupacija Muğle trajala je do 5. jula 1921.", "b77c243c"]},
"OLAYLAR_P0057:1919-10-15:0":{"b": ["Počela francuska vojna uprava u Zapadnoj Trakiji", "5801e6de"], "d": ["Zapadna Trakija, u rukama Bugarske koja je izgubila Prvi svjetski rat, dok su trajali mirovni pregovori stavljena je pod kontrolu država Antante. Prema članku Zapadna Trakija u TDV, oblast su 15. oktobra 1919. okupirale francuske snage; Društvo za odbranu prava Zapadne Trakije tada je svoje sjedište preselilo u Komotini (Gümülcine). Francuska uprava trajala je do prepuštanja oblasti Grčkoj u maju 1920. po odluci iz San Rema.", "58f44e3a"]},
"OLAYLAR_P0057:1920-03-20:0":{"b": ["Englezi ispraznili Eskišehir", "6820e164"], "d": ["Eskišehir, od januara 1919. pod britanskom okupacijom, prema članku Eskišehir u TDV Englezi su ispraznili 20. marta 1920. Grad je nekoliko mjeseci kasnije, u junu 1920, postao središte Zapadnog fronta koji je osnovala Velika narodna skupština Turske.", "5f817d34"]},
"OLAYLAR_P0057:1920-06-22:0":{"b": ["Grčka ljetna ofanziva — okupacija Akhisara, Some, Balıkesira i Alašehira", "f096d2b4"], "d": ["Kada su saveznici grčkoj vojsci dopustili da napreduje preko Milneove linije, u zapadnoj Anadoliji počela je velika grčka ofanziva. Prema članku Nacionalna borba u TDV, grčke jedinice, koje su 22. juna krenule u tri kolone, zauzele su Akhisar, Kirkagač, Somu i Balıkesir. Na jugu je 26. juna okupiran Alašehir, a 3. jula Nazilli.", "bb4b4b94"]},
"OLAYLAR_P0057:1920-07-08:0":{"b": ["Grčka okupacija Burse", "7c2b32a1"], "d": ["Sjeverna kolona ljetne ofanzive nakon Balıkesira okrenula se prema Marmari. Prema člancima Bursa i Nacionalna borba u TDV, Bursa je 8. jula 1920. pala pod grčku okupaciju. Nepoštovanje prema turbetima prvih osmanskih vladara izazvalo je veliku reakciju u cijeloj zemlji.", "2f040dcd"]},
"OLAYLAR_P0057:1920-07-20:0":{"b": ["Grčka vojska okupirala Istočnu Trakiju — Edirne i Kırklareli", "9eb3bda1"], "d": ["Grčka je pristupila faktičkom zauzimanju i Istočne Trakije prije potpisivanja Sèvreskog ugovora. Prema članku Nacionalna borba u TDV, grčka vojska 20. jula zauzela je cijelu Trakiju; taj je razvoj dva dana kasnije naveo padišaha u Istanbulu da sazove Saltanatsko vijeće. Kırklareli je okupiran 26. jula, a i Edirne je istog mjeseca ušlo pod grčku upravu.", "4c68dd1f"]},
"OLAYLAR_P0057:1920-07-28:0":{"b": ["Crvena armija ušla u Nahčivan", "6dcb9005"], "d": ["Englezi, koji su početkom 1919. ušli u oblast, raspustili su Araksku republiku i u ljeto iste godine napustili Nahčivan. Prema članku Nahčivan u TDV, Crvena armija je 28. jula 1920. ušla u Nahčivan, vlast dala komunistima i osnovana je Nahčivanska Sovjetska Socijalistička Republika. Status oblasti utvrđen je ugovorom potpisanim u Karsu 1921. kao autonomne jedinice vezane za Azerbejdžan.", "bc49ebba"]},
"OLAYLAR_P0057:1920-08-29:0":{"b": ["Grčka okupacija Ušaka", "74ad2713"], "d": ["Grčka vojska, da bi nametnula Sèvreski ugovor koji Ankara nije priznavala, nastavila je napredovanje. Prema člancima Ušak i Nacionalna borba u TDV, nakon Gediza 29. augusta 1920. okupiran je i Ušak. Mustafa Kemal-paša je oko mjesec dana prije te okupacije obišao jedinice Nacionalnih snaga u gradu.", "b7c70a40"]},
"OLAYLAR_P0057:1920-10-25:0":{"b": ["Grčka okupacija İnegöla i Jenišehira", "4a0460e7"], "d": ["Grčke jedinice u Bursi počele su napredovati na istok, u pravcu Eskišehira. Prema članku Nacionalna borba u TDV, 25. oktobra 1920. zauzeti su İnegöl i Jenišehir. Kada se shvatilo da se grčko napredovanje ne može zaustaviti milicijskim snagama, Zapadni front reorganiziran je na osnovi regularne vojske.", "53e977e3"]},
"OLAYLAR_P0057:1921-01-01:0":{"b": ["Kraj italijanske okupacije Burdura (godina)", "609123c8"], "d": ["Burdur, koji su Italijani okupirali 28. juna 1919, prema članku Burdur u TDV doživio je kratkotrajnu italijansku okupaciju između 1919. i 1921. Izvor ne navodi dan evakuacije; na karti okupacija završava početkom 1921. Italija se u ljeto 1921. potpuno povukla iz okupacione zone u Anadoliji.", "0ac33ff9"]},
"OLAYLAR_P0057:1921-03-23:0":{"b": ["Druga ofanziva grčke vojske — okupacija Bilecika, Afjona i Adapazarija", "9ae146e2"], "d": ["Grčka vojska, koja je nakon poraza u Prvoj bici na Ineniju iskrcala nove snage u Izmir, ponovo je krenula u ofanzivu prije isteka roka koji je priznala Londonska konferencija. Prema članku Nacionalna borba u TDV, Grci su 23. marta okupirali Bilecik i Afjon. Na sjeveru je i Adapazari 25. marta pao pod grčku okupaciju.", "7d247e77"]},
"OLAYLAR_P0057:1921-03-28:0":{"b": ["Turske snage ispraznile Batum", "ba5745dc"], "d": ["Englezi su se, povlačeći se s Kavkaza u julu 1920, povukli iz Batuma, a grad je preuzela gruzijska vlada. Prema članku Batum u TDV, Moskovski ugovor potpisan sa Sovjetskom Rusijom 16. marta 1921. prepustio je Batum Gruziji. Turske snage ispraznile su grad 28. marta 1921. i Batum je postao središte Autonomne Republike Adžarije osnovane unutar Gruzije.", "9555d8e0"]},
"OLAYLAR_P0057:1921-04-07:0":{"b": ["Povrat Afjona — bitke kod Aslihanlara", "2bbba17b"], "d": ["Nakon grčke ofanzive zaustavljene 1. aprila u Drugoj bici na Ineniju, na južnom frontu Afjon je povraćen 7. aprila. Članak Nacionalna borba u TDV to sažima ovako: 'kod Aslihanlara im je nanesen težak poraz i 7. aprila povraćen je Afjon'; no radovi iz vojne historije sukobe kod Aslihanlara i Dumlupinara stavljaju nakon evakuacije Afjona, između 8. i 15. aprila, i pišu da je taktička nadmoć ostala na grčkoj strani — dva kazivanja se ne slažu, navedena su oba. Pobjeda na Ineniju proslavljena je mitinzima u cijeloj zemlji, prije svega u Istanbulu.", "3525b97a"]},
"OLAYLAR_P0057:1921-06-28:0":{"b": ["Oslobođenje Izmita — nakon Adapazarija", "cec60e36"], "d": ["Adapazari, koji je u martu 1921. pao pod grčku okupaciju, prema članku Adapazari u TDV povraćen je 21. juna. Prema članku Izmit u TDV, Izmit, koji su 6. jula 1920. okupirali najprije Englezi, a zatim Grci, oslobođen je 28. juna 1921. Napuštajući grad, Grci su spalili čaršijski dio.", "da5f0806"]},
"OLAYLAR_P0057:1921-07-05:0":{"b": ["Oslobođenje Muğle od italijanske okupacije", "143ddf98"], "d": ["Italija je u ljeto 1921. počela povlačenje iz svoje okupacione zone u Anadoliji; evakuacija Antalije počela je 1. juna. Prema članku Muğla u TDV, Muğla, od 23. jula 1919. pod italijanskom okupacijom, oslobođena je 5. jula 1921.", "84bff82f"]},
"OLAYLAR_P0057:1921-07-20:0":{"b": ["Evakuacija Eskišehira — grčka vojska ušla u Eskišehir, Kütahyu i Bilecik", "a948a74d"], "d": ["Turska vojska, zatečena nespremna u bitkama kod Kütahye i Eskišehira, po naređenju Mustafe Kemal-paše povukla se istočno od Sakarje. Prema člancima TDV, Grci su 20. jula 1921. ušli u Eskišehir, 21. jula u Kütahyu, 22. jula u Bilecik. Grčki kralj Konstantin 28. jula u Kütahyi predsjedavao je ratnim vijećem i vojska se pripremala za ofanzivu u pravcu Ankare.", "29f7f871"]},
"OLAYLAR_P0057:1922-04-29:0":{"b": ["Povlačenje italijanskih jedinica iz Marmarisa i Kušadasija", "1d672994"], "d": ["Italijani, koji su od maja 1919. bili na jugozapadnim obalama Anadolije, nakon zbližavanja s vladom u Ankari postepeno su ispraznili okupacionu zonu. Antalija i Bodrum ispražnjeni su u ljeto 1921; posljednje italijanske jedinice krajem aprila 1922. otišle su i iz Kušadasija i Marmarisa.", "f956076c"]},
"OLAYLAR_P0057:1922-08-26:0":{"b": ["Počela Velika ofanziva", "efba4bd3"], "d": ["Nakon godinu dana priprema poslije Sakarje turska vojska krenula je u opću ofanzivu na afjonskom frontu. Prema člancima Nacionalna borba i Kütahya u TDV, Velika ofanziva počela je ujutro 26. augusta 1922. iz Afjona i otpor grčke vojske ubrzo je slomljen.", "7eaf426f"]},
"OLAYLAR_P0057:1922-08-27:0":{"b": ["Oslobođenje Afjona", "beaeef23"], "d": ["Drugog dana ofanzive grčki front probijen je pred Afjonom. Prema članku Afjonkarahisar u TDV, na kraju Velike ofanzive, kojom je komandovao sam Atatürk, grčke snage su razbijene i grad je oslobođen 27. augusta 1922. Taj se dan slavi kao dan oslobođenja Afjona.", "bfb4dd98"]},
"OLAYLAR_P0057:1922-08-30:0":{"b": ["Bitka vrhovnog komandanta — oslobođenje Kütahye", "376d3118"], "d": ["Glavnina grčke vojske opkoljena je između Afjona i Dumlupinara. Prema članku Nacionalna borba u TDV, operacija opkoljavanja dovršena je 30. augusta Bitkom vrhovnog komandanta, kojom je lično rukovodio vrhovni komandant Mustafa Kemal-paša. Prema članku Kütahya u TDV, istog dana jedna konjička divizija oslobodila je Kütahyu, koju su grčke snage u povlačenju spalile i razorile.", "6ecd76e4"]},
"OLAYLAR_P0057:1922-09-01:0":{"b": ["Oslobođenje Ušaka", "0f2d44d1"], "d": ["Nakon Bitke vrhovnog komandanta ostaci grčke vojske povukli su se na zapad, prema Izmiru. Prema članku Ušak u TDV, Ušak, od 29. augusta 1920. pod okupacijom, oslobođen je ulaskom nacionalnih snaga u grad 1. septembra 1922. U požaru koji su izazvale okupacione snage u povlačenju izgorjelo je oko tri četvrtine grada.", "ea4dc034"]},
"OLAYLAR_P0057:1922-09-02:0":{"b": ["Oslobođenje Eskišehira", "f442de5c"], "d": ["Na sjevernom krilu Velike ofanzive grčke snage bile su prisiljene napustiti i Eskišehir. Prema članku Eskišehir u TDV, grad, od 20. jula 1921. pod okupacijom, nakon pobjede od 30. augusta oslobođen je 2. septembra 1922. Na kraju trinaestomjesečne okupacije čaršijski dio bio je spaljen, a grad napola razoren.", "3b15a7c5"]},
"OLAYLAR_P0057:1922-09-06:0":{"b": ["Oslobođenje Bilecika", "35dbd49b"], "d": ["Prema članku Bilecik u TDV, grad je tokom Nacionalne borbe tri puta padao pod grčku okupaciju; treća okupacija, započeta 22. jula 1921, okončana je 6. septembra 1922. U požaru koji su grčke snage izazvale napuštajući grad izgorio je veći dio kuća, dućana i vladine zgrade.", "28e74c34"]},
"OLAYLAR_P0057:1922-09-07:0":{"b": ["Oslobođenje Ajdina", "ef1280b5"], "d": ["S približavanjem turske vojske Izmiru povukle su se i grčke snage u dolini Meandra. Prema članku Ajdin u TDV, grad su 7. septembra 1922, djelimično razoren i s veoma smanjenim stanovništvom, oslobodile turske snage. Grci u povlačenju spalili su veliki dio grada.", "358e3333"]},
"OLAYLAR_P0057:1922-09-11:0":{"b": ["Povrat Burse", "6ad1da0b"], "d": ["Nakon oslobođenja Izmira turska vojska napredovala je na sjever, prema obalama Marmare. Prema članku Bursa u TDV, grad, od 8. jula 1920. pod grčkom okupacijom, povraćen je 10-11. septembra 1922. Marš vojske odavde prema Čanakkaleu uznemirio je Engleze i otvorio put pregovorima u Mudanyi.", "caa09d48"]},
"OLAYLAR_P0057:1922-11-10:0":{"b": ["Preuzimanje Istočne Trakije — Kırklareli i Tekirdag", "2a08d65c"], "d": ["Mudanijsko primirje predviđalo je da grčka vojska isprazni Istočnu Trakiju i preda je Turskoj; Refet-paša, zadužen da preuzme Trakiju, 19. oktobra stigao je u Istanbul. Prema TDV, Kırklareli, od 26. jula 1920. pod okupacijom, povraćen je 10. novembra 1922, a Tekirdag je po primirju vraćen Turcima 13. novembra. Tako je Istočna Trakija pripojena turskim teritorijima bez borbe.", "cb085872"]},
"OLAYLAR_P0057B:1431-01-01:0":{"b": ["Najstariji sačuvani tahrir defter — Defter sandžaka Arvanid", "06981f02"], "d": ["Najstariji sačuvani primjerak popisa tahrira, koji su bilježili poreske obveznike, njihova domaćinstva, zemlju i proizvode, jeste Defter sandžaka Arvanid iz 835. (1431.). Popisne komisije upoređivale su stare zapise sa stanjem na terenu, u defter su upisivale nove punoljetne, a brisale umrle. Čini se da je postupak vođenja deftera postojao već u XIV. stoljeću; sistem se tokom XVI. stoljeća u većini ejaleta redovno obnavljao.", "df6b854c"]},
"OLAYLAR_P0057B:1520-01-01:0":{"b": ["Smrt historičara Nešrija", "d30aaa5c"], "d": ["Historičar Nešri, koji je u doba Bajazida II bio muderis u Bursi, prema TDV-u umro je vjerovatno nakon stupanja na prijestolje sultana Sulejmana Zakonodavca, 926. (1520.) ili 927. (1521.). Kako nije postojalo historijsko djelo na turskom, od njegovog Kitab-i Džihannuma do danas su sačuvani samo dijelovi o predislamskoj turskoj historiji i o osmanskoj historiji. TDV ga smatra prvim osmanskim historičarem koji je upoređivao izvore i nastojao objasniti događaje uzročno-posljedičnom vezom.", "eae3b6db"]},
"OLAYLAR_P0057B:1574-01-01:0":{"b": ["Ured darussaade-age odvojen je od ureda babussaade-age i postao samostalna funkcija", "1adb7dd9"], "d": ["Abesinac Mehmed-aga, koristeći ovlaštenja koja su mu data, odvojio je ured darussaade-age od ureda babussaade-age (Enderuna) i uzeo titulu darussaade-age. Ta funkcija, na čelu haremskih aga, imala je ovlaštenja koja su sezala od nadzora nad vakufima Haremejna do dvorske riznice i državnih poslova. Od XVII. stoljeća u toj su funkciji crni eunusi (karaage) prevladali nad bijelim eunusima (akage).", "6196bf6d"]},
"OLAYLAR_P0057B:1648-01-01:0":{"b": ["Evlija Čelebija zabilježio je da je broj radionica keramičkih pločica u Izniku spao na devet", "93ec22f1"], "d": ["Evlija Čelebija, koji je vidio Iznik 1648., napisao je da je u gradu, najvažnijem keramičkom središtu carstva, broj radionica keramičkih pločica spao na devet; gradska industrija pločica zacijelo je otprilike tada počela nazadovati. Prema istom zapažanju, unutar zidina bilo je osamnaest mahala i 600 dućana. TDV ne navodi jedan i siguran uzrok propadanja.", "c052c4ea"]},
"OLAYLAR_P0057B:1702-01-01:0":{"b": ["Naima kao vakanuvis predao je svoju historiju Amdžazade Husein-paši", "efe67a72"], "d": ["Dvorskog pisara iz Alepa Mustafu Naimu je Amdžazade Husein-paša prije 1114. (1702.) postavio za vakanuvisa i iste godine on je svoje djelo predao paši. Rašireno mišljenje da je bio prvi zvanični državni historičar potkrepljuje to što ga njegov nasljednik Rašid-efendija spominje kao vakanuvisa. Ravzatu'l-Husejn, plod tog rada, obuhvata otprilike godine 1592-1660.", "d32ee435"]},
"OLAYLAR_P0057B:1734-01-01:0":{"b": ["Naimina historija (Ravzatu'l-Husejn) štampana je u Muteferikinoj štampariji", "880152ff"], "d": ["Nakon Naimine smrti, Ravzatu'l-Husejn, u narodu poznat kao Naimina historija, štampao je 1147. (1734.) Ibrahim Muteferika u dva velika toma i 500 primjeraka. Predgovor koji je Muteferika napisao na početku prvog toma ponavljao se i u kasnijim izdanjima. Djelo je jedna od prvih velikih historijskih knjiga na turskom štampanih u štampariji.", "81dabf05"]},
"OLAYLAR_P0057B:1756-12-22:0":{"b": ["Smrt prijestolonasljednika šehzade Mehmeda — tvrdnja o trovanju je sporna", "b0f6beef"], "d": ["Umro je šehzada Mehmed, sin Ahmeda III i prijestolonasljednik, i njegova je smrt otvorila put prijestolju njegovom bratu Mustafi III. Dva članka TDV-a razilaze se u pogledu te smrti: članak «Mustafa III» piše da je šehzada umro iznenada i sumnjivo, vjerovatno od trovanja; članak «Osman III» piše da je smrt bila od bolesti i smatra dokazom neosnovanosti optužbe to što je Köse Mustafa-paša u kasnijem razdoblju postao kandidat za velikog vezira i zeta. Atlas ne bira nijedno od dva mišljenja.", "81f9c156"]},
"OLAYLAR_P0058:1339-01-01:0":{"b": ["Eretna sebi potčinio krajeve Tokata, Kayserija i Samsuna", "4a088f9f"], "d": ["Emir Eretna, koji je kao ilhanatski namjesnik stekao moć u Anadoliji, nakon što je ponovo zadobio podršku memlučkog sultana el-Nasira Muhammeda, 1339. proširio je granice i potčinio sebi krajeve Tokata, Kayserija i Samsuna. U tom je periodu pod eretninsku upravu ušao i kraj Zamanti istočno od Kayserija. Bejluk je 1341, smrću el-Nasira, proglasio nezavisnost.", "5be963a4"]},
"OLAYLAR_P0058:1360-01-01:0":{"b": ["Dulkadirovićki Halil-beg proširio granice do Zamantija", "aa911e87"], "d": ["Na eretninske teritorije, oslabljene time što je na čelo Eretninog bejluka došao maloljetni Mehmed-beg, s juga su se pojačali turkmenski upadi. Godine 1360. dok je Omer-beg, jedan od turkmenskih poglavara, zauzimao Malatyu, Dulkadiroglu Halil-beg proširio je granice svog bejluka do Zamantija istočno od Kayserija. Tako je kraj Zamanti između Elbistana i Kayserija prešao u ruke Dulkadirovića i bejluk je tu oblast držao do osmanske aneksije 1515.", "6f54371d"]},
"OLAYLAR_P0058:1394-01-01:0":{"b": ["Bajazid I Munja ponovo strogo opsjeo Istanbul", "244834ca"], "d": ["Istanbul, od 1391. povremeno u blokadi, u proljeće 1394. Bajazid I Munja ponovo je podvrgao strogoj opsadi. Odnos s Bizantom, koji je od 1371. Osmanlijama plaćao harač i slao vojnu pomoć, tako se pretvorio u otvoreno neprijateljstvo. Opsada je dignuta pojavom Timurove opasnosti i bitkom kod Ankare 1402.", "c3af0f1d"]},
"OLAYLAR_P0058:1424-02-22:0":{"b": ["Mir Murata II s Bizantom — Bizant ponovo pristao plaćati harač", "6474d704"], "d": ["Murat II, koji je 1422. opsjeo Istanbul zbog Bizanta koji je podržavao Lažnog Mustafu, 22. februara 1424. potpisao je mirovni ugovor s bizantskim carem. Tim je ugovorom Bizant ponovo pristao Osmanlijama plaćati harač i pristao vratiti mjesta na obalama Marmare, Egeja i Crnog mora koja je uzeo nakon 1402, osim tvrđava Silivri i Terkos; tako se vratio godišnji harač kojeg se oslobodio ugovorom sa šehzadom Sulejman-čelebijom 1403. Bizant je to stanje zadržao do osvajanja Istanbula 1453.", "dd19c749"]},
"OLAYLAR_P0058:1514-10-23:0":{"b": ["Preuzete od Safavida tvrđave Bajburt i Kigi — Erzindžan i Bajburt dati Bijikli Mehmed-begu", "2c7fd65e"], "d": ["Dok je Selim Javuz, vraćajući se iz Tabriza nakon pobjede kod Čaldirana, bio u taboru, stigle su vijesti o preuzimanju tvrđava Bajburt i Kigi. Trapezuntski sandžakbeg Bijikli Mehmed-beg i janinski sandžakbeg Mustafa-beg u oktobru 1514. zauzeli su Bajburt, koji je branio Kara Maksud-i Sultani, jedan od emira šaha Ismaila. Erzindžan, koji je bez borbe ušao pod osmansku vlast, zajedno s Bajburtom 23. oktobra 1514. dat je kao beglerbegluk Bijikli Mehmed-begu, a Bajburt je pretvoren u sjedište sandžaka.", "d3796513"]},
"OLAYLAR_P0058:1514-11-24:0":{"b": ["Selim Javuz se s tabriskog pohoda vratio u Amasyu i tu prezimio", "49d51f94"], "d": ["Selim Javuz, koji je u Tabrizu ostao devet dana, zbog nestašice hrane i nespremnosti vojske odustao je od zimovanja u Iranu i vratio se preko Karsa i Bajburta. Padišah je Ramazanski bajram proveo u Niksaru, a zatim stigao u Amasyu i tu prezimio. Sljedeće godine namjeravao je ponovo krenuti na Safavide; u Amasyi je počeo pritisak janjičara za povratak u Istanbul, a pohod se u proljeće 1515. nastavio osvajanjem Kemaha.", "2693e398"]},
"OLAYLAR_P0059:1594-11-13:0":{"b": ["Vlaška, Moldavija i Erdelj zajedno se pobunili protiv Osmanlija", "e71d3ee9"], "d": ["Sredinom 1594. tri vojvodstva sjeverno od Dunava — Vlaška, Moldavija i Erdelj — odlučila su zajednički djelovati protiv Osmanlija. Moldavski vojvoda Aron Tiran pridružio se Svetoj ligi koju su osnovali austrijski car i papa Klement VIII i potčinio se Erdeljskoj kneževini; vlaški vojvoda Mihai Viteazul pridružio se pokretu zbog nezadovoljstva teškim poreskim teretom. Dana 13. novembra 1594. u Vlaškoj i Moldaviji počeli su istovremeni ustanci protiv osmanske uprave, a uz podršku Erdelja pokret se prelio južno od Dunava, prema osmanskim teritorijima. Prema Enciklopediji islama TDV, taj je trojni savez otvorio sjeverni front Dugog osmansko-habsburškog rata (1593-1606), koji je trajao istih godina.", "30f44add"]},
"OLAYLAR_P0060:1723-01-01:0":{"b": ["Ruske snage iskrcale su se u Enzeliju i smjestile u Reštu — početak okupacije Gilana", "15f9a0f2"], "d": ["Nakon zauzimanja Derbenta, ruski desantni odred od hiljadu ljudi koji je došao iz Astrahana iskrcao se u zaljevu Enzeli i, na poziv namjesnika Rešta, koji je tražio pomoć protiv Afganaca, smjestio se u gradu. Ostatak Gilana zauzet je do maja 1723. Osmanska vojska je pak istog proljeća preko Tbilisija ušla na Kavkaz; dva carstva napredovala su s dva različita kraja u rastrgnutu safavidsku zemlju.", "f4cbd759"]},
"OLAYLAR_P0060:1725-01-01:0":{"b": ["Ruske snage okupirale su Lahidžan — najistočnija tačka u Gilanu", "3d874b31"], "d": ["Rusi u Gilanu nikada nisu mogli preći dalje od Lahidžana; grad je okupiran 1725. Mazandaran i Astarabad, prepušteni Petrogradskim ugovorom, nikada faktički nisu prešli u ruske ruke. Iste godine osmanska vojska zauzela je Tabriz i Gandžu i tako dovršila svoj udio u Azerbejdžanu.", "a350db52"]},
"OLAYLAR_P0060:1732-09-02:0":{"b": ["Ruske snage napustile su Gilan i Tališ — Levašov je prešao Kuru", "9503be07"], "d": ["Kako je isticao rok predaje iz Reštskog ugovora, ruski gilanski korpus povukao se iz Gilana i Tališa i prešao na sjever od rijeke Kure; samo u Gilanu od januara do marta 1732. od bolesti je umrlo više od hiljadu vojnika. Rusko prisustvo na obali sada se svodilo na područje sjeverno od Kure, Baku i Derbent; i oni su vraćeni Gandžanskim ugovorom 1735.", "ec20f6a3"]},
"OLAYLAR_P0063:1724-09-11:0":{"b": ["Uništen je ruski bataljon u Salijanu — Tahmasbove jedinice ušle su na ušće Kure", "f0b425c9"], "d": ["Oficiri ruskog bataljona koji se nakon zauzimanja Bakua smjestio na ušću Kure ubijeni su na gozbi koju je priredio salyanski naib; preostala jedinica povukla se u Baku, a u Salijan je ušla jedinica Tahmaspa II od oko četiri hiljade ljudi. Rusi su se u taj kraj mogli vratiti tek nekoliko godina kasnije, sami postavivši naiba. To je jedan od rijetkih događaja u doba okupacije u kojima su Rusi unutar Irana potisnuti oružjem.", "375630fa"]},
"OLAYLAR_P0063:1734-05-31:0":{"b": ["Nadirova prijetnja ruskom poslaniku Golicinu: ako se ne predaju kaspijske pokrajine i Derbent, sporazumjet će se s Osmanlijama", "f8fec4a7"], "d": ["Nadir, koji je pred Erivanom porazio osmansku vojsku, odbio je rusku ponudu pomoći i poručio da će, ako Rusija odmah ne vrati pokrajine na kaspijskoj obali i Derbent izvan Reštskog ugovora, sklopiti zaseban mir s Osmanlijama. Petrograd je, uoči novog rata s Osmanlijama, ustuknuo kako Iran ne bi gurnuo na suprotnu stranu.", "89b8c85e"]},
"OLAYLAR_P0063:1734-11-09:0":{"b": ["Ruska naredba o povlačenju — napustit će se svi položaji od Bakua, Nizovaje i Kure do Derbenta", "79a068ef"], "d": ["Naredba carice Ane nalagala je da se ruske snage najprije povuku iz Bakua i tvrđave Nizovaja u Derbent, a da se Derbent i preostale pokrajine napuste kada to godišnje doba dopusti. Nadirov pritisak dao je rezultat i prije ugovora.", "9ad1e7fc"]},
"OLAYLAR_P0063:1735-01-01:0":{"b": ["Upućivanje krimskih snaga preko Kabarde u Iran — ruski protest i povod za rat", "e2356781"], "d": ["Krimskim snagama naređeno je da radi potpore osmanskoj vojsci na iranskoj granici prođu kroz kabardinsku oblast na Kavkazu. Rusija je protestirala protiv te naredbe, tvrdeći da te zemlje pripadaju njoj. Iako je naredba povučena, Rusi su to iskoristili kao povod i u proljeće 1736. napali Azov; pravi cilj bio je povratiti Azov i izaći na Crno more.", "e31f4da0"]},
"OLAYLAR_P0063:1735-05-01:0":{"b": ["Predaja Bakua Iranu", "5c6fa266"], "d": ["Prema uslovu Gandžanskog ugovora o evakuaciji u roku od dva mjeseca, ruski zapovjednik de Brilly predao je Baku Musa-hanu, koji je došao preuzeti grad.", "68a77e77"]},
"OLAYLAR_P0063:1735-05-08:0":{"b": ["Predaja Derbenta Iranu — kraj trinaestogodišnje ruske okupacije", "ad7b20ab"], "d": ["Ključevi Derbenta predani su iranskoj strani; neke ruske jedinice ostale su još neko vrijeme u gradu. Tako je ruska okupacija, koja je počela 1722., okončana bez ijedne velike bitke, zbog želje Rusije da uoči novog rata s Osmanlijama zadrži Nadira kao saveznika.", "a72d286a"]},
"OLAYLAR_P0063:1735-07-09:0":{"b": ["Predaja Gandže Nadiru", "1b50eb22"], "d": ["Nadir, koji je na Arpačaju porazio osmansku vojsku, nekoliko sedmica kasnije zauzeo je Gandžu, okruženu snažnim zidinama i trima jarcima. Grad koji su Osmanlije uzele 1725. ponovo je postao iranski; Karabah je ugovorom iz 1736. prepušten Iranu.", "03fc4c7d"]},
"OLAYLAR_P0063:1735-08-12:0":{"b": ["Tbilisi prelazi iranskim jedinicama", "c463de93"], "d": ["Nakon Nadirovog jačanja iranske jedinice ponovo su zauzele Tbilisi i za namjesnika Kartlije-Kahetije postavile Ali Mirzu. Nadir je promijenio tamošnje osmansko upravno uređenje; Kartlijom je upravljao neposredno preko iranskog namjesnika, a 1744. dao ju je Tejmurazu.", "3a18c7c0"]},
"OLAYLAR_P0063:1735-08-23:0":{"b": ["Rušenje tvrđave Sveti krst — ruska granica povučena na Terek, osnovana tvrđava Kizljar", "1bb1117b"], "d": ["Nakon Reštskog i Gandžanskog ugovora nova ruska granica postala je rijeka Terek; odlučeno je da se poruši tvrđava Sveti krst na Sulaku i Levašov je u augustu 1735. izvijestio o rušenju. Iste godine Levašov je na Tereku odabrao mjesto za tvrđavu Kizljar; tako se rusko prisustvo na dagestanskoj obali, koje je trajalo od 1722., povuklo na sjever od Tereka.", "85373e75"]},
"OLAYLAR_P0063:1736-05-02:0":{"b": ["Odluka o ratu s Rusijom — zbog ruskog napada na Azov", "d19f8545"], "d": ["Kada su Rusi u zu-l-ka'de 1148. (mart 1736.) napali tvrđavu Azov i krenuli na Or-Kapu, osmanska vlada je na sazvanom divanu, i uz podsticaj francuskog poslanika Villeneuvea, bila prisiljena donijeti odluku o ratu protiv Rusije. Veliki vezir Sejid Mehmed-paša imenovan je za serasera vojske. Rusija se Gandžanskim ugovorom iz marta 1735. oslobodila iranskog fronta i ponovo stavila na dnevni red cilj izlaska na Crno more.", "a65d5ca0"]},
"OLAYLAR_P0063:1736-06-01:0":{"b": ["Predaja Or-Kape Münnichu — ruska vojska ušla je na Krim", "af2b2613"], "d": ["Münnich je 16. maja (po julijanskom) stigao pred linije Or-Kape i 20. maja u zoru izvršio juriš na linije; tatarska vojska, iznenađena, povukla se, a tvrđava Or predala se sljedećeg dana. Ruska vojska dva dana kasnije krenula je u unutrašnjost poluotoka; Or-Kapa je do kraja augusta ostala u ruskim rukama.", "3fec9485"]},
"OLAYLAR_P0063:1736-06-19:0":{"b": ["Predaja tvrđave Kilburun Leontjevu", "a0600527"], "d": ["Leontjevljeva kolona, koju je Münnich odvojio dok je napredovao po Krimu, uputila se prema Kilburunu na ušću Dnjepra i tvrđava se predala. Budući da izvor ne navodi dan kada su se ruske snage povukle iz tvrđave, na karti se ne prikazuje prozor okupacije.", "c1632ebd"]},
"OLAYLAR_P0063:1736-07-13:0":{"b": ["Pad Azova u ruke Rusa", "004b5ef1"], "d": ["Na kraju napada koji je počeo u martu 1736., tvrđava Azov na ušću Dona pala je u ruke Rusa. Istog ljeta Rusi su prošli Or-Kapu i ušli na Krim, zauzeli Gözleve i Kilburun i počinili pustošenja u Bahčisaraju i Akmesdžidu. Azov je mirom 1739. ostao Rusiji, ali su mu utvrđenja porušena. Izvori se razilaze oko dana pada: TDV navodi taj datum zajedno s Gözleveom, Or-Kapom i Kilburunom; ruski izvori navode 19. juni (30. juni po gregorijanskom), a jedan drugi izvor 1. juli.", "fccaab17"]},
"OLAYLAR_P0063:1736-08-27:0":{"b": ["Münnich je porušio liniju Or-Kape i povukao se s Krima", "84ee7e5c"], "d": ["Münnich, koji se iz unutrašnjosti Krima vratio do Or-Kape, ondje je ostao pet sedmica. Zbog nestašice hrane i bolesti koje su se širile u vojsci, dao je porušiti utvrdnu liniju Perekopa i povukao se u Ukrajinu; kada su Rusi otišli, Tatari su liniju obnovili.", "d453b2eb"]},
"OLAYLAR_P0063:1737-07-14:0":{"b": ["Austrija je objavila rat Osmanlijama — drugi front uz Rusiju", "c27ed99a"], "d": ["Austrija, saveznica Rusije, u junu 1737., iako su u Nemirovu bili dogovoreni mirovni pregovori, napala je u tri pravca osmanske zemlje; careva zvanična objava rata datirana je 14. jula 1737. Seckendorf je u julu zauzeo Niš, ali je austrijska bosanska operacija u augustu zaustavljena kod Banje Luke. Taj front zatvoren je Beogradskim mirom 1739. austrijskim gubitkom.", "7d5518a3"]},
"OLAYLAR_P0063:1737-07-25:0":{"b": ["Lacyjeva prethodnica zauzela je i spalila Karasubazar", "ee36541f"], "d": ["Lacy, koji je prešao Sivaš i ušao na Krim, 12. jula (po julijanskom) odbio je hanov napad. Dva dana kasnije general Douglas na čelu prethodnice rastjerao je tatarski logor pred Karasubazarom, bez otpora zauzeo grad i spalio ga. Lacy je sljedećeg dana počeo povlačenje.", "ac1fd466"]},
"OLAYLAR_P0063:1737-07-27:0":{"b": ["Pad Niša u ruke Austrije — Seckendorfov pohod na Srbiju", "084a31e8"], "d": ["Srbijanski krak austrijske vojske, koja je u ljeto 1737. u tri pravca ušla u osmanske zemlje, pod komandom maršala Seckendorfa spustio se dolinom Morave na jug i zauzeo Niš. Pad tvrđave bio je jedini veliki uspjeh Austrije u tom ratu; međutim, u oktobru iste godine rumelijski beglerbeg Ćuprilizade Hafiz Ahmed-paša povratio je Niš bez borbe.", "5fd4065d"]},
"OLAYLAR_P0063:1737-10-16:0":{"b": ["Povratak Niša od Austrije", "265e0917"], "d": ["Niš, koji je austrijska vojska pod komandom Seckendorfa zauzela u rebiu-l-evvelu 1150. (juli 1737.), u oktobru iste godine povratio je rumelijski beglerbeg Ćuprilizade Hafiz Ahmed-paša. To je, nakon Banje Luke, bio drugi događaj koji je osujetio austrijsku operaciju iz 1737.", "2f62abcc"]},
"OLAYLAR_P0063:1738-08-17:0":{"b": ["Zauzimanje Ada Kaleha od Austrije", "24f58282"], "d": ["Osmanska vojska koja je u proljeće 1738. krenula u pohod zauzela je Mehadiju, opsjela Oršavu i Ada Kaleh i, prešavši Dunav, vršila prodore prema Temišvaru. Ada Kaleh zauzet je 17. augusta 1738. Zatim je Jegen Mehmed-paša, koji je stigao u Niš, poduzimao prodore prema Beogradu; godinu dana kasnije uslijedili su pobjeda kod Hisarčika i Beogradski mir.", "9b408b77"]},
"OLAYLAR_P0065:1770-08-12:0":{"b": ["Jedisanski i budžački Nogajci prelaze pod rusku zaštitu", "54c9791c"], "d": ["Dok je trajala opsada Bendera, ruski zapovjednik Panin potpisao je sporazum s uglednicima jedisanske i budžačke nogajske horde. Nogajci su objavili da se odvajaju od Osmanske države i prelaze pod zaštitu ruske carice. Oko dvanaest hiljada Nogajaca iselilo se iz Budžaka; horde su 1771-1772. naseljene na desnoj obali rijeke Kubana. Prelaskom stepa sjeverno od Krima na rusku stranu otvoren je kopneni put prema poluotoku.", "8e87da5e"]},
"OLAYLAR_P0065:1771-06-26:0":{"b": ["Linija Or-Kape prelazi Rusima", "ae464560"], "d": ["Ruska vojska pod komandom Dolgorukova noćnim se prepadom merdevinama popela na lijevo krilo linije Or-Kape. U isto vrijeme konjica Prozorovskog prošla je plićacima Sivaša, izašla iza linije i razbila krimsko-osmansku konjicu. Sljedećeg dana garnizon tvrđave se predao; ruska vojska dva dana kasnije krenula je u unutrašnjost poluotoka.", "7efec9b9"]},
"OLAYLAR_P0065:1771-06-29:0":{"b": ["Pad tvrđave Arabat; Kerč, Jenikale i Taman prelaze u ruske ruke", "7784d628"], "d": ["Ruska kolona pod komandom Ščerbatova prešla je Genički moreuz preko mosta od čamaca koje je dovela Azovska flota i, prešavši oko sto versta duž Arabatske strelice, zauzela tvrđavu Arabat. U julu je ista kolona zauzela i Kerč, Jenikale i Taman. Tako su i obje obale Kerčkog moreuza došle pod rusku kontrolu.", "5c9efba7"]},
"OLAYLAR_P0067:1788-09-21:0":{"b": ["Bitka kod Sebeša (Karanšebeša) — noćno povlačenje austrijske vojske", "fcc530d0"], "d": ["Osmanske snage pod komandom vidinskog seraskera Ćehaje Hasan-paše porazile su vojsku Josipa II nakon Mehadije i kod Sebeša (Karanšebeša). Na vijećanju u čadoru serdar-i ekrema donesena je odluka o napadu na neprijateljski štab; dok su noću trajale pripreme, vidjelo se da su austrijske jedinice napustile položaje i povukle se u gradić Sebeš. Osmanske snage koje su ih gonile pritisnule su ih u gradiću; u požaru koji je izbio poginulo je mnogo vojnika, preživjeli su se sklonili u Lugoš (Lugoj), udaljen sedam sati, a zarobljeno je više od hiljadu ljudi. Sopstveni ratni dnevnik austrijske vojske istu noć bilježi kao paniku i vlastitu vatru; za poređenje dviju pripovijesti, dodatno štivo: karsi-karansebes-1788. Grad nije prešao u osmansko vlasništvo: zauzet je, spaljen i napušten 10. oktobra 1788. — zato se na karti ne vidi promjena granice.", "1b1d8ea5"]},
"OLAYLAR_P0068:1427-01-01:0":{"b": ["Knez Inal ujedinio je Kabardince pod jednom upravom", "34f01c9e"], "d": ["U kabardinskoj grani Čerkeza, koji su se nakon mongolsko-tatarskih invazija povukli na istok, knez Inal (1427-1456) ujedinio je veći dio naroda pod svojom upravom; kneževi Kabarde, Beslenejaca i Čemguja od njega izvode svoje porijeklo. Kabardinski begovi do kraja XVIII. stoljeća imali su utjecaj i na Čečene, Inguše, Karačajevce-Balkare i Osetine te na Abazine sjeverno od Kavkaskih planina. Datum je početak godina Inalove vladavine; dan ujedinjenja nije poznat.", "405949a2"]},
"OLAYLAR_P0068:1475-01-01:0":{"b": ["Čerkeska obala priznaje osmansku vlast", "c61a1859"], "d": ["Genovske kolonije na crnomorskoj obali, koje su nakon osvajanja Istanbula izgubile vezu sa Sredozemljem, po naredbi sultana Mehmeda II Osvajača došle su pod osmansku upravu: 1475. preko Gedik Ahmed-paše i 1479. preko Kasim-paše. Zajednice koje su živjele na obali između Tamana i Sočija, a koje osmanski izvori nazivaju \"Donjim Čerkezima\" (\"Aşağıra\"), priznale su osmansku vlast; obala je od tada tri stoljeća ostala pod osmanskom vlašću. To je priznavanje vlasti: plemena su zadržala svoj poredak, a mjesta koja su Osmanlije faktički držale bile su obalne tvrđave poput Anape, Sogudžaka, Gelendžika, Suhumija i Faša.", "b46e4e11"]},
"OLAYLAR_P0068:1563-01-01:0":{"b": ["Prva ruska tvrđava na Kavkazu: Terek", "5dcabb8e"], "d": ["Kabardinski knez Temrjuk, iscrpljen krimskim upadima i pohodima za robljem, 1557. i 1559. slao je poslanike u Moskvu i udao kćer za cara Ivana IV. Rusi, koji su potpisali sporazum s nekim kabardinskim kneževima, 1563. podigli su na obali rijeke Terek svoju prvu tvrđavu na Kavkazu. Osmanski padišah je u pismu poslanom 1570. tražio da se ruske tvrđave u Kabardi poruše; tvrđava je porušena 1574. To je pitanje saveza i tvrđave, a ne prelaska teritorije iz ruke u ruku — zato se na karti ne prikazuje nikakva promjena.", "f74fed71"]},
"OLAYLAR_P0068:1763-01-01:0":{"b": ["Rusija je u Kabardi sagradila tvrđavu Mozdok", "630428b1"], "d": ["U Kabardi, koju je Beogradski mir (1739.) ostavio neutralnom, počela je borba kneževa naklonjenih Osmanlijama i onih naklonjenih Rusiji. Koristeći tu zbrku, Rusija je, uprkos prigovoru Osmanske države i kabardinskih kneževa, 1763. dala podići tvrđavu Mozdok na obali Tereka. Tvrđava je kasnijih godina postala istočni kraj ruske utvrđene linije od Azova do Mozdoka i smatrana je jednim od uzroka rata 1768-74.", "deaad34c"]},
"OLAYLAR_P0068:1789-10-13:0":{"b": ["Beograd i Smederevo prelaze u ruke Austrije", "cf874516"], "d": ["U trećoj godini rata austrijski zapovjednik Laudon zauzeo je osmanske granične tvrđave uz Dunav. Smederevo se predalo 13. oktobra 1789. pod uslovom da se 300 vojnika garnizona povuče položivši oružje; Beograd, pedeset godina osmanska granična tvrđava, iste je jeseni pao u ruke Austrije. Laudon je između 1789. i 1791. dao podići šančeve koji su dominirali smederevskom tvrđavom i varoši. Oba grada Svištovskim mirom potpisanim 4. augusta 1791. vraćena su Osmanskoj državi; zato su na karti oba prikazana kao okupacija, a ne aneksija. Dan predaje Beograda ne spominje se ni u jednom od četiri pročitana članka TDV-a (članak navodi samo godinu); ovdje navedeni datum je dan Smedereva i za Beograd nije procjena, nego jedini poznati dan iste operacije.", "3ab6a49a"]},
"OLAYLAR_P0068:1861-06-13:0":{"b": ["Čerkezi su se sastali u Sočiju i zatražili pomoć od Osmanlija, Britanije i Francuske", "d7ae7762"], "d": ["Čerkezi, koji su nastavili rat s Rusima i nakon predaje šejha Šamila (1859.), sastali su se 13. juna 1861. u Sočiju i zatražili pomoć od Osmanske države, Britanije i Francuske. Pomoć nije došla; iste godine uz carevo odobrenje zvanično je odlučeno o progonu Čerkeza i 1861-1864. okupirane su zemlje Abzaha, Šapsuga i Ubiha. Stanovništvu je objavljeno da se u roku od mjesec dana naseli na mjesta koja će im se pokazati uz Kuban ili da se iseli u osmanske zemlje, u suprotnom će kao ratni zarobljenici biti protjerani u unutrašnjost Rusije.", "78005fcf"]},
"OLAYLAR_P0068B:1788-01-25:0":{"b": ["Melek Mehmed-paša razriješen vezirstva — uklanjanje pristalica mira", "a07e5755"], "d": ["Dok se pripremalo otvaranje drugog fronta rata, Melek Mehmed-paša je 25. januara 1788. razriješen vezirstva. Prema TDV-u, pravi razlog razrješenja bio je to što je veliki vezir Kodža Jusuf-paša htio udaljiti pristalice mira od državne uprave. Melek Mehmed-paša će na kraju rata, 4. maja 1792., biti postavljen za velikog vezira umjesto Kodža Jusuf-paše.", "f725e76a"]},
"OLAYLAR_P0068B:1788-02-22:0":{"b": ["Serdar-i ekrem Kodža Jusuf-paša kreće u pohod s neograničenim ovlaštenjima", "c16ecddb"], "d": ["U danima kada se otvorio rat na dva fronta, veliki vezir i serdar-i ekrem Kodža Jusuf-paša 22. februara 1788. krenuo je na čelu vojske iz Istanbula. Abdulhamid I dao mu je, prema izrazu TDV-a, široku samostalnost, tj. neograničena ovlaštenja, u rangu Ćuprilića. Time je vođenje i upravljanje ratom u cijelosti prepušteno serdaru.", "64341325"]},
"OLAYLAR_P0068B:1788-05-10:0":{"b": ["Džezairli Gazi Hasan-paša isplovljava s flotom na Crno more", "4dc6574c"], "d": ["Kapudan-paša Džezairli Gazi Hasan-paša 10. maja 1788. isplovio je s flotom na Crno more. Cilj je bio vršiti pritisak na liniju Očakov-Kilburun i slomiti nadmoć ruske flote na sjeveru Crnog mora; ta je operacija postala početak pomorskih okršaja koji su trajali cijelo ljeto.", "9bc90d70"]},
"OLAYLAR_P0068B:1788-08-01:0":{"b": ["Pomorska bitka kod Zmijskog otoka (Fidonisi)", "5c6a90c1"], "d": ["Džezairli Gazi Hasan-paša porazio je rusku flotu u bitki kod Zmijskog otoka vođenoj u augustu 1788. Međutim, taj uspjeh nije bio dovoljan da spasi tvrđave na sjeveru Crnog mora; krajem iste godine pao je Očakov.", "c850a910"]},
"OLAYLAR_P0068B:1789-01-01:0":{"b": ["Rusi zauzimaju Akerman", "48638c7c"], "d": ["Akerman su 1789. Rusi opsjeli i zauzeli; prema TDV-u, tvrđava je nakon 1770. po drugi put prešla u ruske ruke. Tajfur-pašu, koji je tvrđavu predao bez borbe, veliki vezir Džezairli Gazi Hasan-paša dao je pogubiti.", "3e4f5789"]},
"OLAYLAR_P0068B:1789-05-01:0":{"b": ["Poraz kod Galaca", "65e7a29d"], "d": ["Osmanske snage poražene su 1. maja 1789. kod Galaca. Taj poraz bio je prva karika u nizu poraza koji će se ponavljati cijelo ljeto kod Focşanija i Rimnika, i poljuljao je položaj serdar-i ekrema Kodža Jusuf-paše.", "28e100e0"]},
"OLAYLAR_P0068B:1789-06-07:0":{"b": ["Razrješenje Kodža Jusuf-paše s položaja velikog vezira", "54fdaa33"], "d": ["Poraz kod Galaca postao je vidljivi razlog uklanjanja Kodža Jusuf-paše s položaja velikog vezira 7. juna 1789. Umjesto njega postavljen je Ćehaja Hasan-paša, poznat po uspjesima na austrijskom frontu. U preostale tri godine rata položaj velikog vezira četiri će puta mijenjati nosioca.", "73d2aab3"]},
"OLAYLAR_P0068B:1789-08-01:0":{"b": ["Poraz kod Focşanija", "09430751"], "d": ["Osmanska vojska pretrpjela je 1. augusta 1789. kod Focşanija težak poraz od rusko-austrijskih snaga. Dva zasebna članka TDV-a taj dan navode jednako. Poraz će se ponoviti u septembru iste godine kod Rimnika i osmanska odbrana u Vlaškoj će se urušiti.", "a0cb033c"]},
"OLAYLAR_P0068B:1789-09-22:0":{"b": ["Poraz kod Rimnika (Boze)", "343edd1a"], "d": ["Osmanska vojska pretrpjela je 22. septembra 1789. težak poraz pri prijelazu rijeke Rimnik i potom na obali rijeke Boze. Taj drugi poraz, koji je došao sedam sedmica poslije Focşanija, faktički je razbio vlaški front i u oktobru i novembru doveo do predaje tvrđava na dnjestarskoj liniji: članak TDV-a o Kodža Jusuf-paši navodi predaju 'Izmaila' 11. oktobra i Bendera 14. novembra. Međutim, predaja Izmaila 1789. ne spominje se u članku TDV-a o Izmailu (tvrđava je 1790. još u osmanskim rukama), a i ESBE piše da su nakon Rimnika zauzeti samo Hadžibej i Akerman i da se Bender predao 3. novembra (po julijanskom; = 14. novembra); i TDV, članak o Akermanu, bilježi da su Rusi tvrđavu zauzeli 1789. Predaja od 11. oktobra najvjerovatnije je predaja Akermana — budući da se dan za Akerman nije mogao potvrditi u pročitanom izvoru, na karti se ne prikazuje zasebno.", "45226358"]},
"OLAYLAR_P0068B:1789-12-03:0":{"b": ["Postavljenje Džezairli Gazi Hasan-paše za velikog vezira i serdar-i ekrema", "37e10738"], "d": ["Nakon poraza u Vlaškoj i gubitaka tvrđava, ostarjeli zapovjednik flote Džezairli Gazi Hasan-paša 3. decembra 1789. postavljen je za velikog vezira i serdar-i ekrema. Tri zasebna članka TDV-a taj dan navode jednako. Njegov mandat trajat će kraće od četiri mjeseca.", "17c7e52e"]},
"OLAYLAR_P0068B:1790-01-01:0":{"b": ["Desant na Calafat i njegovo odbijanje", "f8bc2f38"], "d": ["Osmanske snage koje su krajem aprila 1790. krenule iz Vidina i preko Dunava se iskrcale na Calafat brzo su odbijene. Taj neuspjeli desant poklapa se s mjesecima kada je inicijativa na austrijskom frontu izašla iz osmanskih ruku i kada je počelo traganje za primirjem.", "09b57c17"]},
"OLAYLAR_P0068B:1790-03-30:0":{"b": ["Smrt serdar-i ekrema u taboru kod Šumena — kraj četveromjesečnog mandata velikog vezira", "ce61597b"], "d": ["Veliki vezir i serdar-i ekrem Džezairli Gazi Hasan-paša, stariji od osamdeset godina, preselio je 30. marta 1790. u taboru kod Šumena. Njegov mandat velikog vezira, koji je trajao tri mjeseca i dvadeset osam dana, poklopio se s najtežom ratnom zimom.", "7ff18e9d"]},
"OLAYLAR_P0068B:1790-04-16:0":{"b": ["Pad Stare Hârșove — kraj opsade koja je trajala cijelu zimu", "133fe352"], "d": ["Nakon teške opsade koja je trajala cijelu zimu, Stara Hârșova pala je 16. aprila 1790. u ruke austrijskih snaga. Istih dana odbijen je i osmanski desant s Vidina preko Dunava na Calafat.", "1dcb3252"]},
"OLAYLAR_P0068B:1790-06-08:0":{"b": ["Spuštanje austrijskih snaga do Đurđua i njihovo odbijanje", "6fbd373f"], "d": ["Austrijske snage spustile su se 8. juna 1790. uz Dunav do Đurđua, ali su ih osmanski vojnici odbili. Tri mjeseca kasnije na istom mjestu, u čadoru velikog vezira, potpisat će se primirje s Austrijom.", "63725445"]},
"OLAYLAR_P0068B:1790-09-06:0":{"b": ["Odluka istanbulskog vijeća o primirju — odustajanje od preduslova", "8cb6a44f"], "d": ["Vijeće koje se 6. septembra 1790. sastalo u Istanbulu odustalo je od preduslova postavljenih za pregovore s Austrijom. Ta odluka otvorila je put primirju koje će dvanaest dana kasnije biti potpisano u Đurđuu i dovela do toga da se rat na austrijskom frontu faktički okonča.", "f73026d8"]},
"OLAYLAR_P0068B:1790-09-19:0":{"b": ["Đurđevsko primirje — na austrijskom frontu utihnulo je oružje", "87915031"], "d": ["Primirje između Osmanske države i Austrije potpisano je 19. septembra 1790. u čadoru velikog vezira u Đurđuu. Primirje, koje će ostati na snazi devet mjeseci, zaustavilo je borbe na austrijskom frontu koje su trajale dvije i po godine i otvorilo put mirovnoj konferenciji u Svištovu.", "919d2742"]},
"OLAYLAR_P0068B:1790-09-21:0":{"b": ["Coburg potpisuje Đurđevsko primirje i razmjena tekstova", "56ce0fee"], "d": ["Tekst primirja potpisao je 21. septembra 1790. i austrijski vrhovni zapovjednik princ Coburg, a primjerci su uzajamno uručeni. Tako je primirje stupilo na snagu za obje strane.", "a6f60a94"]},
"OLAYLAR_P0068B:1790-12-30:0":{"b": ["Otvaranje mirovne konferencije u Svištovu", "ce5058cb"], "d": ["Osmanski i austrijski delegati prvi put su se sastali 30. decembra 1790. u Svištovu i uzajamno predali punomoći. Tako su počeli pregovori koji će trajati osam mjeseci i u jednom trenutku biti potpuno prekinuti.", "407808c4"]},
"OLAYLAR_P0068B:1791-01-01:0":{"b": ["Ruska opsada Braile — tvrđava nije zauzeta", "a5d5844b"], "d": ["Tvrđavu Brailu Rusi su u junu 1791. opsjeli, ali je nisu mogli zauzeti. Nakon poraza kod Mačina istog ljeta, strane će sjesti za sto radi primirja, a Braila će ostati u osmanskim rukama.", "367079fa"]},
"OLAYLAR_P0068B:1791-02-27:0":{"b": ["Drugi mandat Kodža Jusuf-paše kao velikog vezira — preuzimanje dužnosti u taboru kod Šumena", "c6e04dc4"], "d": ["Nakon kratkog mandata Šerif Hasan-paše, koji je završio pogubljenjem, pečat je ponovo predat Kodža Jusuf-paši; paša je 27. februara 1791. otišao u tabor kod Šumena i preuzeo dužnost. Primirje i mirovni pregovori koji će okončati rat vodit će se za njegovog drugog mandata.", "3331c22b"]},
"OLAYLAR_P0068B:1791-06-10:0":{"b": ["Prekid pregovora u Svištovu — austrijska delegacija povlači se u Bukurešt", "b5a0a875"], "d": ["Austrijski opunomoćenik Herbert povukao se 10. juna 1791. u Bukurešt i tako doveo do prekida pregovora; sljedećeg dana istekao je i rok primirja. Taj prekid trajao je pet sedmica i mir je spašen tek posredovanjem Britanije i Pruske.", "19ee29e9"]},
"OLAYLAR_P0068B:1791-06-11:0":{"b": ["Istek Đurđevskog primirja — mir stisnut u isto ljeto", "73e4f9c0"], "d": ["Devetomjesečno Đurđevsko primirje isteklo je 11. juna 1791. Budući da pregovori koji su trajali u Svištovu do tog dana nisu bili završeni, mir se našao stisnut između kraja primirja i mogućnosti obnovljenog rata; ugovor je mogao biti potpisan tek 4. augusta 1791.", "c0082fb0"]},
"OLAYLAR_P0068B:1791-07-09:0":{"b": ["Poraz kod Mačina — poraz koji je donio mir", "ccadcd46"], "d": ["Osmanska vojska pretrpjela je kod Mačina opći poraz i velika je pustoš. Taj poraz, koji je došao pošto je primirje s Austrijom već bilo potpisano, učinio je neizbježnom i odluku o sjedanju za sto s Rusijom: mjesec dana kasnije u Galacu je potpisano primirje.", "842dcfca"]},
"OLAYLAR_P0068B:1791-07-18:0":{"b": ["Ponovni početak mirovnih pregovora — Herbertov povratak u Svištov", "3715b815"], "d": ["Nakon petosedmičnog prekida austrijska delegacija vratila se 18. jula 1791. u Svištov. Sedamnaest dana kasnije, 4. augusta 1791., potpisat će se mirovni ugovor.", "3f3ed300"]},
"OLAYLAR_P0068B:1791-08-08:0":{"b": ["Saglasnost o primirju u Galacu između Vasif-efendije i kneza Repnina", "f792ca6b"], "d": ["Mjesec dana nakon poraza kod Mačina, 8. augusta 1791. u Galacu su Ahmed Vasif-efendija i ruski zapovjednik knez Repnin postigli saglasnost o osnovama primirja. Tri dana kasnije potpisat će se dokumenti o primirju.", "610110f6"]},
"OLAYLAR_P0068B:1791-08-11:0":{"b": ["Galacko primirje — osmomjesečni prekid vatre s Rusijom", "169ee7ec"], "d": ["Osmomjesečno primirje između Osmanske države i Rusije potpisano je 11. augusta 1791.; dokumenti su istog dana potvrđeni pod nazivom 'osnovni član i primirje'. Tako su borbe na ruskom frontu, koje su trajale četiri godine, prestale i postavljen je okvir mira koji će pet mjeseci kasnije biti potpisan u Jašiju.", "6b7fb0e3"]},
"OLAYLAR_P0068B:1791-08-12:0":{"b": ["Padišahova potvrda Svištovskog mira", "8cbbdccd"], "d": ["Svištovski mir potpisan 4. augusta 1791. potvrđen je 12. augusta. Potvrda je uslijedila odmah dan nakon potpisivanja primirja s Rusijom: Osmanska država je u istoj sedmici pravno okončala borbe na oba fronta.", "4972648f"]},
"OLAYLAR_P0068B:1791-08-31:0":{"b": ["Svečana razmjena ratifikacijskih isprava iz Svištova", "f8419068"], "d": ["Ratifikacijske isprave mira s Austrijom svečano su razmijenjene 31. augusta 1791.; nakon toga veliki vezir je krenuo na mirovne pregovore na ruskom frontu. Tako je austrijski front otvoren 1788. potpuno zatvoren.", "c0ddbdf0"]},
"OLAYLAR_P0068B:1791-10-16:0":{"b": ["Potemkinova smrt — promjena na ruskoj strani u pregovorima u Jašiju", "78f41463"], "d": ["Ruski opunomoćenik Potemkin umro je na putu za manastir Nikolašet 16. oktobra 1791. Umjesto njega pregovore je vodio grof Bezborodko; mirovni pregovori mogli su redovno početi tek nakon njegovog dolaska, u novembru.", "ca581195"]},
"OLAYLAR_P0068B:1791-11-10:0":{"b": ["Početak osmansko-ruskih pregovora u Jašiju", "455205f8"], "d": ["Osmanska i ruska delegacija održale su 10. novembra 1791. u Jašiju prvu sjednicu. Za dva mjeseca održat će se šesnaest sastanaka i na tim sjednicama bit će riješena pitanja odštete i granice.", "e092f125"]},
"OLAYLAR_P0068B:1792-01-07:0":{"b": ["Četrnaesta sjednica u Jašiju — Rusija se odriče zahtjeva za odštetom", "36aa4c91"], "d": ["Na četrnaestom razgovoru 7. januara 1792. ruski opunomoćenik Bezborodko odrekao se zahtjeva za odštetom i objavio da je mir sklopljen. Dogovoreno je da se tekst ugovora potpiše tri dana kasnije.", "76f6232b"]},
"OLAYLAR_P0068B:1792-01-18:0":{"b": ["Potvrda Jašijskog mira senetom velikog vezira", "b2f4cec8"], "d": ["Jašijski mir potpisan 10. januara 1792. potvrđen je 18. januara senetom koji je izdao veliki vezir. Nakon potvrde uslijedit će razmjena potvrdnih pisama i ratifikacijskih isprava i mir će početkom februara biti pravno konačan.", "be4cae64"]},
"OLAYLAR_P0068B:1792-01-27:0":{"b": ["Šesnaesta sjednica u Jašiju — razmjena potvrdnih pisama", "26061259"], "d": ["Na šesnaestom i posljednjem sastanku 27. januara 1792. uzajamno su razmijenjena potvrdna pisma. Time je konferencija zatvorena; preostala je samo razmjena vladarskih ratifikacijskih isprava.", "6726568b"]},
"OLAYLAR_P0068B:1792-02-10:0":{"b": ["Razmjena ratifikacijskih isprava iz Jašija — mir postaje konačan u međunarodnom pravu", "7b59d6b3"], "d": ["Vladarske ratifikacijske isprave razmijenjene su 10. februara 1792. i mir je postao konačan i sa stajališta međunarodnog prava. Tako je rat na dva fronta, koji je trajao pet godina, zvanično zatvoren; gubitak Krima postao je konačan, a nova granica Osmanske države postala je Turla (Dnjestar).", "f0615309"]},
"OLAYLAR_P0068B:1792-05-03:0":{"b": ["Razrješenje Kodža Jusuf-paše i postavljenje za valiju Trabzona", "ee79414b"], "d": ["Tri mjeseca nakon što je mir postao konačan, Selim III je 3. maja 1792. razriješio Kodža Jusuf-pašu, koji je od početka rata dvaput bio veliki vezir, i istog dana ga postavio za valiju Trabzona i muhafiza Anape. Tako je garnitura koja je vodila rat napustila dužnost.", "1ff948fd"]},
"OLAYLAR_P0068B:1792-05-04:0":{"b": ["Postavljenje Melek Mehmed-paše za velikog vezira — formiranje reformske garniture", "bbb92fd7"], "d": ["Melek Mehmed-paša, koji je 1788. udaljen s vezirstva jer je bio pristalica mira, 4. maja 1792. doveden je na položaj velikog vezira. Njegovim dolaskom u prijestolnicu 7. juna počelo je prikupljanje lajiha o nizam-i devletu od državnih velikodostojnika; priprema programa Nizam-i Džedid odvijala se s tom garniturom.", "94e90cff"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["Osvajanje tvrđave Ostrovice u dolini Une", "5c6cc91b"], "d": ["Ostrovica, u rukama Frankopana i drugih hrvatskih velikaša, nalazila se na strmom grebenu koji je povezivao sjeverni i južni dio doline Une. Godine 1523. prešla je pod osmansku upravu i do 1878. imala osmanski garnizon. Tvrđava je pravi značaj stekla nakon Karlovaca (1699): zbog blizine mletačke i austrijske granice proširena je i postala središte kapetanije Stara Ostrovica; gradić Kulen Vakuf osnovan je u njenom podnožju početkom XVIII stoljeća.", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["Osvajanje tvrđava Udbine i Krbave — Lika ulazi pod osmansku upravu", "5fe329d3"], "d": ["Krbavsko polje se 1524. ispraznilo i u Udbini je ostao samo Karlovićev garnizon. Karlović je u aprilu 1527. pred tvrđavom odnio posljednju pobjedu, ali je krajem maja Udbina zajedno s tvrđavama Mrsinj i Komić prešla u ruke bosanskog paše. Iste godine kraj Gospića dat je agama Senkovićima. Lika i Krbava otada su bile dio sandžaka sa središtem u Obrovcu, koji je 1580. dobio ime Krka.", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["Drežnik i drežnička županija konačno prelaze pod osmansku upravu", "6624ad14"], "d": ["Drežnik, od 1323. u rukama Frankopana, 1578. su Osmanlije privremeno držale. Godine 1592. tvrđava i cijela drežnička županija konačno su ušle pod osmansku upravu; iste godine pao je i Bihać. Drežnik je u XVIII stoljeću bio vezan za ostrožačku kapetaniju.", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["Osmanlije zauzele tvrđavu Cetin", "98815f97"], "d": ["Cetin, od sredine XVI stoljeća ključna tvrđava u odbrani slunjskog kraja od Osmanlija, nakon više opsada 1636. prešao je pod osmansku upravu. Taj prvi osmanski period trajao je dvije godine.", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["Tvrđava Cetin vraća se na habsburšku stranu", "690f9f84"], "d": ["Cetin, koji je 1636. prešao u osmanske ruke, 1638. vratio se u hrvatsko-habsburšku graničnu odbranu i tako ostao do 1670.", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Cetin ponovo osmanska tvrđava", "e1750675"], "d": ["Cetin je 1670. ponovo postao osmanska tvrđava i u XVIII stoljeću temeljito utvrđen: srednjovjekovna tvrđava opasana je zidinama s kulama. Tvrđava je do 1790. držala sjeverozapadni kraj bosanske krajine.", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["Gubitak Like i Krbave — Udbina i Gospić prešli u ruke habsburških graničarskih snaga", "01277a38"], "d": ["U ratu koji se nastavio nakon bečkog poraza hrvatske graničarske jedinice pod komandom karlovačkog generala Herbersteina 1689. zauzele su Udbinu; iste godine iz osmanske uprave izašao je i Gospić. Više od 160 godina duga osmanska Lika bila je okončana, ispražnjena mjesta naseljena su novim hrvatskim stanovništvom, a Udbina je do Svištovskog mira (1791) bila važna tvrđava granične odbrane protiv Osmanlija.", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["Austrija zauzela Drežnik — zapadni front Dubičkog rata", "05d5e5f1"], "d": ["U Osmansko-austrijskom ratu 1788-1791. habsburške snage zauzele su Drežnik zapadno od Bihaća. Po 4. članu Svištovskog mira Drežnik i Cetin ostali su pod habsburškom upravom i više se nisu vratili Bosni.", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["Austrija zauzela tvrđavu Cetin", "df182480"], "d": ["Habsburška vojska 1790. napala je Cetin, Bužim i Veliku Kladušu i zauzela Cetin. Mobilizacija koju je proglasio bosanski namjesnik i protivnapad nisu povratili tvrđavu; 4. član Svištovskog mira prepustio je Cetin Habsburzima. Bosanski krajišnici su 1809. i 1813. kratkim prepadima ponovo zauzeli tvrđavu.", "fc69baec"]},
"OLAYLAR_P0917DUNYA:1915-02-23:0":{"b": ["Ruska okupacija Hope", "d4bd9ae3"], "d": ["Hopu, koja je nakon Berlinskog ugovora 1878. ostala osmanski kadiluk u Lazistanskom sandžaku, u Prvom svjetskom ratu zauzele su ruske jedinice; okupacija je trajala do 14. marta 1918.", "4cbc2764"]},
"OLAYLAR_P0917DUNYA:1915-09-26:0":{"b": ["Britanska okupacija Kut el-Amare", "2447347a"], "d": ["Britanski general Townshend, koji je ciljao zauzeti Bagdad, krenuo je uz Tigris i na putu zauzeo Kut el-Amaru. Grad je nakon protokola o predaji potpisanog 29. aprila 1916. ponovo prešao u ruke turskih snaga.", "f815cd30"]},
"OLAYLAR_P0917DUNYA:1916-02-16:0":{"b": ["Erzurum pada pod rusku okupaciju", "4bcf972b"], "d": ["Ruske snage, koje su od početka rata Erzurum odabrale kao glavni cilj, ušle su u grad; Erzurum je po treći put došao pod rusku okupaciju. Okupacija je trajala do 12. marta 1918.", "65611111"]},
"OLAYLAR_P0917DUNYA:1916-02-24:0":{"b": ["Ruska okupacija Aşkalea", "c0b4232f"], "d": ["Ruske snage, koje su 16. februara 1916. zauzele Erzurum, napredujući na zapad zauzele su 24. februara Aşkale. Aşkale je oslobođen 3. marta 1918.", "6b05668a"]},
"OLAYLAR_P0917DUNYA:1916-03-01:0":{"b": ["Ruska okupacija Bitlisa", "2cdb1cbc"], "d": ["Ruske snage zauzele su Bitlis. Okupacija je trajala do 8. augusta 1916.", "b311d03c"]},
"OLAYLAR_P0917DUNYA:1916-03-08:0":{"b": ["Ruska okupacija Rizea: pad istočne crnomorske obale", "263f36d3"], "d": ["Ruske jedinice, koje su 7. februara 1916. iz Batuma krenule u napad u pravcu Arhavija, napredovale su obalom na zapad i zauzele 4. marta Pazar, 5. marta Čajeli, 8. marta Rize i 26. marta Of. Trabzon je na kraju tog napredovanja zauzet s kopna 18. aprila 1916.", "5edb2835"]},
"OLAYLAR_P0917DUNYA:1916-04-18:0":{"b": ["Ruska okupacija Trabzona", "5d166ea1"], "d": ["Ruske jedinice, koje su 14. aprila probile odbrambenu liniju na Karadereu i 16. aprila stigle do Jomre, ušle su 18. aprila u Trabzon nakon što je tursko stanovništvo napustilo grad. Ruska okupacija trajala je do 24. februara 1918.", "311840b1"]},
"OLAYLAR_P0917DUNYA:1916-07-16:0":{"b": ["Ruska okupacija Bajburta i Gümüşhanea", "a4229eff"], "d": ["Probojem Kopske odbrane ruske jedinice zauzele su 16. jula 1916. Bajburt, 19. jula Gümüşhane i 22. jula Kelkit; Erzindžan je pao nakon njih, 24. jula.", "04312d2b"]},
"OLAYLAR_P0917DUNYA:1916-07-24:0":{"b": ["Ruska okupacija Erzindžana", "81c11c05"], "d": ["Ruske snage zauzele su Erzindžan 24. jula 1916. Grad je oslobođen 26. februara 1918.", "964bb144"]},
"OLAYLAR_P0917DUNYA:1916-08-08:0":{"b": ["Oslobođenje Bitlisa od ruske okupacije", "8294f009"], "d": ["Ruska okupacija, koja je počela 1. marta 1916., okončana je povlačenjem Rusa iz grada.", "d172c696"]},
"OLAYLAR_P0917DUNYA:1916-09-17:0":{"b": ["Taif prelazi snagama šerifa Husejna", "3924f74f"], "d": ["Snage šerifa Husejna, koji se za vrijeme Prvog svjetskog rata pobunio protiv osmanske uprave i imao britansku podršku, zauzele su Taif. Tokom opsade grad je pretrpio veliku štetu.", "77eb751d"]},
"OLAYLAR_P0917DUNYA:1916-11-06:0":{"b": ["Ubistvo Alija Dinara — Darfurski sultanat prestao je postojati, Darfur je pripojen britanskom Sudanu", "17796ae7"], "d": ["Darfurski sultan Ali Dinar, koji se u Prvom svjetskom ratu približio Osmanskoj državi, nakon pada prijestolnice Fašera u maju 1916. povukao se u pravcu Džebel Mare; ubile su ga 6. novembra 1916. snage koje je poslala sudanska vlada. Nešto kasnije darfurske zemlje pripojene su britanskom Sudanu kao pokrajina.", "77fea96b"]},
"OLAYLAR_P0917DUNYA:1917-03-07:0":{"b": ["Britanska okupacija Nedžefa", "eff495f9"], "d": ["Nedžef, koji je u posljednje osmansko doba bio središte kadiluka u sandžaku Kerbela Bagdadskog vilajeta, Britanci su zauzeli 7. marta 1917.; četiri dana kasnije pao je i Bagdad. Grad je monarhijom uspostavljenom 1920. ušao u granice Iraka.", "737a90d9"]},
"OLAYLAR_P0917DUNYA:1917-12-06:0":{"b": ["Hanekin je ušao u britansku liniju", "daef063a"], "d": ["Nakon operacije na Hamrinu, britanski III. korpus je 6. decembra 1917. zauzeo prednju liniju koja se protezala od Hanekina do Kizilrubata; Hanekin je od tada ostao u britanskim rukama i postao početak puta za Iran.", "968eb7b5"]},
"OLAYLAR_P0917DUNYA:1918-02-19:0":{"b": ["Oslobođenje Bajburta i Gümüşhanea", "15162c86"], "d": ["U napredovanju koje je počelo raskidom Erzindžanskog primirja Kelkit je oslobođen 17., a Bajburt 19. februara; ruska okupacija Gümüşhanea okončana je 28. februara 1918.", "6ac1cb20"]},
"OLAYLAR_P0917DUNYA:1918-02-24:0":{"b": ["Oslobođenje Trabzona od ruske okupacije", "d0c44c85"], "d": ["Rusi su se povukli iz Trabzona i okončana je okupacija koja je trajala oko dvije godine.", "7a57114d"]},
"OLAYLAR_P0917DUNYA:1918-02-26:0":{"b": ["Oslobođenje Erzindžana", "2700373c"], "d": ["Erzindžan, koji je od 24. jula 1916. bio pod ruskom okupacijom, oslobodile su turske jedinice.", "d3617b82"]},
"OLAYLAR_P0917DUNYA:1918-03-02:0":{"b": ["Oslobođenje Rizea: povratak istočne crnomorske obale", "cab60e94"], "d": ["Povlačenjem Rusa turske jedinice napredovale su obalom na istok: Rize se ponovo vratio pod osmansku upravu 2. marta, Čajeli 9. marta, a Hopa 14. marta 1918.", "014dea28"]},
"OLAYLAR_P0917DUNYA:1918-03-12:0":{"b": ["Oslobođenje Erzuruma", "6c832f86"], "d": ["Turske jedinice pod komandom Kazima Karabekir-paše oslobodile su Erzurum od armenskih jedinica; grad je nakon dvogodišnje okupacije ponovo ušao pod osmansku upravu.", "43ae103d"]},
"OLAYLAR_P0917DUNYA:1918-04-01:0":{"b": ["Poraz kod Tuz Hurmatua — osmanske jedinice povukle su se u Kirkuk", "d844b61f"], "d": ["Pred kraj Prvog svjetskog rata, u aprilu 1918., osmanske jedinice koje su kod Tuz Hurmatua poražene od britanskih snaga povukle su se u Kirkuk; gradić je došao pod britansku okupaciju.", "07529ee4"]},
"OLAYLAR_P0917DUNYA:1918-04-28:0":{"b": ["Operacija u Južnom Kurdistanu: kolona C ušla je u Kifri", "13b40542"], "d": ["U operaciji u Južnom Kurdistanu britanska kolona C ujutro 28. aprila 1918. bez otpora ušla je u Kifri. I kada je krajem maja Kirkuk napušten, Kifri i Tuz Hurmatu držani su kao britanske isturene straže.", "bcae14d1"]},
"OLAYLAR_P0917DUNYA:1918-05-07:0":{"b": ["Britanska okupacija Kirkuka", "6f7a899f"], "d": ["Osmanske jedinice, poražene u aprilu 1918. kod Tuz Hurmatua, povukle su se u Kirkuk; 7. maja Britanci su zauzeli Kirkuk.", "dd627ad7"]},
"OLAYLAR_P0917DUNYA:1918-05-27:0":{"b": ["Povratak Kirkuka", "9e911edf"], "d": ["Nakon dvadesetodnevne britanske okupacije, osmanske snage povratile su Kirkuk 27. maja 1918. Kada su se pod britanskim napadima koji su počeli 28. oktobra 1918. osmanske jedinice povukle u Altun-Köprü, grad je ponovo prešao pod britansku upravu.", "08a1b3e0"]},
"OLAYLAR_P0917DUNYA:1918-07-12:0":{"b": ["Kraj samaranske željeznice: britanski odred smjestio se u Tikritu", "7015ab60"], "d": ["Nakon bitke kod Tikrita 5. novembra 1917. britanske snage su se 10. novembra povukle u Samaru. Dana 12. jula 1918. odred iz I. korpusa zauzeo je Tikrit radi zaštite produženja samaranske željeznice.", "baff356d"]},
"OLAYLAR_P0917DUNYA:1918-09-15:0":{"b": ["Kavkaska islamska vojska zauzela je Baku", "1ac40958"], "d": ["Kavkaska islamska vojska pod komandom Nuri-paše, koja je prema Batumskom ugovoru od 4. juna 1918. došla pomoći Azerbejdžanskoj Demokratskoj Republici, zauzela je Baku koji je bio u ruskim rukama. Nakon Mudroskog primirja osmanske snage povukle su se iz grada; republika je okončana 27. aprila 1920. okupacijom Crvene armije.", "31413075"]},
"OLAYLAR_P0917DUNYA:1921-02-25:0":{"b": ["Ulazak Crvene armije u Tbilisi: pad Gruzijske Demokratske Republike", "de0e19cd"], "d": ["Gruziju, koja je 26. maja 1918. proglasila nezavisnost, u februaru 1921. okupirala je Sovjetska Rusija; 25. februara 1921. boljševici su ušli u Tbilisi i uspostavili sovjetski režim. Tim su događajem Gori, Telavi i Dušeti (istočna Gruzija) prešli pod kontrolu Sovjetske Rusije.", "ea05a868"]},
"OLAYLAR_P0917KOSU13:1387-01-01:0":{"b": ["Osvajanje Vodene (zima 1386-1387.)", "1e542d14"], "d": ["Vodena, zapadno od Vardara u Makedoniji, ušla je pod osmansku upravu osvajanjem za koje osmanske hronike navode različite godine. Hodža Sadeddin osvajanje smješta u 1386.; TDV smatra primjerenijim da se kao vrlo vjerovatna prihvati zima 1386-1387. Budući da se zapovjednik koji je izvršio osvajanje u izvoru izričito ne spominje, osoba nije upisana.", "0da93b6a"]},
"OLAYLAR_P0917KOSU13:1415-01-01:0":{"b": ["Manisa prelazi pod upravu Mehmeda I Čelebija — kraj manisanske grane Saruhanogullarija", "6d6c7622"], "d": ["Na kraju Fetreta zemlja Saruhana prešla je pod upravu Mehmeda I Čelebija i manisanska grana Saruhanogullarija nestala je iz historije. TDV taj prelazak smješta poslije 1411. i prije 1415.; osmanska uprava mogla je biti potpuno uspostavljena nešto prije 818. (1415.). Zato je datum upisan najkasnijim krajem tog intervala.", "4d3e8c85"]},
"OLAYLAR_P0917KOSU13:1427-01-01:0":{"b": ["Đurđu (Yergöğü) prelazi Vlaškoj", "bc5c11f4"], "d": ["Tvrđavu Đurđu (Giurgiu) na obali Dunava Vlasi su povratili 1427. Tvrđava je bila jedno od prvih uporišta Osmanlija na sjevernoj obali Dunava i više od dvadeset godina ostala je u Vlaškoj.", "91dc683d"]},
"OLAYLAR_P0917KOSU13:1450-01-01:0":{"b": ["Đurđu se vraća pod osmansku kontrolu (853./1449-50.)", "c9ad1b89"], "d": ["Tvrđava Đurđu, koju su Vlasi povratili 1427., 853. godine ponovo je došla pod osmansku kontrolu. Budući da se hidžretska godina proteže od februara 1449. do februara 1450., datum je zapisan Novom godinom 1450., koja pada unutar tog intervala. Tvrđava je od tada bila osmanska krajiška tvrđava koja je štitila prijelaz preko Dunava.", "15b80685"]},
"OLAYLAR_P0917KOSU13:1516-10-01:0":{"b": ["Jerusalem i gradovi Palestine prelaze pod osmansku upravu", "7ac58e9d"], "d": ["Nakon pobjede kod Mardž Dabika i dolaska Selima I Javuza u Damask 27. septembra, gradovi Sirije i Palestine jedan za drugim prešli su pod osmansku upravu. TDV navodi da je Nablus ušao pod osmansku upravu u jesen 1516., a Jerusalem vjerovatno u oktobru 1516., prije dolaska padišaha. Padišah je u Jerusalem stigao tek nakon bitke kod Gaze, 29. decembra 1516.", "7680d172"]},
"OLAYLAR_P0917KOSU13:1532-01-01:0":{"b": ["Bitlis prešao pod safavidsku zaštitu — Ulama i Fil-paša podigli su opsadu", "2d0610f6"], "d": ["Kada je Tekeli Ulama prebjegao Osmanlijama i postavljen za beglerbega bitliskog kraja, vazal Osmanlija, gospodar Bitlisa Šeref-han, prebjegao je Safavidima. Ulama i dijarbekirski beglerbeg Fil-paša 938. opsjeli su tvrđavu; tvrđava je izdržala tri mjeseca, a kada su osmanske snage saznale da se približava šah Tahmasp, podigle su opsadu. Šah je Šeref-hanu priključio Bitlis i krajeve Ahlata, Muša i Hinisa.", "8b605ee5"]},
"OLAYLAR_P0917KOSU13:1534-01-01:0":{"b": ["Bitlis je Ulama-pašinom rukom konačno pripojen Osmanlijama", "7631002a"], "d": ["Tekeli Ulama, čija je prva opsada ostala bez uspjeha, ubio je 940. (1533.) gospodara Bitlisa Šeref-hana i 1534. konačno pripojio Bitlis osmanskim zemljama. Sin Šeref-hana Šemsudin-beg, nakon što je Bitlis dat Ulami, s plemenom Rojeki sklonio se kod Safavida. Osmansku vlast nad Bitlisom priznali su i Safavidi Amasijskim mirom 1555.", "3d1f3e99"]},
"OLAYLAR_P0917KOSU13:1565-01-01:0":{"b": ["Osmanlije zauzimaju tvrđavu Krupa", "7a786bf3"], "d": ["Tvrđava Krupa na desnoj obali Une pala je 1565. u ruke Osmanlija. Tvrđava je u sljedeća dva stoljeća ostala osmanska uprkos austrijskim opsadama (1581., 1690., 1692., 1716.) i postala dio unske granične linije između Bihaća i Novog.", "e7a52e35"]},
"OLAYLAR_P0917KOSU13:1578-08-24:0":{"b": ["Zauzimanje Tbilisija bez borbe — pokornost Kahetije i Imeretije", "b1563ee6"], "d": ["Osmanska vojska pod komandom Lale Mustafa-paše, koja je napredovala nakon pobjede kod Čildira, stigla je 24. augusta u Tbilisi i bez borbe zauzela napuštenu tvrđavu. Nakon osvajanja Tbilisija vladari Imeretije i Kahetije obavijestili su Osmanlije o svojoj pokornosti.", "41a9cb07"]},
"OLAYLAR_P0917KOSU13:1588-09-01:0":{"b": ["Pokornost Šahverdi-hana, gospodara Karadaga (Ahara), Džafer-paši — Marand ulazi pod osmansku upravu", "fe55fb37"], "d": ["Tabriski beglerbeg Džafer-paša 1588. proširio je svoju vlast na Marand; gospodar Karadaga Šahverdi-han pokorio se i poslao sina u Tabriz. Izvori navode samo godinu; dan je usklađen s pohodom na Gandžu iste godine.", "9a1a0cee"]},
"OLAYLAR_P0917KOSU13:1589-01-01:0":{"b": ["Džigalazade Sinan-paša zauzeo je Nihavend i podigao tvrđavu — pokornost Luristana", "1a6a0329"], "d": ["Bagdadski valija Džigalazade Sinan-paša krajem 1588. zauzeo je Nihavend i ondje dao podići tvrđavu; gospodar Luristana Šahverdi pokorio se Osmanlijama. Izvori ne daju dan; datum je na nivou godine.", "89a4eefd"]},
"OLAYLAR_P0917KOSU13:1722-11-01:0":{"b": ["Osmansko priznanje vlasti Hadži Davuda nad Širvanom", "8e7b0476"], "d": ["Kada su Osmanlije u novembru 1722. uputile ultimatum ruskim snagama da se povuku iz tog kraja, priznali su vlast Hadži Davuda nad Širvanom. Hadži Davud tako je, poput krimskog hana, postao vazalni vladar vezan za Osmanlije.", "6b466aaf"]},
"OLAYLAR_P0917KOSU13:1723-08-06:0":{"b": ["Ruske snage zauzimaju Baku", "482170dc"], "d": ["U drugoj godini Kaspijskog pohoda Petra I jedinica generala Matjuškina, došavši s mora, zauzela je Baku. Grad je ostao s ruskim garnizonom do 1735., kada je Gandžanskim ugovorom vraćen Iranu. Članak TDV-a o Bakuu povratak smješta u 1734.; ruski i iranski izvori navode Gandžanski ugovor iz 1735.", "29dc4fb3"]},
"OLAYLAR_P0917KOSU13:1723-11-10:0":{"b": ["Predaja Sanandadža (Sine), središta Ardalana", "83b23183"], "d": ["Babanski beg Hane Mehmed-paša, upućen na Ardalan nakon zauzimanja Kermanšaha, preuzeo je središte pokrajine Sanandadž; i live Mihriban (Merivan), Bane i Sakiz pripojene su osmanskom Ardalanskom ejaletu. Za ejalet je 1727. sačinjen detaljan osmanski tahrir defter.", "e4060148"]},
"OLAYLAR_P0917KOSU13:1724-01-01:0":{"b": ["Urmija i Salmas prelaze pod osmansku upravu", "1e25828f"], "d": ["U godinama kada se Safavidska država raspadala zbog afganske invazije, Urmija je još jednom došla pod osmansku vlast. Za Urmiju i pripadajuću livu Salmas 1728. sačinjen je osmanski tahrir defter. U Nadirovoj ofanzivi 1729-1730. oblast je izgubljena; Hećimoglu Ali-paša povratio je Urmiju 1731.", "505c034f"]},
"OLAYLAR_P0917KOSU13:1725-09-09:0":{"b": ["Zauzimanje Ardebila", "917ebe96"], "d": ["Nakon Tabriza snage Ćuprilizade Abdullah-paše ušle su u Ardebil, duhovno središte Safavida. Grad je 1728., zajedno s nahijama Serab i Mijane, popisan u defter kao osmanska liva Ardebil; i susjedni Halhal unesen je u defter kao zasebna liva. Nadir je 1730. povratio Ardebil.", "1fe99397"]},
"OLAYLAR_P0917KOSU13:1731-11-15:0":{"b": ["Hećimoglu Ali-paša povraća Tabriz", "fda463ac"], "d": ["Tabriz, koji je 1730. pao u ruke Safavida, Hećimoglu Ali-paša ponovo je zauzeo 15. novembra 1731.; u istoj operaciji zauzeta je i Urmija. Međutim, ugovorom od 10. januara 1732. Tabriz je prepušten Iranu. Atlas smatra da je i Kotur, koji prati niz Hoja, tog dana prešao od Safavida Osmanlijama (TDV, članak o Hoju; dan specifičan za Kotur nije naveden u izvoru — deklarirana približnost).", "9847bdc5"]},
"OLAYLAR_P0917KOSU13:1735-10-03:0":{"b": ["Predaja Erivana Nadir-hanu", "371ef64b"], "d": ["Nadir-han, koji je nakon poraza na Arpačaju (Baghavardu) 9. jula uzeo Gandžu, a 12. augusta Tbilisi, zauzeo je i Erivan. Nahije Karpi (Üçkilise), Šerur i Maku, zajedno sa središtem ejaleta, prešle su Iranu.", "d2c03da0"]},
"OLAYLAR_P0917KOSU13:1736-03-24:0":{"b": ["Rusija je krenula na Azov i Krim — Osmansko-ruski rat faktički je počeo", "c6d4dbc7"], "d": ["Rusija, koja je prolazak krimskih snaga kroz Kabardu na putu ka iranskom frontu smatrala povredom svoje teritorije, to je uzela za povod i bez objave rata u dva pravca krenula na Azov i Krim. Münnich je prešao Don i zauzeo tvrđave pred Azovom. Osmanski divan donio je odluku o ratu tek 2. maja 1736.", "c7d0e549"]},
"OLAYLAR_P0917KOSU13:1739-12-12:0":{"b": ["Ahdnama o miru s Rusijom: Kabarda neutralna, Azov će se porušiti", "27454835"], "d": ["Ahdnama o miru s Rusijom sačinjena je 12. decembra 1739. Utvrđenja Azova porušit će se i između dviju država ostaviti pusta međuzona, a Kabarda neće biti potčinjena ni Rusiji ni Osmanlijama (čl. 6). Očakov i Kilburun ostali su Osmanlijama.", "02e73b3a"]},
"OLAYLAR_P0917KOSU13:1770-09-01:0":{"b": ["Predaja tvrđave Kilije Repninu", "e894b7d0"], "d": ["Repninova kolona, koja se nakon poraza kod Kartala spustila na ušće Dunava, stigla je 10. augusta (po julijanskom) pred Kiliju. Nakon vatre baterija kroz proboje i desetodnevne odbrane, branioci su predali tvrđavu pod uslovom da slobodno izađu sa svojim oružjem, narodom i imovinom. Kilija je Kučukkajnardžijskim mirom (1774.) vraćena Osmanlijama.", "fb66a9e9"]},
"OLAYLAR_P0917KOSU13:1770-10-09:0":{"b": ["Pala je tvrđava Akerman na ušću Dnjestra", "018c420b"], "d": ["Nedugo nakon pada Bendera i Akerman na ušću Dnjestra pao je u ruke ruskih snaga. Tvrđava je Kučukkajnardžijskim mirom (1774.) vraćena Osmanlijama.", "38e48332"]},
"OLAYLAR_P0917KOSU13:1788-08-26:0":{"b": ["Pad Dubice u ruke Austrije", "66d70917"], "d": ["Prvi austrijski napadi u proljeće 1788. bili su odbijeni. U augustu je maršal Laudon ponovo uspostavio opsadu; tvrđava, koja je ostala bez hrane i municije, predala se 26. augusta 1788. Dubica je, zajedno s Novim koji je pao u oktobru, bila jedini vojni uspjeh Austrije te godine. Tvrđava je Svištovskim mirom 1791. vraćena Osmanlijama.", "658f6f5a"]},
"OLAYLAR_P0917KOSU13:1788-09-01:0":{"b": ["Austrijsko-ruske snage zauzele su Hotin", "a6c18567"], "d": ["U ratu koji je počeo 1787. združene snage Austrije i Rusije opsjele su Hotin i tvrđavu su zauzele u septembru 1788. Prema Svištovskom miru, Austrija je tvrđavu držala na povjerenje do završetka ruskog mira; Hotin je Jašijskim mirom 1792. vraćen Osmanlijama.", "59f8979f"]},
"OLAYLAR_P0917KOSU13:1788-10-03:0":{"b": ["Laudon je zauzeo tvrđavu Novi na Uni", "80651c30"], "d": ["Nakon Dubice Laudon je krenuo na tvrđavu Novi na Uni i 3. oktobra 1788. zauzeo je; kapetan Cerić i cijela posada pali su u zarobljeništvo. Zbog gubitka dviju tvrđava u Bosni je proglašena opća mobilizacija. Novi je Svištovskim mirom 1791. vraćen.", "36ddff90"]},
"OLAYLAR_P0917KOSU13:1789-11-01:0":{"b": ["Austrijska vojska (Coburg) okupirala je Bukurešt", "ec890b9a"], "d": ["Nakon poraza kod Rimnika austrijska vojska početkom novembra 1789. okupirala je Bukurešt, središte Vlaške. Grad je Svištovskim mirom od 4. augusta 1791. vraćen osmanskoj strani.", "8c031b96"]},
"OLAYLAR_P0917KOSU13:1789-11-14:0":{"b": ["Predaja tvrđave Bender Potemkinu", "a661bafa"], "d": ["U osmansko-ruskom ratu 1787-1792. tvrđava Bender na Dnjestru predala se ruskoj vojsci pod komandom Potemkina. Tvrđava je Jašijskim mirom 1792. vraćena Osmanlijama.", "b150e1c5"]},
"OLAYLAR_P0917KOSU13:1790-10-24:0":{"b": ["Predaja tvrđave Kilije Rusima", "5e88acfe"], "d": ["U pohodu 1790. tvrđava Kilija na ušću Dunava opsjednuta je 4. oktobra (po starom kalendaru) i devet dana kasnije predala se generalu Gudoviču. Tvrđava je Jašijskim mirom 1792. vraćena Osmanlijama.", "45089b90"]},
"OLAYLAR_P0917KOSU13:1809-09-26:0":{"b": ["Predaja tvrđave Izmail generalu Zassu", "dc74c6d0"], "d": ["U osmansko-ruskom ratu 1806-1812. tvrđava Izmail na Dunavu predala se generalu Zassu. Tvrđava je Bukureškim mirom 1812. zajedno s Besarabijom prepuštena Rusiji.", "4d43c35c"]},
"OLAYLAR_P0917KOSU13:1838-01-01:0":{"b": ["Rusi su na čerkeskoj obali zauzeli luke Soči i Tuapse", "75679594"], "d": ["Na obali Čerkeza, koji nisu priznavali Jedrenski mir i faktički su ostali nezavisni, Rusi su 1838. zauzeli luke Soči i Tuapse. Okupacija čerkeske unutrašnjosti dovršena je 1861-1864.", "36d3e541"]},
"OLAYLAR_P0917KOSU13:1854-01-01:0":{"b": ["Rusi su u Krimskom ratu napustili i digli u zrak tvrđavu Veljaminovski u Tuapseu", "2202f051"], "d": ["Ruske tvrđave na čerkeskoj obali, koje je ulaskom englesko-francuske flote u Crno more u Krimskom ratu postalo nemoguće braniti, bile su napuštene; napuštena je i dignuta u zrak i tvrđava Veljaminovski, podignuta u Tuapseu 1838. Obala je desetak godina ponovo ostala pod kontrolom čerkeskih plemena.", "2b772139"]},
"OLAYLAR_P0917KOSU13:1864-02-01:0":{"b": ["Rusi su ponovo zauzeli staru tvrđavu Veljaminovski u Tuapseu", "a7ca0939"], "d": ["U posljednjoj godini okupacije Zapadnog Kavkaza ruske jedinice iskrcale su se na čerkesku obalu i ponovo zauzele mjesto tvrđave Veljaminovski, napuštene deset godina ranije. Za nekoliko mjeseci čerkeski otpor je prestao, a obalno stanovništvo najvećim je dijelom protjerano u osmanske zemlje.", "12049c51"]},
"OLAYLAR_P0917TARAF:1892-01-01:0":{"b": ["Drugi francusko-osmanski aranžman — tunisko-tripolitanska granica produžena je do Gadamesa", "94885487"], "d": ["Drugim francusko-osmanskim aranžmanom granica između Tunisa i Tripolitanskog vilajeta određena je detaljnije nego prije i u unutrašnjosti sve do Gadamesa. Glavni dokument koji je povukao današnju granicu jeste Tripolitanska konvencija, koja će biti potpisana osamnaest godina kasnije.", "b9df9291"]},
"OLAYLAR_P0917TARAF:1906-10-01:0":{"b": ["Rafaški sporazum — opisana je linija Rafah-Taba između Osmanlija i Egipatskog hediviata", "f10d25c6"], "d": ["Nakon akapsko-tabske krize 1906. osmanski i hedivski komesari dogovorili su se u Rafahu o upravnoj liniji razdvajanja; linija se protezala od Ras Tabe u Akapskom zaljevu do sredine između dvaju stubova u Rafahu. Mješovita delegacija od kraja iste godine do februara sljedeće godine podigla je duž linije devedeset jedan zidani stub. Ta je linija današnja granica Egipta s Izraelom i Egipta s Gazom.", "28a925f5"]},
"OLAYLAR_P0917TARAF:1909-04-19:0":{"b": ["Tursko-bugarski protokol u Istanbulu — Osmanlije su priznale nezavisnost Bugarske", "97302dc1"], "d": ["Protokolom potpisanim u Istanbulu uz posredovanje Rusije, Osmanska država zvanično je priznala nezavisnost Bugarske, proglašenu jednostrano šest mjeseci ranije. Tako je stara osmansko-bugarska granica u Strandži i pravno postala linija između dviju nezavisnih država; taj dio i danas je dio tursko-bugarske granice.", "393405ba"]},
"OLAYLAR_P0917TARAF:1910-05-19:0":{"b": ["Tripolitanska konvencija — granica između Tunisa i Tripolitanskog vilajeta povučena od Ras Adždira do Gadamesa", "9ca9e95a"], "d": ["Konvencijom potpisanom u Tripoliju između Francuske i Osmanske države opisana je granica između Tunisa i Tripolitanskog vilajeta od Ras Adždira na obali Sredozemnog mora do južno od Gadamesa. Mješovita komisija 1910-1911. obilježila je liniju s više od dvjesto kamenova; linija je i danas granica Libije i Tunisa. Ta granica dvije godine kasnije Ouchyjskim mirom prešla je od Osmanlija Italiji.", "74a4bc3f"]},
"OLAYLAR_P0917TARAF:1913-11-17:0":{"b": ["Istanbulski protokol — razgraničenje tursko-iranske granice", "daa100b9"], "d": ["Osmanski i iranski predstavnici, pod nadzorom britanskog i ruskog poslanika, potpisali su u Istanbulu protokol o razgraničenju tursko-iranske granice zasnovan na Erzurumskom ugovoru iz 1847. Mješovita komisija do oktobra sljedeće godine obilježila je liniju na terenu, osim kratkog dijela oko Kotura. Ta linija, koja je 1923. ostala kao tursko-iranska granica, izmijenjena je 1932. i 1937. na tri dijela.", "4bb44a7b"]},
"OLAYLAR_P0917TARAF:1915-09-06:0":{"b": ["Sofijska konvencija — ispravka osmansko-bugarske granice", "42026201"], "d": ["Konvencija potpisana u Sofiji nedugo prije ulaska Bugarske u rat na strani Osmanlija ispravila je osmansko-bugarsku granicu koju je povukao Istanbulski mir iz 1913. Istočnotrakijski dio linije 1921. ponovo je obilježila komisija iz Neuillyja i potvrđen je u Lozani.", "b259b598"]},
"OLAYLAR_SEHIR_ILK:1284-03-20:0":{"b": ["Bilecik se prvi put pominje — granica s Bizantom počinjala je kod Bilecika", "7b69f743"], "d": ["U događajima 683. godine koje prenosi Nešri, Bilecik se javlja kao mjesto gdje je počinjala granica između pograničnog bejluka Osman-bega i Bizanta. To je prvi poznati pomen naselja u historiji; nije njegovo osnivanje.", "f668b296"]},
"OLAYLAR_SEHIR_ILK:1299-09-28:0":{"b": ["Novac u ime Gazan-kana u Burduru — prvo poznato svjedočanstvo o gradu", "01974ddc"], "d": ["Hamidovići su pod ilhanatskim pritiskom 699. godine bili prisiljeni kovati novac u Burduru u ime Gazan-kana. Taj je novac prvo pisano/datirano svjedočanstvo o Burduru.", "83a1e1ee"]},
"OLAYLAR_SEHIR_ILK:1352-03-01:0":{"b": ["Čorum se pominje u Eretninoj zemlji — prvo poznato svjedočanstvo o gradu", "bf7bd67f"], "d": ["Među gradovima pod vlašću Eretna-bega u trenutku njegove smrti u muharremu 753. navodi se i Čorum. Osnivanje grada nije poznato; ovaj je pomen najranije datirano svjedočanstvo koje se moglo naći.", "68c8fd3f"]},
"OLAYLAR_SEHIR_ILK:1368-01-20:0":{"b": ["Braila se prvi put pominje — povlastica Vlaicua Vodă brašovskim trgovcima", "0b3517a7"], "d": ["Vlaški vojvoda Vladislav dao je brašovskim trgovcima ispravu koja im priznaje olakšice pri prijenosu robe putem preko Braile. Ta je isprava prvo poznato pisano svjedočanstvo o Braili; mjesto se ovdje još ne javlja kao grad, nego kao krajnja tačka puta na Dunavu. To nije datum osnivanja.", "8ed7db79"]},
"OLAYLAR_SEHIR_ILK:1420-01-01:0":{"b": ["Kišinjev prvi put pomenut u povelji moldavskog vojvode", "a50799d7"], "d": ["Ime Kišinjeva prvi put se javlja u povelji moldavskog vojvode Aleksandra iz 1420. Grad je dugo ostao mali moldavski gradić; kada je 1812. zajedno s Besarabijom prešao Rusiji, postao je središte pokrajine.", "61d831d5"]},
"OLAYLAR_SEHIR_ILK:1445-01-01:0":{"b": ["Galac se prvi put pominje u ispravi moldavskog vojvode", "a31af8a2"], "d": ["Moldavski vojvoda Ştefan II oslobodio je carine dva kola manastira Humor koja su dovozila ribu iz Galaca. Ta je isprava prvo sigurno poznato pisano svjedočanstvo o Galacu; naselje je ranije možda postojalo kao ribarsko selo na obali Dunava.", "40d464f1"]},
"OLAYLAR_SEHIR_ILK:1452-04-03:0":{"b": ["Ime Mostara prvi put se javlja u jednom dubrovačkom dokumentu", "a599bc55"], "d": ["Ime Mostara prvi put se javlja u dubrovačkom dokumentu od 3. aprila 1452; naselje je bilo na teritorijima Hercegovog vojvodstva. Osmansko osvajanje je 1466-68.", "5fba613f"]},
"OLAYLAR_SEHIR_ILK:1458-01-01:0":{"b": ["Hunkar-džamija u Sarajevu — najranije datirano svjedočanstvo o naselju", "ad697a7d"], "d": ["Bosanski sandžakbeg Ishak-beg u prvom muslimanskom naselju u Sarajevskom polju dao je sagraditi sebi saraj, Hunkar-džamiju u ime sultana Mehmeda Osvajača i pored nje hamam. Džamija je datirana 862. (1458); to je najranije poznata datirana građevina Sarajeva.", "d7927c3d"]},
"OLAYLAR_SEHIR_ILK:1462-02-01:0":{"b": ["Vakufnama Ishak-bega — uvakufljeno gradsko jezgro Sarajeva", "0b364229"], "d": ["Iz vakufname Ishak-bega iz džumade-l-ule 866. (februara 1462) vidi se da su osim džamije i hamama sagrađeni zavija, mevlevijska tekija, imaret, most preko Miljacke, Kolobara han na suprotnoj obali, bezistan, karavan-saraj i dućani. Dokument je vakufski temelj grada; naselje je postojalo i prije njega.", "5f20e8f0"]},
"OLAYLAR_SEHIR_ILK:1472-06-08:0":{"b": ["Tatar-Pazardžik prvi put zabilježen u akindžijskom defteru", "3b1c839e"], "d": ["Najstariji zapisi o gradu sežu do 877. (1472) godine: akindžijski defter u Narodnoj biblioteci u Sofiji bilježi naselje.", "45a744f9"]},
"OLAYLAR_SEHIR_ILK:1494-02-06:0":{"b": ["Banja Luka prvi put pomenuta u uputi kralja Vladislava II", "0ebc6288"], "d": ["Ime Banja Luka prvi put se javlja u uputi ugarsko-hrvatskog kralja Vladislava II od 6. februara 1494; kraj je preko Jajačke banovine bio vezan za ugarsku krunu. Osmansko osvajanje je zima 1527-28.", "02da21ca"]},
"OLAYLAR_SEHIR_ILK:1494-10-02:0":{"b": ["Stanovnici Basre dovršili preseljenje na današnje područje — stara Basra napuštena", "20f96eac"], "d": ["Stanovništvo se postepeno počelo naseljavati u današnjoj Basri, koju je smatralo sigurnijom od beduinskih napada i gdje je lakše moglo namiriti potrebe za vodom; prelazak na novo područje dovršen je 900. (1494-95) godine. Stara Basra, osnovana u doba hazreti Omera, bila je oko 25 km daleko od današnjeg grada.", "7e2ce96c"]},
"OLAYLAR_SEHIR_ILK:1503-01-01:0":{"b": ["Mengli Giraj-kan dao sagraditi Han-saraj na obali Čurjuksua — temelj Bahčisaraja", "0792497c"], "d": ["U dolini koja je bila ljetna oblast za lov i odmor namjesnika Zlatne Horde i prvih krimskih kanova, Mengli Giraj I dao je na obali Čurjuksua sagraditi dvor danas poznat kao Han-saraj i tako položio temelj Bahčisaraja. Grad se razvio oko dvora i duž uske doline Čurjuksua, potkraj XVI stoljeća procvjetao i postao središte Krimskog kanata.", "dbbc246c"]},
"OLAYLAR_SEHIR_ILK:1552-01-01:0":{"b": ["Zaporoški kozaci osnovali prvi Sič na otoku Hortica", "e6ca0dd9"], "d": ["Knez Dmitro Višnevecki osnovao je prvi Zaporoški Sič na otoku Mala Hortica na Dnjepru. Tvrđavu su 1558. opsjeli i srušili krimski Tatari; Sič je kasnije preseljen na južnije otoke. Termin: «Sič» (ukrajinski Sich) jest središnji tabor zaporoških kozaka na dnjeparskim otocima, utvrđen brvnima i jarkom; sjedište štaba, skupštine (Rada) i izabranog vojnog poglavara (koševoj), a ne državna prijestonica.", "2af408f9"]},
"OLAYLAR_SEHIR_ILK:1593-01-01:0":{"b": ["Osnovan Bazavlucki Sič", "fcd507ae"], "d": ["Nakon što su Tatari srušili Tomakivski Sič, zaporoški kozaci osnovali su novi Sič na otoku Bazavluk, gdje se Dnjepar spaja s rukavcima Čortomlik, Pidpilna i Skarban. Sič je srušen 1638. u poljskom pohodu nakon gušenja kozačkog ustanka. Termin: «Sič» (ukrajinski Sich) jest središnji tabor zaporoških kozaka na dnjeparskim otocima, utvrđen brvnima i jarkom; sjedište štaba, skupštine (Rada) i izabranog vojnog poglavara (koševoj), a ne državna prijestonica. U to doba «Hetmanat» još ne postoji (1648); ime Zaporožje znači «iza brzaka», a Sičevi stoje na stepskoj granici nizvodno od dnjeparskih brzaka. Etničkog srodstva s Kazacima Kazahstana nema: zaporoški kozaci istočnoslavenska su (ukrajinska) pravoslavna zajednica; zajednička je samo riječ turskog porijekla «kozak/kazak» (slobodni ratnik).", "ecc27d31"]},
"OLAYLAR_SEHIR_ILK:1628-01-01:0":{"b": ["Mikitinski Sič prvi put pomenut", "61e22abc"], "d": ["Ime četvrtog Siča, osnovanog na Mikitinom Rogu, na mjestu današnjeg Nikopolja, prvi put se javlja 1628; 1648. zauzeo ga je Bogdan Hmeljnicki. To je prvo poznato svjedočanstvo o mjestu, a ne njegovo osnivanje.", "63f059d0"]},
"OLAYLAR_SEHIR_ILK:1652-01-01:0":{"b": ["Osnovan Čortomlicki Sič", "4b6e8197"], "d": ["Zaporoški kozaci osnovali su na rtu gdje se Dnjepar spaja s rijekom Čortomlik Čortomlicki Sič, zvan i 'Stari Sič'. Sič je, jer su kozaci podržali Mazepu, 25. maja 1709. srušila ruska vojska.", "e7b8c2ca"]},
"OLAYLAR_SEHIR_ILK:1654-01-01:0":{"b": ["Harkov osnovali kozački doseljenici", "288b303c"], "d": ["Na sjevernom rubu divlje stepe, na spoju rijeka Lopan i Harkov, kozački doseljenici s desne obale Dnjepra osnovali su naselje. Harkov je ubrzo postao središte Slobodske Ukrajine vezane za Moskvu.", "0d185061"]},
"OLAYLAR_SEHIR_ILK:1711-01-01:0":{"b": ["Zaporoški kozaci s dozvolom krimskog kana osnovali Aleškivski Sič", "ed26f29d"], "d": ["Kada je ruska ofanziva natjerala na evakuaciju Siča na Kamenki, zaporoški kozaci s dozvolom krimskog kana nastanili su se na teritorijima kanata, u Aleškama na lijevoj obali rijeke Konke. Nakon Prutskog mira pridružili su im se i Gordijenkovi kozaci. Kan nije dozvolio da Sič ima bedeme i topove.", "acb5924a"]},
"OLAYLAR_SEHIR_ILK:1728-01-01:0":{"b": ["Aleškivski Sič opljačkan i napušten", "52361709"], "d": ["Proruski samarski kozaci napali su i opljačkali Aleškivski Sič i zapalili kasarne. Sič nije obnovljen; kozaci su se 1730. vratili na Kamenku, a 1734. zakleli se na vjernost Rusiji i osnovali Novi Sič.", "bf03f792"]},
"OLAYLAR_SEHIR_ILK:1738-01-01:0":{"b": ["Na obali Volge osnovana tvrđava Stavropolj", "eb087a50"], "d": ["Na srednjoj Volgi za Kalmike koji su prihvatili kršćanstvo osnovana je tvrđava Stavropolj (današnji Togljati).", "d486bb18"]},
"OLAYLAR_SEHIR_ILK:1738-03-24:0":{"b": ["Nadir-šah zauzeo Kandahar i dao srušiti stari grad", "9cc23e6b"], "d": ["Afšarski vladar Nadir-šah nakon duge opsade zauzeo je Kandahar, koji je bio u rukama gildžijskih Afganistanaca. Grad je razoren, a stanovništvo je preselilo u Nadirabad, osnovan jugoistočno od starog mjesta; stari Kandahar više nikada nije postao grad.", "c8df437b"]},
"OLAYLAR_SEHIR_ILK:1777-01-01:0":{"b": ["Na Azovsko-mozdočkoj liniji osnovana tvrđava Stavropolj", "7fd9b9f1"], "d": ["Na Azovsko-mozdočkoj utvrđenoj liniji, podignutoj nakon Kučuk-Kajnardže radi kontrole stepe između Kubana i Tereka, sagrađeno je deset tvrđava; jedna od njih bila je Stavropolj. Tvrđava je kasnije postala središte Kavkaskog namjesništva i Stavropoljske gubernije.", "f27157a3"]},
"OLAYLAR_SEHIR_ILK:1778-01-01:0":{"b": ["Na ušću Dnjepra osnovano hersonsko brodogradilište", "115f2c34"], "d": ["Na ušću Dnjepra, koje je nakon Kučuk-Kajnardže prešlo Rusiji, blizu utvrđenja Aleksandr-šanc, podignutog 1737. i ubrzo srušenog, osnovano je brodogradilište i nazvano Herson. Grad je 1784. postao središte sreza, a 1803. središte gubernije.", "a664a96e"]},
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["Grci s Krima osnovali Mariupolj na obali Azova", "4e3af209"], "d": ["Grci koji su došli s Krima osnovali su Mariupolj na mjestu gdje se Kalmijus ulijeva u Azovsko more. Grad je 1784. postao središte sreza vezanog za Jekaterinoslavsko namjesništvo.", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Jekaterinoslav preseljen na današnje mjesto na obali Dnjepra", "ec361381"], "d": ["Jekaterinoslav, koji je Potemkin 1778. osnovao na spoju rijeka Kilčen i Samara, zbog nezdravog položaja 1783. prenesen je na današnje mjesto.", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["U zaljevu Ahtijar osnovana ruska ratna luka Sevastopolj", "01058a25"], "d": ["Nakon ruske aneksije Krima 1783. za vojnu luku izabran je zaljev u kojem se nalazilo krimskotatarsko selo Ahtijar (Akjar); luka je osnovana sljedeće godine i dobila ime Sevastopolj. Grad je 1804. postao glavna luka ruske Crnomorske flote.", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["Na ušću Buga osnovano utvrđenje Nikolajev", "d57e52b9"], "d": ["Na spoju rijeka Južni Bug i Ingul po naređenju kneza Potemkina podignuto je utvrđenje. Godine 1788. tu je otvoreno brodogradilište i naselje je postalo jedno od brodograditeljskih središta Crnomorske flote.", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["Na obali Moločne osnovano pogranično naselje, jezgro Melitopolja", "637d5817"], "d": ["Nakon aneksije Krima na obali rijeke Moločne osnovano je pogranično naselje. Naselje je 1816. dobilo ime Novooleksandrivka, a 1841. pod imenom Melitopolj proglašeno je gradom.", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["Osnovan Novočerkask, novo središte Donske kozačke vojske", "bf5709fd"], "d": ["Upravno središte Donske kozačke vojske prešlo je iz Čerkaska, koji je do tada bio središte, u Novočerkask, osnovan na lokalitetu Birjučij Kut između rijeka Aksaj i Tuzlov.", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Vadi Halfa zabilježena na Burckhardtovom putovanju po Nubiji", "6efc72ec"], "d": ["Švicarski putopisac J. L. Burckhardt u dnevniku od 6. marta 1813. piše da je prošao kroz Vadi Halfu i da se tamo obavlja nešto trgovine. To je prvo datirano svjedočanstvo koje se moglo naći.", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["Na obali Azova osnovano pristanište Berdjansk", "908ac3cf"], "d": ["Na inicijativu kneza Mihaila Voroncova na mjestu gdje se rijeka Berda ulijeva u Azovsko more osnovan je Berdjansk. Naselje je 1835. postalo grad, a 1842. središte sreza.", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["Stanovnici Malatye ostaju u vinogradima Aspuzua — jezgro moderne Malatye", "d1dba159"], "d": ["Glavni osmanski stožer protiv egipatske vojske Ibrahim-paše u ljeto 1838. premješten je iz Mezraa u Malatyu. Stanovnici Malatye, koji su boravili u ljetnim kućama u Aspuzuu, nakon odlaska vojske nisu se vratili u zimske kuće u starom, razrušenom gradu; Aspuzu je postao jezgro moderne Malatye. Stara Malatya (Battalgazi) nastavila je živjeti smanjujući se.", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Van se podiže na novom mjestu — razrušeni stari grad se napušta", "6d278578"], "d": ["Van je oslobođen okupacije 2. aprila 1918. Povratnici su umjesto popravke starog Vana na obali jezera, razrušenog u ratnim godinama, sagradili novi grad oko 7 km od obale, na mjestu starih mahala Noršen i Arak. Stari grad je napušten.", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Maraš prešao Memlucima — alepski namjesnik Bilban et-Tabahi povratio ga od Armenaca", "03171265"], "d": ["Maraš, koji je od 1258. bio u rukama Kilikijskog armenskog kraljevstva, 1293. je ugovorom sultana Halila s Armencima na kratko prešao Memlucima, a nakon njihovog povlačenja ponovo pao u ruke Armenaca. Godine 697. (1298) memlučki namjesnik Alepa Bilban et-Tabahi povratio je grad. Maraš je zatim ostao memlučki teritorij do uspona Dulkadirovića.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["Bizantsko Carstvo postalo osmanski haračar", "615df998"], "d": ["Nakon pobjede kod Čirmena (1371) bizantski car Ivan V u zimu 1372. pristao je da postane haračar Murata I: plaćat će godišnji harač i davati vojnike za sultanove pohode. Bizant je od tog datuma do 1403. ostao vazalna država vezana za Osmanlije; blokada Bajazida I Munje 1391. povećala je harač. Nakon poraza kod Ankare Galipoljski ugovor sa šehzadom Sulejman-čelebijom (1403) oslobodio je Bizant harača; ugovorom s Muratom II 1424. harač je ponovo počeo.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Bajazid I Munja nakon Berkukove smrti pripojio osmanskim teritorijima Besni, Darende i Divrigi", "8e57d7e6"], "d": ["Kada su nakon smrti memlučkog sultana Berkuka (juna 1399) upravni poslovi Memlučke države zapali u nered, Bajazid I Munja spustio se u sliv Eufrata i uz Malatyu osmanskim teritorijima pripojio Besni (Behisni), Darende i Divrigi. Sivas je prije toga, nakon smrti kadije Burhanuddina u ljeto 1398, prepušten Osmanlijama. Divrigi je od 1391. bio pod memlučkom vlašću kao istureno uporište vezano za Alepski ejalet. Osmanska uprava ovdje nije dugo trajala: zbog približavajuće Timurove opasnosti Divrigi je 1401. ponovo vraćen Memlucima, a grad je konačno ušao pod osmansku upravu nakon Mardž Dabika 1516.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Besni prešao Memlucima tokom Timurovog pohoda na Sivas i Malatyu", "4853da9a"], "d": ["Besni, koji je Bajazid I Munja 1398. uzeo zajedno sa Sivasom, Darendeom i Malatyom, prešao je 1400, dok je Timur zauzimao Sivas i Malatyu, u ruke Memluka. Timur je 27. septembra 1400. nakon žestoke opsade zauzeo i Besni; kada se povukao iz tog kraja, Besni je ponovo došao pod memlučku vlast i ostao kod Memluka (osim jednog dulkadirovićkog međurazdoblja) dok ga u augustu 1516. nije zauzeo Selim Javuz.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Divrigi zbog Timurove opasnosti ponovo vraćen Memlucima", "97196b1f"], "d": ["Divrigi, koji je Bajazid I Munja 1398. uzeo od Memluka, 1401. ponovo je prepušten Memlucima zbog Timurovog približavanja Anadoliji. Zato se nakon Timurovog razaranja Sivasa (1400) Divrigi na karti prikazuje memlučkom bojom; istih je mjeseci Bajazid na istoku zauzimao Erzindžan i Kemah, tj. memlučki teritorij ostao je između osmanskih posjeda na zapadu (Sivas) i sjeveroistoku (Kemah). Divrigi je konačno prešao Osmanlijama tek nakon Mardž Dabika 1516.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["Memlučki sultan Šejh povratio Antep i Darende od Dulkadirovića", "f90c9508"], "d": ["Zabrinut zbog prijateljstva Dulkadirovića s Osmanlijama, memlučki sultan Šejh 1414. krenuo je u pohod; povratio je Antep i Darende, koje je ranije svojom voljom dao Dulkadirovićima.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Dulkadiroglu Mehmed-beg povratio Darende i Besni pripojio svojim teritorijima", "df914dcb"], "d": ["Darende, koji su Memluci uzeli 1414, Dulkadiroglu Mehmed-beg povratio je 1418, a Besni je pripojio svojim teritorijima.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Memluci kod Antepa porazili Dulkadiroviće; Besni se vratio pod memlučku upravu (približno)", "72742430"], "d": ["Memlučka vojska 1436. porazila je Dulkadiroviće kod Antepa, a Mehmed-beg povukao se na Akdag. Godina povratka Besnija Memlucima nije zapisana u izvoru; Besni je 1418. pripojen Dulkadiru, a Memlucima se vratio prije nego što ga je Šehsuvar-beg 1465. uzeo od Memluka. Atlas Besni vraća Memlucima (deklarirana približnost) zajedno s tim porazom kod Antepa, susjednog središta.", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Dulkadiroglu Šehsuvar-beg uzeo Besni od Memluka (približno)", "843f0fc4"], "d": ["Šehsuvar-beg (1465-1472), kojeg je sultan Mehmed Osvajač imenovao dulkadirovićkim begom, zauzeo je Besni, Gerger, Biredžik i Rumkale, koji su bili u memlučkim rukama; Memluci su poraženi u jesen 1467. kod Turnadaga, a u proljeće 1468. blizu Antepa.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["Emir Jašbak porazio Šehsuvar-bega; Besni se vratio pod memlučku upravu (približno)", "4d856aee"], "d": ["U proljeće 1471. emir Jašbak porazio je Šehsuvar-bega u dolini Savron; Memluci su povratili Kadirli i Kozan. Šehsuvar je 1472. pogubljen u Kairu, a Memluci su ponovo postavili Šahbudaka za bega. Tim je povratom i Besni ušao pod memlučku upravu (TDV besni: 'potkraj XV stoljeća ponovo je prešao u ruke Memluka').", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Ferdinandove snage zauzele i utvrdile Solnok", "6c8416e6"], "d": ["Dok su se Osmanlije spremale da sagrade tvrđavu u Solnoku na Tisi, snage Ferdinanda I pretekle su ih: sredinom septembra 1550. zauzele su Solnok, a tvrđava je sredinom oktobra osposobljena za odbranu. Tako je Solnok, koji je pripadao Izabelinoj zemlji, godinu prije prelaska Erdelja Ferdinandu prešao u habsburške ruke; Osmanlije su tvrđavu zauzele 1552.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["Erdelj prešao pod habsburšku upravu: sabor u Kolozsváru priznao Izabelino odricanje", "8458a566"], "d": ["Po Martinuzzijevom sporazumu s Ferdinandom kraljica Izabela je 19. juna 1551. u tvrđavi Szászsebes, u ime malog kralja Ivana Sigismunda (János Zsigmond), potpisala odricanje koje joj je nametnuto. Erdeljski sabor, okupljen 26. jula u Kolozsváru, priznao je to odricanje i vlast kralja Ferdinanda; habsburška vojska generala Castalda ušla je u erdeljski Beograd (Gyulafehérvár). Tako je Erdelj, vezan za Osmanlije, prešao pod habsburšku upravu koja će trajati pet godina.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Habsburška uprava u Erdelju okončana: Erdelj ponovo vojvodstvo vezano za Osmanlije", "721a482a"], "d": ["Preko svećenika Martinuzzija (Fráter György), hrvatskog porijekla, koji je zbog maloljetnosti Ivana Sigismunda postavljen za njegovog staratelja, Habsburgovci su 1551. pokušali zavladati Erdeljem; erdeljski Beograd (Gyulafehérvár), Kaloşvar, Brassó i Segesvár pet su godina ostali pod habsburškom upravom. Osmanlije su to spriječile i Erdelj je ponovo postao vojvodstvo koje plaća harač i vezano je za njih. Erdelj je zatim u XVI i XVII stoljeću oko 150 godina zadržao status zasnovan na širokoj autonomiji u unutrašnjim poslovima i vezanosti za Istanbul u vanjskim.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt i Tokaj prešli na stranu Zapolje", "587c782d"], "d": ["Nakon povratka Izabele i Ivana Sigismunda u Erdelj 1556, pristaše Zapolje opsjele su 1556. Nagyvárad. Godine 1557. aristokrati gornje Tise zauzeli su najvažnije kraljevske tvrđave — Várad, Huszt i Tokaj; u Ferdinandovim rukama ostale su samo Gyula i Világos. Várad je zatim postao tvrđava Erdeljske kneževine i tako ostao dok ga 1660. nisu zauzele Osmanlije.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi zauzeo Szatmár — sjeverni kraj Erdelja prešao Habsburgovcima", "2256bb27"], "d": ["Szatmár, koji je prelaskom Menyhérta Balasse na drugu stranu 1561. prešao Habsburgovcima, István Báthory povratio je prepadom u jesen 1564. i pripojio Erdelju. Habsburški zapovjednik Lazarus von Schwendi u februaru 1565. krenuo je u protivnapad: Tokaj je pao 9. februara, Szerencs četiri dana kasnije, a Szatmár je gotovo bez otpora prešao u ruke carskih snaga.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Bocskaijeve snage zauzele Szatmár", "e93b098b"], "d": ["Dok se Bocskaijev ustanak širio po sjeveroistočnoj Ugarskoj, Gyulaffy je 21. januara 1605. zauzeo Szatmár, koji je opsjedao. Bečkim mirom od 23. juna 1606. szatmárska županija doživotno je prepuštena Bocskaiju; kako nije bilo muškog nasljednika, smrću Bocskaija 29. decembra 1606. županija se vratila kraljevini.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Smrt Istvána Bocskaija — szatmárska županija vratila se kraljevini", "3721bb9b"], "d": ["Erdeljski knez István Bocskai umro je 29. decembra 1606. u Kassi. Bečkim mirom (23. juna 1606) županije, uključujući Szatmár, bile su mu prepuštene doživotno, s tim da se, ako ne bude muškog nasljednika, vrate kraljevini; po toj odredbi szatmárska županija vratila se habsburškoj Ugarskoj kraljevini. Erdelj je počeo tražiti novog kneza.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Gábor Bethlen preuzeo kontrolu nad szatmárskom županijom", "80263da1"], "d": ["Ugarskim pohodom Gábora Bethlena u jesen 1619. szatmárska županija došla je pod kontrolu erdeljskog kneza; u novembru 1619. već se pismom obraćao županiji. Preliminarni ugovor od 23. januara 1620. i Nikolsburški mir doživotno su Bethlenu prepustili sedam županija, uključujući i Szatmár. Nakon Bethlenove smrti (15. novembra 1629) povrat županija kraljevini dovršen je 30. marta 1630.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Dovršen povrat sedam županija Gábora Bethlena kraljevini", "31b5968f"], "d": ["Nikolsburškim mirom sedam gornjougarskih županija, uključujući Szatmár, doživotno je prepušteno Gáboru Bethlenu. Nakon Bethlenove smrti 15. novembra 1629. povrat županija kraljevini počeo je uputom od 30. novembra 1629. i dovršen je 30. marta 1630.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["György Rákóczi I preuzeo Szatmár", "f398635b"], "d": ["U pohodu erdeljskog kneza Györgya Rákóczija I 1644. njemački garnizon Szatmára prešao je u Rákóczijevu službu i tvrđava je prešla u ruke Erdelja. Linački mir od 16. decembra 1645. prepustio je tvrđavu Rákóczijevim nasljednicima dok na erdeljskom prijestolju bude neko iz roda Rákóczi.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Gubitak Nitre — De Souches povratio tvrđavu", "c71bf012"], "d": ["Nitru, koja se nakon kratkog otpora predala poslije osvajanja Uyvara (Nové Zámky) 1663, carski zapovjednik De Souches opsjeo je 15. aprila 1664; tvrđava se predala 3. maja 1664. Kako je Vasvarski mir zauzeta mjesta ostavio u zatečenom stanju, Uyvar je ostao kod Osmanlija, a Nitra u habsburškim rukama.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Gubitak Léve", "f311920e"], "d": ["Nakon Nitre De Souches je 9. juna 1664. opsjeo Lévu; kapitulacija je potpisana 13. juna, a 14. juna tvrđava je bila u rukama carskih snaga. Bitka kod Léve (Garamszentbenedek) 19. jula 1664. nije promijenila vlasništvo; završila je tako što su Habsburzi zadržali Lévu i Nitru.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Dorošenko predao Čigirin Samojloviču", "3b538237"], "d": ["Hetman desne obale pod osmanskom zaštitom Petro Dorošenko 19. septembra 1676. predao je svoju prijestonicu Čigirin hetmanu lijeve obale Samojloviču i ruskim snagama. Osmanlije su smijenile Dorošenka i na njegovo mjesto postavile Jurija Hmeljnickog; opsada 1677. s ciljem istjerivanja ruskog garnizona iz Čigirina ostala je bez uspjeha, a tvrđava je zauzeta tek 21. augusta 1678.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Predaja banatskih tvrđava Erdelja (Temišvar, Lipova, Lugoš, Karanšebeš) ugarskom kralju Ferdinandu", "0e354976"], "d": ["Godine 1551. habsburška vojska pod komandom generala Castalda ušla je u Erdelj; kraljica Izabela i njen sin bili su prisiljeni odreći se prava na ugarsko prijestolje. Martinuzzi je sredinom jula 1551, uz Castaldovo odobrenje, poslao Endrea Báthoryja da u ime Ferdinanda preuzme tvrđave Temišvar, Lipovu, Šolimoš, Karanšebeš, Lugoš, Becse, Bečkerek i Čanad. Južne tvrđave Erdelja pod osmanskom zaštitom tako su prešle u habsburške ruke; Zakonodavčevi pohodi 1551-1552. odgovor su na to.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Petrovics Péter imenovan sandžakbegom Lugoša i Karanšebeša", "bcbe73e4"], "d": ["Na uporne molbe Izabele i Petrovicsa, Sulejman Zakonodavac odlučio je vratiti malog Ivana Sigismunda u Erdelj. Pismom napisanim u Alepu 7. aprila 1554. naredio je Erdelju da dijete vrate u njegovu zemlju; naredio je i vlaškom i moldavskom vojvodi da u tom poslu pomognu Petrovicsu, kojeg je istovremeno imenovao sandžakbegom Lugoša i Karanšebeša. Lugoš, osvojen 1552, tako je kao osmanski sandžak dat Petrovicsu.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Dignuta opsada Lipove — prepad lugoškog bana na Temišvar", "be03430e"], "d": ["U proljeće 1596. temišvarski paša opsjeo je Lipovu. U noći s 10. na 11. maja, po naređenju erdeljskog lugoškog bana Györgya Palaticsa, vojnici Györgya Budaya napali su i zapalili temišvarska predgrađa; to što je György Borbély u tvrđavi dao ispaliti sve topove uvjerilo je pašu da je stigla pomoć. Paša se 11. maja povukao ispred Lipove i pohitao da brani vlastito središte. Lugoš je tada bio u rukama Erdeljske kneževine.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Austrijske snage pod komandom Veteranija okupirale Oršavu", "1b4a4f6c"], "d": ["U pohodu 1688. general Veterani je nakon zauzimanja Karanšebeša krenuo na Oršavu i okupirao i nju. U izvoru nema dana okupacije; korištena je godišnja osnova, 1. januar 1688.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Thököly i osmanske snage povratili Oršavu", "c5645da9"], "d": ["Na Oršavu, koju je Veterani okupirao 1688, nakon zauzimanja Vetislana krenuli su Thököly i osmanske paše. Nakon beznačajnih sukoba Thököly je 15. jula 1689. ušao u Oršavu. Heissler, koji je stigao na vijest o opasnosti, vidjevši da je snaga pred njim dobro opremljena municijom i brodovima, povukao se da brani Erdelj. Ni Herbevilleov napad pred gradom u augustu nije povratio Oršavu.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Lugoški sandžak pao pod habsburšku okupaciju (1691-1695)", "c8bcd6bd"], "d": ["Lugoški sandžak bio je 1691-1695. pod habsburškom (njemačkom) okupacijom; Mustafa II ponovo ga je osvojio 22. septembra 1695. U starom zapisu razdoblje 1689-1695. bila je deklarirana praznina; dio 1691-1695. sada se boji kao habsburški, a 1689-1691. ostaje praznina. Datum je uzet samo kao godina.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["Tvrđava Lugoš ušla pod habsburšku upravu", "6a9d401f"], "d": ["Lugoj, sandžačka tvrđava vezana za Temišvarski ejalet, od 1695. bio je u osmanskim rukama; predajom središta ejaleta na kraju opsade 1716. prepušten je Habsburškoj Monarhiji. Stari zapis stavljao je prijenos na 1. januar 1716, godišnju osnovu.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Habsburška vojska zauzela Oršavu (pohod 1717)", "7a4faffe"], "d": ["U pohodu 1717. general Splényi stigao je 27. augusta pred Oršavu i lako zauzeo grad; Oršava, koju Mercy 1716. nije uspio zauzeti, tako je prešla u habsburške ruke. Budući da su okolna dunavska priobalna saća (uključujući đerdapski dio na srpskoj strani) vezana za najbližu naseobinsku tačku, Oršavu, boje se bojom njenog vlasnika. Datum je uzet samo kao godina; tačan dan nije potvrđen.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Palanka Oršava prelazi Osmanlijama — posada se povukla na Ada Kale", "de759b16"], "d": ["Na početku pohoda 1738. vidinski muhafiz Hadži Mehmed-paša napao je utvrdu Erzsébet na Dunavu. Popodne 8. maja odred spahija od 4-5 hiljada ljudi krenuo je s lijeve obale Dunava na Oršavu i napao palanku Oršavu; austrijska posada, koja je pretrpjela oko stotinu gubitaka, povukla se u Novu Oršavu, tj. otočku tvrđavu Ada Kale. Nakon sukoba kod Mehadije u julu, i Ada Kale je u augustu 1738. prešla u osmanske ruke; Beogradski mir 1739. priznao je to stanje.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Murat II zauzeo Alaca-Hisar (Kruševac), Niš i Pirot (Šehirköy) vratili se Osmanlijama", "54af926a"], "d": ["Nakon smrti srpskog despota Stefana Lazarevića bez nasljednika (1427), Murat II, pozivajući se na brak Bajazida I Munje sa srpskom princezom, ustvrdio je da je zakoniti nasljednik Srbije, krenuo u akciju i zauzeo Alaca-Hisar (1428). Iste godine, nakon Lazarevićeve smrti, Osmanlije su povratile i tvrđavu Šehirköy — grad je 1412. zauzeo Stefan i branio ga od Musa-čelebije. Prema članku nis u TDV, Osmanlije su iste godine (831/1428) povratile i Niš. Tako je pod osmansku kontrolu ušla linija koja povezuje doline Velike Morave i Nišave.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["Krstaška vojska zauzela Pirot — nišavski krak 'Duge vojne'", "fdf6140c"], "d": ["Krstaška vojska pod vodstvom kralja Vladislava i srpskog despota Đurađa Brankovića 1443. zauzela je Pirot. U nastavku istog pohoda osmanske snage će u novembru biti poražene na prijevoju Zlatica (Izladi). Pirot je nakon Segedinskog mira (1444) Murat II ponovo dao Srbima, ali je 1456, nakon smrti Đurađa Brankovića, prešao Osmanlijama.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["U kraju Alaca-Hisara uspostavljena konačna osmanska vlast", "9715382a"], "d": ["Alaca-Hisar, koji je po sporazumu s ugarskim delegatima 1444. prepušten Brankoviću, u godinama nakon pobjede kod Varne ponovo je ušao pod tursku vlast. To drugo osvajanje grada nije dokumentirano ratnim, nego finansijskim zapisom: zapisi o timarima za neka sela vezana za Alaca-Hisar datiraju se na kraj 1453 / početak 1454; no to je samo svjedočanstvo o selima — 1454. osmanske snage poražene su u okolini Alaca-Hisara, a 1455. Alaca-Hisar je kao granica prepušten Brankoviću. Prema TDV, konačna osmanska vlast u kraju uspostavljena je 1458.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Osnivanje Morejske despotovine — Manuel Kantakuzin u Mistri", "87660b82"], "d": ["Bizantski car Ivan Kantakuzin dao je sinu Manuelu zasebnu upravnu oblast u Moreji; tako je nastala Morejska despotovina sa središtem u Mistri. Manuel je vladao do 1380; u tom su se periodu bizantska kultura i umjetnost razvijale naročito u Mistri. Despotovina je trajala do osvajanja sultana Mehmeda Osvajača 1460.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Despot Konstantin uzeo Patras od Franaka", "cb0dd18c"], "d": ["Morejski despot Konstantin (1449. posljednji bizantski car) povratio je Patras od Latina; tako je i ta važna luka na sjeverozapadu poluotoka pripojena despotovini. Patras je 1458, u Osvajačevom pohodu na Moreju, ušao pod osmansku vlast.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčić Kosača 'herceg od Svetog Save' — rođenje Hercegovine", "cc67061f"], "d": ["Stjepan Vukčić Kosača, koji je Hum i Trebinje ujedinio u jednom posjedu, pobunio se protiv bosanskog kralja i proglasio se 'hercegom od Svetog Save'; titulu mu je 1448. dao car Friedrich III. Ime Hercegovina ('hercegova zemlja') potječe od te titule. Hercegovina je od 1466. dio po dio prelazila Osmanlijama, 1470. postala je sandžak; preostali teritoriji pripojeni su početkom 1482.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Krakovski mir — država Njemačkog reda pretvorena u Prusko vojvodstvo", "78666ddd"], "d": ["Veliki majstor teutonskih vitezova Albrecht Brandenburški, ne našavši pomoć protiv Poljske, potpisao je Krakovski mir. Država Reda (Ordensstaat) postala je, pod vrhovništvom Poljske, nasljedno i svjetovno vojvodstvo koje je prešlo na brandenburšku dinastiju. Središte je bio Königsberg; Albrecht je tu 1544. osnovao Univerzitet Albertus. Vojvodstvo se 1701. pretvorilo u Kraljevinu Prusku.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Proglašenje Republike Austrije — kraj Habsburške monarhije", "c84f316c"], "d": ["Dan nakon što se car Karlo I 11. novembra povukao iz državnih poslova, Privremena nacionalna skupština usvojila je zakon o obliku države i vlade i proglašena je republika. Habsburšku Austriju zamijenila je Prva republika sa središtem u Beču. Tim su proglasom Beč, Linz, Salzburg, Innsbruck, Klagenfurt, Bregenz i drugi njemačko-austrijski gradovi postali teritorij Republike Austrije (Deutschösterreich).", "2dcc1399"]},
"OLAYLAR_T5_1000A:1008-01-01:0":{"b": ["Batum pod vlašću Gruzijskog kraljevstva/kraljevstava — datirano svjedočenje u izvoru", "62cd2833"], "d": ["Izvor u tom datumu grad Batum prikazuje pod upravom Gruzijskog kraljevstva/kraljevstava; ranija pripadnost u izvoru nije datirana (atlas razdoblje prije tog datuma ostavlja prazno).", "e03655c9"]},
"OLAYLAR_T5_1000A:1024-01-01:0":{"b": ["Mervanid Nasruddevle pripojio Amid svom emiratu", "9fbc8c85"], "d": ["Mervanidski emir Nasruddevle Ahmed pripojio je Amid (Dijarbekir) teritorijama emirata; iduće godine zauzeo je i Urfu.", "d585a28b"]},
"OLAYLAR_T5_1000A:1054-01-01:0":{"b": ["Maraga došla pod seldžučku vlast", "c011cac9"], "d": ["Maraga, koja je bila u rukama Revvadida, došla je pod seldžučku vlast azerbejdžanskim pohodom Tugrul-bega.", "2ff74d2d"]},
"OLAYLAR_T5_1000A:1055-12-18:0":{"b": ["Tugrul-beg ušao u Bagdad", "38af55c2"], "d": ["Tugrul-beg, koji je na poziv halife Kaima bi-Emrillaha došao u Bagdad, okončao je buvejhidsku vlast.", "f7f905d1"]},
"OLAYLAR_T5_1000A:1056-01-01:0":{"b": ["Mosul prešao u ruke Seldžuka", "20b8da93"], "d": ["Mosul je zajedno s Irakom prešao Seldžucima; uprkos kratkom Besasirijevom zaposjedanju, četiri godine ostao je u seldžučkim rukama.", "a55cff1d"]},
"OLAYLAR_T5_1000A:1061-01-01:0":{"b": ["Mosul ponovo kod Ukajlida", "8b7c0603"], "d": ["Mosul je 1061. ponovo došao pod ukajlidsku vlast; i nakon seldžučkog zauzimanja 1084. Melik-šah je grad vratio ukajlidskom emiru.", "71824a2b"]},
"OLAYLAR_T5_1000A:1064-01-01:0":{"b": ["Alp Arslan okončao Nahčivanski šahluk", "5620360e"], "d": ["Alp Arslan, koji je porazio Revvadide, ukinuo je Nahčivanski šahluk koji su osnovali Dulefidi.", "f9fd7d73"]},
"OLAYLAR_T5_1000A:1071-01-01:0":{"b": ["Emir Saltuk osvojio Erzurum", "f52c09dd"], "d": ["Nakon Malazgirta Alp Arslan je okolinu Erzuruma dodijelio kao iktu emiru Saltuku; Saltuk je iste godine zauzeo grad i osnovan je Saltukidski bejluk (prema Yinançu 1080).", "505fcc25"]},
"OLAYLAR_T5_1000A:1071-01-01:1":{"b": ["Danišmend-gazi osvojio Sivas", "348d7ad3"], "d": ["Danišmend-gazi, koji je zauzeo Sivas što mu je nakon Malazgirta dodijeljen kao ikta, ondje je osnovao jezgro dinastije (datum osvajanja sporan; postoji i predanje o 1080).", "b9b5dd65"]},
"OLAYLAR_T5_1000A:1074-01-01:0":{"b": ["Filaret zauzeo Malatju", "9c80e3bd"], "d": ["Filaret, koji je u Kilikiji osnovao armensku kneževinu, zauzeo je Malatju predstavljajući se kao bizantijski predstavnik i upravljao je preko namjesnika (Gabriel i dr.).", "958ede64"]},
"OLAYLAR_T5_1000A:1074-01-01:1":{"b": ["Emir Danišmend osvojio Tokat", "c9321fb6"], "d": ["Nakon pobjede kod Malazgirta emir Danišmend uzeo je Tokat od Bizanta.", "dcc7f8e2"]},
"OLAYLAR_T5_1000A:1085-01-01:0":{"b": ["Seldžuci uzeli Hasankeyf od Mervanida", "4fa9d559"], "d": ["Za Melik-šaha Seldžuci su okončali mervanidsku vlast i uzeli i Hasankeyf.", "b9794646"]},
"OLAYLAR_T5_1000A:1085-05-31:0":{"b": ["Sin Fahruddevle uzeo Amid, mervanidska vlast završena", "ecaf6b03"], "d": ["Zaimurrusa, sin Fahruddevle ibn Džehira kojeg je zadužio Melik-šah, uzeo je Amid od Mervanida.", "8745ce9d"]},
"OLAYLAR_T5_1000A:1093-01-01:0":{"b": ["Tutuš zauzeo Dijarbekir", "469b8ebc"], "d": ["Nakon Melik-šahove smrti Tutuš, koji je polagao pravo na sultanat, zauzeo je područje Dijarbekira i zarobio posljednjeg mervanidskog emira Mansura.", "52daa285"]},
"OLAYLAR_T5_1000A:1095-01-01:0":{"b": ["Turkmenski beg Sadr počeo vladati Amidom", "3d67b786"], "d": ["Nakon Tutuševe smrti turkmenski beg Sadr zagospodario je Amidom; njegov nasljednik Inal osnovao je dinastiju Inalogullari.", "5fdca35c"]},
"OLAYLAR_T5_1000A:1096-01-01:0":{"b": ["Kurboga zauzeo Mosul", "462a238f"], "d": ["Seldžučki emir Kurboga uzeo je Mosul od Ukajlida. (Zul-kade 489 / novembar 1096; atlas, prateći zapis države, piše s preciznošću do godine.)", "14d9ca6d"]},
"OLAYLAR_T5_1000A:1100-01-01:0":{"b": ["Niksar pod vlašću Danišmendida — datirano svjedočenje u izvoru", "81181870"], "d": ["Izvor u tom datumu grad Niksar prikazuje pod upravom Danišmendida; ranija pripadnost u izvoru nije datirana (atlas razdoblje prije tog datuma ostavlja prazno).", "c1463e88"]},
"OLAYLAR_T5_1000A:1102-09-18:0":{"b": ["Danišmendid Gumuštegin-gazi zauzeo Malatju", "87f1166c"], "d": ["Gumuštegin-gazi na kraju opsade zauzeo je Malatju.", "2d0e9668"]},
"OLAYLAR_T5_1000A:1106-09-02:0":{"b": ["Kilidž Arslan I primio predaju Malatje", "eca366d5"], "d": ["Nakon Gumušteginove smrti Kilidž Arslan I opsadom dužom od dva mjeseca pripojio je Malatju seldžučkim teritorijama.", "69bdbc2c"]},
"OLAYLAR_T5_1000A:1108-03-04:0":{"b": ["Mezjedid Sadaka poginuo kod Numanije, Hilla prešla Seldžucima", "e5ecea7c"], "d": ["Muhammed Tapar porazio je Sadaku; njegov sin Dubejs zarobljen je i nije mu dopušten povratak u Hillu.", "be1e2910"]},
"OLAYLAR_T5_1000A:1111-01-01:0":{"b": ["Ilarslan povratio Elbistan od Tankreda", "923962c2"], "d": ["Elbistan, koji je zauzeo antiohijski knez Tankred, povratio je Ilarslan, atabeg melika Malatje Tugrul Arslana.", "ce0754bd"]},
"OLAYLAR_T5_1000A:1112-01-01:0":{"b": ["Artukid Belek zagospodario Harputom", "83425a6e"], "d": ["Belek b. Behram, unuk Artuk-bega, zagospodario je Harputom i osnovao svoj bejluk sa središtem u Paluu.", "ff838897"]},
"OLAYLAR_T5_1000A:1116-01-01:0":{"b": ["Niğde pod vlašću Anadolijske (Turske) seldžučke države — datirano svjedočenje u izvoru", "dfb24c4b"], "d": ["Izvor u tom datumu grad Niğde prikazuje pod upravom Anadolijske (Turske) seldžučke države; ranija pripadnost u izvoru nije datirana (atlas razdoblje prije tog datuma ostavlja prazno).", "477146f3"]},
"OLAYLAR_T5_1000A:1117-01-01:0":{"b": ["Dubejs se vratio u Hillu", "9bc0e03a"], "d": ["Nakon smrti Muhammeda Tapara Dubejs je u doba iračkog seldžučkog sultana Mahmuda mogao otići u Hillu.", "d9aec87c"]},
"OLAYLAR_T5_1000A:1118-05-06:0":{"b": ["Mahmud u Bagdadu proglašen iračkim seldžučkim sultanom — osnovana Iračka seldžučka država", "18babf94"], "d": ["Nakon smrti Muhammeda Tapara halifa je njegovog sina Mahmuda proglasio sultanom; osnovana je Iračka seldžučka država. Bagdad s Mosulom i Tikritom ostao je vezan za Irački seldžučki sultanat, a Azerbejdžan (Maraga, Nahčivan) pripao je iračkom seldžučkom dijelu. Tikrit se u izvoru te godine pominje kao ikta bagdadskog šahne.", "cf36af86"]},
"OLAYLAR_T5_1000A:1119-01-01:0":{"b": ["Ivan II Komnen povratio Denizli", "cb523c0f"], "d": ["Bizantijski car Ivan II Komnen prisilio je seldžučkog komandanta Laodikeje Alp Karu na povlačenje; teritorije Denizlija ponovo su prešle Bizantu (članak o Bizantu navodi 1120).", "8bdb49b8"]},
"OLAYLAR_T5_1000A:1120-01-01:0":{"b": ["Aksunkur el-Ahmedili poslan u Maragu", "7a3d6deb"], "d": ["Sultan Mahmud poslao je Aksunkura el-Ahmedilija u Maragu; u gradu se ustalio ahmedilijski atabegat.", "3616b62c"]},
"OLAYLAR_T5_1000A:1124-12-10:0":{"b": ["Danišmendid emir Gazi primio predaju Malatje; i Elbistan prešao Danišmendidima", "97f3f958"], "d": ["Nakon Belekove smrti emir Gazi dugom je opsadom uzeo Malatju od seldžučkog melika Tugrul Arslana; zauzimanjem oblasti Malatje i Elbistan je došao pod danišmendidsku upravu.", "ae95651d"]},
"OLAYLAR_T5_1000A:1127-01-01:0":{"b": ["Emir Gazi uzeo Ankaru od Seldžuka", "25b745cd"], "d": ["Danišmendid emir Gazi porazio je Melika Araba, sina Kilidž Arslana I, i uzeo mu Ankaru.", "008f5e3f"]},
"OLAYLAR_T5_1000A:1127-01-01:1":{"b": ["Imaduddin Zengi atabeg Mosula (Zengidi)", "ba79276b"], "d": ["Irački seldžučki sultan Mahmud dao je Mosul kao iktu Imaduddinu Zengiju; osnovan je Mosulski atabegat.", "a1929772"]},
"OLAYLAR_T5_1000A:1134-01-01:0":{"b": ["Kayseri pod vlašću Danišmendida — datirano svjedočenje u izvoru", "3b9b8604"], "d": ["Izvor u tom datumu grad Kayseri prikazuje pod upravom Danišmendida; ranija pripadnost u izvoru nije datirana (atlas razdoblje prije tog datuma ostavlja prazno).", "e82b707e"]},
"OLAYLAR_T5_1000A:1142-01-01:0":{"b": ["Kemah pod vlašću Mengudžekida (Mengücekogullari) — datirano svjedočenje u izvoru", "d86927c6"], "d": ["Izvor u tom datumu grad Kemah prikazuje pod upravom Mengudžekida (Mengücekogullari); ranija pripadnost u izvoru nije datirana (atlas razdoblje prije tog datuma ostavlja prazno).", "fcb6186c"]},
"OLAYLAR_T5_1000A:1144-01-01:0":{"b": ["Sultan Mesud zauzeo Elbistan", "825e2c56"], "d": ["Mesud I zauzeo je Elbistan i Džejhan koji su bili u rukama Ajnuddevle i za melika postavio sina Kilidž Arslana.", "d69cdacb"]},
"OLAYLAR_T5_1000A:1148-01-01:0":{"b": ["Nahčivan pripojen Ildegizidima", "774400cc"], "d": ["Raspadom Seldžuka Nahčivan se pripojio državi Ildegizida i do 1174. bio njihovo središte (godina pripajanja nije navedena; početak dinastije).", "bf42d3bd"]},
"OLAYLAR_T5_1000A:1149-01-01:0":{"b": ["Tikrit prešao Begteginidima (EI2)", "a2caf5af"], "d": ["Prema onome što TDV prenosi iz EI2, Tikrit je od 1149. do 1190. bio pod vlašću Begteginida.", "d10d23e8"]},
"OLAYLAR_T5_1000A:1150-04-30:0":{"b": ["Sultan Mesud dao Hillu Salarkerdu", "4bdbd034"], "d": ["Nakon smrti Mezjedida Alija sultan Mesud dao je Hillu svom komandantu Salarkerdu.", "059e9aeb"]},
"OLAYLAR_T5_1000A:1152-04-08:0":{"b": ["Sultan Mesud umro; halifa Muktefi postao jedini gospodar Iraka, zauzeo Hillu, Kufu i Vasit", "21192405"], "d": ["Smrću sultana Mesuda halifa Muktefi li-Emrillah uspostavio je u Bagdadu i Iraku vlast nezavisnu od seldžučkog uticaja; halifin vezir zauzeo je Hillu, a zauzeti su i Kufa i Vasit.", "cd348b82"]},
"OLAYLAR_T5_1000A:1156-01-01:0":{"b": ["Jagibasan zauzeo Elbistan", "824708d3"], "d": ["Nakon Mesudove smrti danišmendidski melik Sivasa Jagibasan zauzeo je Elbistan; sporazumom mu je ostavljena uprava.", "d413e508"]},
"OLAYLAR_T5_1000A:1156-01-01:1":{"b": ["Seldžučki komandanti zauzeli Hillu, Mezjedidi podređeni namjesniku", "43afd955"], "d": ["Hillu su zauzeli komandanti sultana Muhammeda b. Mahmuda; Mezjedidi su vladali kao podređeni sultanovom namjesniku.", "c6c81147"]},
"OLAYLAR_T5_1000A:1160-01-01:0":{"b": ["Baku pod vlašću Širvanšaha — datirano svjedočenje u izvoru", "1f2863e4"], "d": ["Izvor u tom datumu grad Baku prikazuje pod upravom Širvanšaha; ranija pripadnost u izvoru nije datirana (atlas razdoblje prije tog datuma ostavlja prazno).", "506dae86"]},
"OLAYLAR_T5_1000A:1163-01-01:0":{"b": ["Halifa Mustendžid zauzeo Hillu, Mezjedidi prestali", "4348923c"], "d": ["Jedinice halife Mustendžida i Benu Muntefika zaposjele su Hillu, a Mezjedidi su rastjerani.", "da071466"]},
"OLAYLAR_T5_1000A:1165-01-01:0":{"b": ["Kilidž Arslan II zauzeo Elbistan i Darendu", "7c109007"], "d": ["Kilidž Arslan II, koristeći sukob među Danišmendidima, zauzeo je Elbistan, Darendu i oblast Geduk.", "d258bac6"]},
"OLAYLAR_T5_1000A:1172-01-01:0":{"b": ["Rupenid Mleh uzeo Tarsus od Bizanta", "2f98fd11"], "d": ["Rupenid Mleh je uz pomoć Nuruddina Zengija povratio Adanu, Misis i Tarsus od Bizantinaca.", "e1cfa006"]},
"OLAYLAR_T5_1000A:1174-01-01:0":{"b": ["Ildegizid Pehlivan zauzeo Tabriz", "f0831f17"], "d": ["Ildegizid Pehlivan mirnim je putem uzeo Tabriz od Ahmedilida i dao ga bratu Kizil Arslanu.", "81ee8ab8"]},
"OLAYLAR_T5_1000A:1175-01-01:0":{"b": ["Kilidž Arslan II uzeo Sivas i Niksar od Danišmendida", "584575bb"], "d": ["Nakon smrti Nuruddina Zengija Kilidž Arslan II je u ljeto 1175. zauzeo Sivas, Niksar, Tokat i ostale danišmendidske teritorije; sivaski ogranak prestao je.", "c8092aea"]},
"OLAYLAR_T5_1000A:1178-10-25:0":{"b": ["Kilidž Arslan II zauzeo Malatju, danišmendidski ogranak ugašen", "3bdbb060"], "d": ["Četveromjesečnom opsadom Malatja je prešla Seldžucima i malatjanski ogranak Danišmendida prestao je.", "b92d6ebb"]},
"OLAYLAR_T5_1000A:1183-04-29:0":{"b": ["Saladin zauzeo Amid i dao ga Artukidu Nuruddinu Muhammedu", "8c3cc7bb"], "d": ["Saladin Ejubi opsadom je zauzeo Amid i dao ga artukidskom emiru Hisnkajfe Nuruddinu Muhammedu; Inalogullari su prestali.", "b16cdda4"]},
"OLAYLAR_T5_1000A:1184-01-01:0":{"b": ["Ruben III povratio Adanu od krstaša", "e9876f85"], "d": ["Misis, Adanu i Tel Hamdun, koji su nakon Mleha neko vrijeme bili kod krstaša, povratio je 1184. Rupenid Ruben III.", "177b5432"]},
"OLAYLAR_T5_1000A:1190-01-01:0":{"b": ["Tikrit prešao Abasidima", "e8f5aeac"], "d": ["Nakon begteginidske vlasti grad je prešao pod upravu abasidskog hilafeta.", "f91cfb0d"]},
"OLAYLAR_T5_1000A:1194-01-01:0":{"b": ["Ruknudin Sulejman-šah II povratio Samsun", "0971ebcd"], "d": ["Samsun i istočnocrnomorske teritorije, koje su tokom bratskih sukoba prešle Komnenima, povratio je Sulejman-šah.", "940e4b5b"]},
"OLAYLAR_T5_1000A:1199-01-06:0":{"b": ["Adana i Tarsus: rupenidska kneževina pretvorena u Armensko kraljevstvo Kilikije", "de3c4beb"], "d": ["Rupenidska dinastija, koja je držala Adanu i Tarsus, preuzela je kraljevsku titulu; to je promjena titule iste dinastije, teritorija nije promijenila ruke. Dan krunisanja NIJE NAĐEN u TDV — datum je preuzet iz početka zapisa o Armenskom kraljevstvu Kilikije (dan iz zapisa države nije izvor).", "be8faf2b"]},
"OLAYLAR_T5_1000A:1204-01-01:0":{"b": ["Osnovano Trapezuntsko Carstvo — Giresun i Sinop u njegovim granicama", "a99b6ba0"], "d": ["Aleksije Komnen, koji je nakon što su Latini zauzeli Istanbul pobjegao u Trapezunt, proglasio se carem; grad je postao središte nove države. Država koju su osnovali komnenski potomci Aleksije i David prostirala se do Sinopa; i Giresun je ostao u granicama Trapezuntskog Carstva.", "dd95df25"]},
"OLAYLAR_T5_1000A:1204-04-13:0":{"b": ["Kütahya pod vlašću Nikejskog (Laskaridskog) Carstva — datirano svjedočenje u izvoru", "d91fa405"], "d": ["Izvor u tom datumu grad Kütahyu prikazuje pod upravom Nikejskog (Laskaridskog) Carstva; ranija pripadnost u izvoru nije datirana (atlas razdoblje prije tog datuma ostavlja prazno).", "50f100b1"]},
"OLAYLAR_T5_1000A:1205-01-01:0":{"b": ["Ildegizid Ebu Bekr uzeo Maragu", "03faed10"], "d": ["Ahmedilid Alaudin Korpe Arslan bio je prisiljen tvrđavu Maragu prepustiti ildegizidskom atabegu Ebu Bekru.", "742aae78"]},
"OLAYLAR_T5_1000A:1206-01-01:0":{"b": ["Seldžuci osvojili Denizli i Honaz", "1053ccc8"], "d": ["U drugoj vladavini Gijasudina Kejhusreva I Denizli i Honaz prešli su Seldžucima (bizantijski izvori kažu 1196, a članak o Seldžucima 603/1207).", "c102dae3"]},
"OLAYLAR_T5_1000A:1208-07-16:0":{"b": ["Gijasudin Kejhusrev I ponovo pripojio Maraş Seldžucima", "91b1544e"], "d": ["Kejhusrev je poveo pohod protiv Armenaca i pripojio Maraş seldžučkim teritorijama.", "5ffaa2f3"]},
"OLAYLAR_T5_1000A:1211-01-01:0":{"b": ["Kastamonu pod vlašću Čobanogullara — datirano svjedočenje u izvoru", "10b682ba"], "d": ["Izvor u tom datumu grad Kastamonu prikazuje pod upravom Čobanogullara; ranija pripadnost u izvoru nije datirana (atlas razdoblje prije tog datuma ostavlja prazno).", "1cdb9e90"]},
"OLAYLAR_T5_1000A:1214-11-02:0":{"b": ["Izzudin Kejkavus I osvojio Sinop", "463ea2b9"], "d": ["Seldžučki sultan Izzudin Kejkavus I uzeo je Sinop od trapezuntskih Komnena.", "0a71d5c6"]},
"OLAYLAR_T5_1000A:1222-01-01:0":{"b": ["Alaudin Kejkubad I zauzeo Kalonoros (Alaiju)", "5a4d6ac2"], "d": ["Seldžuci su zauzeli tvrđavu Kalonoros istočno od Antalije, ponovo je izgradili i ona je dobila ime Alaija (članak o Alanyi navodi 1221).", "a00756da"]},
"OLAYLAR_T5_1000A:1225-01-01:0":{"b": ["Dželaluddin Horezmšah anektirao Azerbejdžan", "5b812b99"], "d": ["Dželaluddin Horezmšah pripojio je svojim teritorijama Azerbejdžan i Arran (rečenica o području).", "5bba4780"]},
"OLAYLAR_T5_1000A:1225-07-01:0":{"b": ["Dželaluddin Horezmšah zauzeo Maragu", "a55ec004"], "d": ["Dželaluddin Horezmšah zauzeo je Maragu i učinio je vojnim i upravnim središtem u Azerbejdžanu.", "2aa8a852"]},
"OLAYLAR_T5_1000A:1225-07-25:0":{"b": ["Dželaluddin Horezmšah ušao u Tabriz", "72904097"], "d": ["Kada se atabeg Özbek povukao u Gandžu, Dželaluddin Horezmšah ušao je u Tabriz, zagospodario gradom i učinio ga svojim središtem.", "43ee9867"]},
"OLAYLAR_T5_1000A:1228-01-01:0":{"b": ["Alaudin Kejkubad zauzeo Kemah", "8c5aa655"], "d": ["Kemaško-erzindžanski ogranak Mengudžekida pripojio je seldžučkim teritorijama Alaudin Kejkubad I, koji je opsadom zauzeo Kemah.", "7edb7223"]},
"OLAYLAR_T5_1000A:1231-01-01:0":{"b": ["Mongoli drugi put zauzeli Maragu", "f1320e5d"], "d": ["Na kraju horezmšahovske vlasti Maraga je prešla u ruke Mongola.", "9cee2a89"]},
"OLAYLAR_T5_1000A:1231-01-01:1":{"b": ["Azerbejdžan došao pod mongolsku vlast — Tabriz pao pod mongolsku okupaciju", "3f38ef66"], "d": ["Slomom Dželaluddina Horezmšaha Tabriz je 1231. pao pod mongolsku okupaciju; mongolska vlast iste je godine obuhvatila sjeverni i južni Azerbejdžan (rečenica o području, nije specifična za grad). U Širvanu (Baku, Šemaha) Širvanšasi su pod mongolskom vlašću nastavili postojati kao lokalna dinastija; atlas ove dvije tačke po Emreovoj odluci drži u boji širvanšaha (mongolska/ilhanatska vazalnost u napomeni).", "46225c2e"]},
"OLAYLAR_T5_1000A:1232-10-01:0":{"b": ["Ejubid el-Melik el-Kamil zauzeo Amid", "9cebe681"], "d": ["El-Melik el-Kamil opsadom je uzeo Amid od Artukida.", "02085ee1"]},
"OLAYLAR_T5_1000A:1233-01-01:0":{"b": ["Alaudin Kejkubad I uzeo Kütahyu od Nikejskog Carstva", "e0b9a7f7"], "d": ["Kütahya, koja je u neredima nakon 1182. ponovo prešla Bizantu, za Alaudina Kejkubada I povraćena je od Nikejskog Carstva.", "90db8b27"]},
"OLAYLAR_T5_1000A:1233-01-01:1":{"b": ["Bedreddin Lulu sultan Mosula", "73268628"], "d": ["Smrću posljednjeg zengidskog atabega halifa je Bedreddina Lulua proglasio sultanom. (Rebiul-evvel 631 / decembar 1233; atlas, prateći zapis države, piše s preciznošću do godine.)", "076b23b0"]},
"OLAYLAR_T5_1000A:1234-08-01:0":{"b": ["Seldžuci zauzeli Harput", "3b9391eb"], "d": ["Vojska Alaudina Kejkubada nakon dvadeset četiri dana opsade primila je predaju tvrđave Harput; harputski ogranak Artukida prestao je.", "1ae6c0d9"]},
"OLAYLAR_T5_1000A:1240-07-23:0":{"b": ["Gijasudin Kejhusrev II zauzeo Amid", "c37c3b04"], "d": ["Anadolijski seldžučki sultan Gijasudin Kejhusrev II uzeo je Amid od Ejubida.", "f8a0cc8c"]},
"OLAYLAR_T5_1000A:1253-01-01:0":{"b": ["Mengu-kaan imenovao Iftiharuddina namjesnikom Kazvina", "fc650d13"], "d": ["Veliki mongolski kan Mengu imenovao je namjesnika u Kazvinu; počelo je doba Iftiharida.", "c042dadd"]},
"OLAYLAR_T5_1000A:1256-01-01:0":{"b": ["Dolazak Hulagua: Kazvin i Nahčivan prešli pod upravu Ilhanata", "24673608"], "d": ["Dolaskom Hulagua u Iran mongolska uprava prenesena je na Ilhanatsku državu; Kazvin i Nahčivan prešli su pod ilhanatsku upravu (granica po pravilu 5, nije dan iz izvora). U Širvanu (Baku, Šemaha) mongolska okupacija donijela je teška razaranja, ali su Širvanšasi opstali kao lokalna dinastija; atlas ove dvije tačke drži u boji širvanšaha (Emreova odluka).", "14d75e4f"]},
"OLAYLAR_T5_1000A:1257-01-01:0":{"b": ["Mongoli zauzeli Tikrit", "60af2df0"], "d": ["Tokom mongolske invazije Tikrit je zauzet i opljačkan; grad je izašao iz abasidske uprave.", "1a51fdd7"]},
"OLAYLAR_T5_1000A:1257-03-27:0":{"b": ["Hulagu krenuo iz Hamadana na Bagdad", "5f0c77b5"], "d": ["Hulagu je iz Hamadana, gdje mu je bila komora, krenuo u pohod na Bagdad (svjedočanstvo ilhanatske vlasti).", "303cbae8"]},
"OLAYLAR_T5_1000A:1258-01-01:0":{"b": ["Bogatimur zauzeo Kufu i Basru", "dec82b4e"], "d": ["Mongolske snage pod komandom Bogatimura zauzele su Kufu, Vasit i Basru.", "10fd1496"]},
"OLAYLAR_T5_1000A:1258-01-01:1":{"b": ["Irak prešao u ruke Mongola (regionalno)", "7b990281"], "d": ["Hulaguovim zauzimanjem Bagdada 1258. srušena je Abasidska država i Irak je prešao u ruke Mongola.", "6f12d882"]},
"OLAYLAR_T5_1000A:1258-01-01:2":{"b": ["Maraş prepušten Armencima", "6161f1a5"], "d": ["Imaduddin iz porodice Husameddina, ne našavši podršku, prepustio je Maraş kilikijskim Armencima.", "9ea1e7ff"]},
"OLAYLAR_T5_1000A:1258-01-01:3":{"b": ["Vasit prešao pod ilhanatsku vlast", "fbdf83fc"], "d": ["Ilhanatskim zauzimanjem Iraka Vasit je prešao pod njihovu upravu.", "5f4aee6b"]},
"OLAYLAR_T5_1000A:1258-02-10:0":{"b": ["Mongoli zauzeli Bagdad; kraj Abasidskog hilafeta", "41c34bd4"], "d": ["Mongoli pod komandom Hulagua napali su Bagdad, halifa Mustasim se predao; grad je prešao pod ilhanatsku vlast.", "1c979d91"]},
"OLAYLAR_T5_1000A:1262-01-01:0":{"b": ["Mongoli zauzeli Mosul, dinastija Lulua prestala", "035d0121"], "d": ["Mosul el-Melika es-Saliha Ismaila, koji je stao uz Bajbarsa, pretrpio je mongolsko razaranje, a on je ubijen pred Hulaguom.", "69cc41a9"]},
"OLAYLAR_T5_1000B:1069-10-20:0":{"b": ["Mekanska hutba prebačena sa Fatimija na abasidskog halifu i sultana Alp Arslana", "df951887"], "d": ["Budući da zbog gladi u Egiptu nije stizala hrana, mekanski emir Ebu Hašim Muhammed b. Džafer dao je da se hutba uči u ime abasidskog halife Kaima bi-Emrillaha i seldžučkog sultana Alp Arslana; Meka je prešla pod vrhovništvo Velikih Seldžuka.", "c8a5b1f7"]},
"OLAYLAR_T5_1000B:1075-01-01:0":{"b": ["Atsiz b. Uvak zauzeo Damask", "8eea047f"], "d": ["Atsiz je zauzeo Siriju i dao da se hutba uči u ime abasidskog halife i Melik-šaha.", "1de51f0c"]},
"OLAYLAR_T5_1000B:1076-01-01:0":{"b": ["Mekanski emir Ebu Hašim ponovo dao da se hutba uči u ime fatimijskog halife", "85b6c0c0"], "d": ["Uprkos Melik-šahovim nastojanjima da učvrsti sunitski uticaj, mekanski emir ponovo je počeo davati da se hutba uči u ime Fatimija; Meka se vratila pod fatimijsko vrhovništvo.", "a7ec64c5"]},
"OLAYLAR_T5_1000B:1079-01-01:0":{"b": ["Tutuš ušao u Damask, osnovani sirijski Seldžuci", "b48b38be"], "d": ["Tutuš je ušao u grad i osnovao Sirijsku seldžučku državu.", "6404e098"]},
"OLAYLAR_T5_1000B:1080-01-01:0":{"b": ["Mekanski emir izjavio odanost abasidskom halifi Muktediju i sultanu Melik-šahu", "38a430a5"], "d": ["Mekanski emir ponovo se podredio abasidskom halifi i seldžučkom sultanu; ta odanost trajala je do Melik-šahove smrti (1092).", "41ad14e9"]},
"OLAYLAR_T5_1000B:1092-01-01:0":{"b": ["Nakon smrti sultana Melik-šaha hutba u Meki ponovo vraćena Fatimijama", "195a27cd"], "d": ["Kada je umro seldžučki sultan Melik-šah, mekanski emir ponovo je počeo davati da se hutbe uče u ime fatimijskog halife; Meka je prešla pod fatimijsko vrhovništvo.", "00e9a74b"]},
"OLAYLAR_T5_1000B:1097-07-01:0":{"b": ["Nakon poraza kod Dorileja Eskişehir se vratio Bizantu", "3f381ee4"], "d": ["Nakon povlačenja Kilidž Arslana I pred krstašima grad je ponovo prešao pod bizantijsku upravu.", "f3155b07"]},
"OLAYLAR_T5_1000B:1104-06-06:0":{"b": ["Tugtegin osnovao Damaščanski atabegat", "f26729c0"], "d": ["Nakon Dukakove smrti atabeg Tugtegin osnovao je dinastiju Burida.", "ac9e7419"]},
"OLAYLAR_T5_1000B:1150-01-01:0":{"b": ["Almohadi zauzeli Meknes", "ee976b41"], "d": ["Nakon dugog otpora grad je došao pod almohadsku vlast i bio opljačkan.", "4924b727"]},
"OLAYLAR_T5_1000B:1154-04-25:0":{"b": ["Nuruddin Zengi zauzeo Damask", "a4fd8b58"], "d": ["Nuruddin Mahmud stavio je Damask pod svoju vlast.", "f87fe7de"]},
"OLAYLAR_T5_1000B:1171-09-13:0":{"b": ["U Egiptu prestala fatimijska uprava, na čelo došli Ejubidi — Aleksandrija, Fajum i Meka (Hidžaz)", "1c565534"], "d": ["Saladinovim vezirstvom i smrću fatimijskog halife Adida (567/1171) Egipat je prešao Ejubidima; Aleksandrija i Fajum došli su pod ejubidsku upravu. Dan nije naveden u izvoru — preuzet je iz kraja zapisa o Fatimijama (dan iz zapisa države nije izvor). I Hidžaz je došao pod ejubidsku upravu; vrhovništvo nad Mekom prešlo je s Fatimija na Ejubide (Emreov model vrhovništva #23).", "191ac5be"]},
"OLAYLAR_T5_1000B:1174-01-01:0":{"b": ["Saladin zauzeo Damask", "dfdb11ce"], "d": ["Nakon Nuruddinove smrti grad je prešao Saladinu Ejubiju.", "a20855b8"]},
"OLAYLAR_T5_1000B:1176-09-17:0":{"b": ["Nakon Miriokefalona Bizant ispraznio Dorilej", "24aef255"], "d": ["Nakon poraza kod Miriokefalona Manuel je prema ugovoru srušio utvrđenja Dorileja i ispraznio grad; Turci su ga počeli zvati Eskişehir.", "d56a7724"]},
"OLAYLAR_T5_1000B:1178-01-01:0":{"b": ["Amasya pripojena seldžučkim teritorijama", "cf56b964"], "d": ["Kilidž Arslan II pripojio je danišmendidske teritorije (uključujući Amasyu) seldžučkoj zemlji.", "ddbb98aa"]},
"OLAYLAR_T5_1000B:1187-01-01:0":{"b": ["Braća Asen zauzela sjevernu Bugarsku; Bizant priznao Drugo bugarsko carstvo", "ff0554e9"], "d": ["Braća Petar i Asen uz kumansku podršku ponovo su zauzela sjevernu Bugarsku; mirom 1187. Bizant je priznao Drugo bugarsko carstvo.", "fc165cbf"]},
"OLAYLAR_T5_1000B:1189-01-01:0":{"b": ["Srbija učvrstila vlast u Zeti", "794c821d"], "d": ["Godine 1189. Srbija je učvrstila vlast nad Zetom (uključujući kotorsku obalu); Zeti je priznat poseban status.", "5f16f312"]},
"OLAYLAR_T5_1000B:1192-01-01:0":{"b": ["Guy de Lusignan kupio Kipar, Nikozija postala prijestolnica", "11017aea"], "d": ["Guy de Lusignan kupio je ostrvo od templara i učinio Nikoziju prijestolnicom.", "b6494b99"]},
"OLAYLAR_T5_1000B:1201-03-01:0":{"b": ["Kalojan zauzeo Varnu", "1237fe7f"], "d": ["Bugari pod komandom cara Kalojana u martu 1201. uzeli su Varnu od Bizanta; grad je u XIII-XIV stoljeću ostao u granicama Bugarske države.", "b60444f8"]},
"OLAYLAR_T5_1000B:1202-01-01:0":{"b": ["Nišapur konačno pripojen Horezmšasima", "fa4a6cd2"], "d": ["Alaudin Muhammed b. Tekiš konačno je pripojio grad horezmšahovskim teritorijama.", "58cb9059"]},
"OLAYLAR_T5_1000B:1204-04-13:0":{"b": ["Galipoljsko poluostrvo prešlo pod latinsku upravu", "27308f59"], "d": ["Nakon IV krstaškog pohoda Galipolje s okolinom prešlo je 1204. pod upravu Latina.", "48b977ad"]},
"OLAYLAR_T5_1000B:1204-04-13:1":{"b": ["Osnovana Epirska despotovina — Janjina postala središte, Lepant prešao despotovini", "d7966877"], "d": ["Nakon IV krstaškog pohoda Mihailo Anđel osnovao je Epirsku despotovinu; Janjina je postala središte despotovine, a i Lepant je ostao unutar teritorija despotovine.", "632eac4c"]},
"OLAYLAR_T5_1000B:1204-08-12:0":{"b": ["Kreta prodata Veneciji", "f1760e84"], "d": ["Markiz Montferrata Bonifacije sporazumom od 12. augusta 1204. prepustio je Kretu Veneciji za 100.000 srebrnjaka.", "cdb2570d"]},
"OLAYLAR_T5_1000B:1219-01-01:0":{"b": ["Osnovana Mansura", "342a6f47"], "d": ["El-Melik el-Kamil osnovao je Mansuru kao štab protiv krstaša koji su zauzeli Damijetu.", "35189819"]},
"OLAYLAR_T5_1000B:1221-04-10:0":{"b": ["Mongoli zauzeli Nišapur", "0e73f075"], "d": ["Mongolskom invazijom grad je razoren.", "be55c768"]},
"OLAYLAR_T5_1000B:1229-01-01:0":{"b": ["Rasulid Nuruddin Omer preuzeo upravu nad Jemenom", "ee1ec7ab"], "d": ["Nakon smrti posljednjeg jemenskog Ejubida el-Mesuda Nuruddin Omer zagospodario je Jemenom.", "02cf9719"]},
"OLAYLAR_T5_1000B:1235-01-01:0":{"b": ["Nikejski car Vatac povratio Galipolje", "a6936e33"], "d": ["Nikejski car Ivan III Duka Vatac povratio je Galipolje od Latina (1235).", "184a089e"]},
"OLAYLAR_T5_1000B:1243-07-01:0":{"b": ["Mongoli zauzeli Amasyu", "783bcd0c"], "d": ["Nakon Köse Daga Mongoli su zauzeli grad, njime su upravljali mongolski namjesnici.", "4e46e2df"]},
"OLAYLAR_T5_1000B:1246-01-01:0":{"b": ["Vatac prešao u Trakiju: Edirne i Solun pripojeni Nikejskom Carstvu", "0bf61ca5"], "d": ["Nikejski vladar Ivan III Duka Vatac 1246. prešao je u Trakiju i zauzeo teritorije koje su zaposjeli Bugari i Solun.", "73992921"]},
"OLAYLAR_T5_1000B:1250-01-01:0":{"b": ["Rasulidska vlast priznavana u Meki — Nuruddin Omer pao žrtvom atentata", "d7e03c21"], "d": ["Kada je jemenski rasulidski sultan Nuruddin Omer ubijen u Džanadu (februar 1250), vlast njegove države priznavana je od Meke do Hadramauta; u godini kada je prestao ejubidski sultanat Meka se vidi pod rasulidskim vrhovništvom.", "ba654624"]},
"OLAYLAR_T5_1000B:1250-04-30:0":{"b": ["U Egiptu osnovana Memlučka država — Aleksandrija, Mansura i Fajum prešli Memlucima", "230c1a11"], "d": ["Nakon Turan-šaha s Šedžeruddur i Izzudinom Ajbekom uspostavljena je memlučka vlast; egipatski gradovi (Aleksandrija, Mansura, Fajum) prešli su pod memlučku upravu. Izvor daje Ajbekovo stupanje na prijestolje 3. jula 1250; atlas je dan preuzeo iz kraja zapisa o Ejubidima (30. april 1250) — dan iz zapisa države nije izvor, razlika je prijavljena.", "f9743bcd"]},
"OLAYLAR_T5_1000B:1250-04-30:1":{"b": ["Alepski Ejubid en-Nasir Jusuf zagospodario Damaskom", "d585985d"], "d": ["Dok se u Egiptu uspostavljala memlučka vlast, gospodar Alepa en-Nasir Jusuf zauzeo je Damask (648/1250).", "c05ddddc"]},
"OLAYLAR_T5_1000B:1253-04-01:0":{"b": ["Jerusalem mirom ostavljen Memlucima", "50d53fac"], "d": ["Mirom sklopljenim uz posredovanje halife Jerusalem je ostavljen Memlucima.", "82982e3a"]},
"OLAYLAR_T5_1000B:1256-01-01:0":{"b": ["Jerusalem ponovo prešao Ejubidima", "fdeedd4a"], "d": ["Palestina i Jerusalem ponovo su prešli u ruke sirijskih Ejubida.", "46a6e2a9"]},
"OLAYLAR_T5_1000B:1260-03-01:0":{"b": ["Mongoli zauzeli Damask", "430bdfea"], "d": ["U Hulaguovom sirijskom pohodu Damask je prešao Mongolima.", "407e5d3f"]},
"OLAYLAR_T5_1000B:1260-09-03:0":{"b": ["Bitka kod Ajn Džaluta: Damask i Jerusalem prešli Memlucima", "40ebd7b7"], "d": ["Kutuz je porazio Mongole kod Ajn Džaluta (25. ramazan 658 / 3. septembar 1260); veći dio Sirije, Damask i Jerusalem prešli su u ruke Memluka, ejubidska dinastija prestala je.", "619c8015"]},
"OLAYLAR_T5_1000B:1261-06-09:0":{"b": ["Bajbars obnovio Abasidski hilafet u Kairu — Meka i Medina vezane za Memluke", "a5128a1e"], "d": ["Bajbars je Abasida Ahmeda, koji je preživio pad Bagdada, proglasio halifom u Kairu i dao mu prisegu; kao zaštitnik hilafeta pod memlučko vrhovništvo stavio je i dva sveta grada (Harameyn). Dan je dan obnove hilafeta; dan pripajanja Meke i Medine nije naveden u izvoru (donja granica).", "638d550a"]},
"OLAYLAR_T5_1000B:1261-07-25:0":{"b": ["Nikejske jedinice ušle u Istanbul — obnovljeno Bizantsko Carstvo", "81741490"], "d": ["Nikejske jedinice 25. jula 1261. ušle su u Istanbul i okončale latinsku vlast; teritorije laskaridske (nikejske) države — Bursa, Izmir, Čimpe, Edirne, Solun — ponovo su postale Bizantsko Carstvo. Atlas na tim tačkama razdoblje Nikejskog Carstva prije 1261. prikazuje samo za one koje se u izvoru pominju po imenu.", "b389b508"]},
"OLAYLAR_T5_1000B:1271-01-01:0":{"b": ["Karlo Anžujski zauzeo Drač i Kroju", "082a86b8"], "d": ["Karlo iz anžujske dinastije 1271-1272. zauzeo je Drač i Kroju i dao obnoviti staru tvrđavu.", "e9f84d14"]},
"OLAYLAR_T5_1000B:1284-01-01:0":{"b": ["Sicilijanci zauzeli ostrvo Džerbu", "daab5ad2"], "d": ["Ostrvo Džerbu zauzeli su Sicilijanci 683 (1284-85); najprije je bilo papinski posjed, zatim vezano za Kraljevinu Siciliju.", "691035b3"]},
"OLAYLAR_T5_1000B:1318-01-01:0":{"b": ["Janjina ponovo pripojena Bizantskom Carstvu", "60016303"], "d": ["Janjina, koja je u drugoj polovini XIII stoljeća mnogo puta mijenjala vlasnika, 1318. ponovo je pripojena Bizantu, ali je u izvjesnoj mjeri zadržala autonomiju; središte Epirske despotovine pomjerilo se u Artu.", "14c24d12"]},
"OLAYLAR_T5_1000B:1334-01-01:0":{"b": ["Stanovnici Džerbe protjerali Sicilijance s ostrva", "ff71985e"], "d": ["Stanovnici ostrva, pobunivši se protiv loše uprave sicilijanskih namjesnika, 1334. protjerali su Sicilijance; Džerba je ponovo došla pod hafsidsku upravu.", "1ddb9780"]},
"OLAYLAR_T5_1000B:1363-01-01:0":{"b": ["Karlo Thopia zagospodario Krojom", "4e40583d"], "d": ["Nakon smrti cara Dušana (1355) Albanac Karlo Thopia zagospodario je Krojom.", "7af64cd2"]},
"OLAYLAR_UMIT19_ASIRET_1119:1722-04-05:0":{"b": ["Roggeveen je ugledao Uskršnji otok i dao mu ime Paasch Eyland; da na otoku žive ljudi shvaćeno je sljedećeg dana po dimu", "c6940261"], "d": ["Ekspedicija Jacoba Roggeveena je, prema zvaničnom brodskom dnevniku, 5. aprila 1722. ugledala nizak i ravan otok, te ga je, budući da se našla ondje na dan Uskrsa, nazvala Paasch Eyland. Dana 6. aprila uočen je dim koji se dizao s više mjesta i zaključeno je da na otoku žive ljudi; Behrensov opis otkriće smješta na 6. april.", "32641f88"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-08-13:0":{"b": ["Prethodnica Sullivanove ekspedicije spalila je selo Chemung (Chemong)", "2656fcd6"], "d": ["Sullivanova vojska krenula je 12. augusta 1779. uveče iz Tioge na noćni marš i sljedećeg jutra u zoru stigla do sela Chemung; seljani su prethodno pobjegli. Jedinice su spalile oko dvadeset objekata u selu i uništile okolna polja kukuruza.", "07caaa80"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-08-29:0":{"b": ["Bitka kod Newtowna: Sullivanova ekspedicija razbila je zaklon irokeskih ratnika, među kojima su bili Cayuge i Seneke, blizu Chemunga", "2383ea65"], "d": ["Vojska general-majora Sullivana naišla je 29. augusta 1779. blizu Chemunga na zaklon koji su pripremile snage u kojima su, prema Sullivanovom pismu, prevladavali indijanski ratnici «sedam naroda» (zajedno s Butlerima, Brantom i McDonaldom, pod odvojenim komandama); zbog artiljerijske vatre i bočnog pritiska generala Poora zaklon je napušten.", "3adfc9de"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-09-02:0":{"b": ["Sullivanova vojska uništila je selo Catharine's Town i njegov kukuruz", "62b91293"], "d": ["Vojska Sullivanove ekspedicije stigla je u noći 1. septembra 1779. u Catharine's Town blizu jezera Seneca; 2. septembra uništila je selo i zasijani kukuruz. Selo je bilo naselje s trideset kuća, vrtovima i obiljem kukuruza.", "d56e8155"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-09-05:0":{"b": ["Sullivanova vojska ušla je u selo Kendaia; oko dvadeset kuća pretvoreno je u pepeo, a usjevi i voćke uništeni", "68c01d89"], "d": ["Sullivanova vojska stigla je 5. septembra 1779. do sela Kendaia; prema Sullivanovom izvještaju, selo je bilo napušteno. Rogersov dnevnik bilježi da je selo uništeno, a Sullivanov zvanični izvještaj da je oko dvadeset kuća pretvoreno u pepeo i da je vojska otprilike jedan dan uništavala usjeve i voćke.", "f29f4983"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-09-15:0":{"b": ["Sullivanova vojska uništila je Genesee (Chenesee) Town i usjeve kukuruza i graha", "c5e8f3be"], "d": ["Sullivanova vojska ušla je 14. septembra 1779. u Genesee (Chenesee) Town, koji je imao oko sedamdeset kuća; 15. septembra cijela vojska izašla je na teren da uništi usjeve, spaljeni su kukuruz i grah, a kada je počeo povratni marš, sela su ostavljena u plamenu.", "3a04a429"]},
"OLAYLAR_UMIT19_ASIRET_1119:1830-10-07:0":{"b": ["U Van Diemenovoj zemlji počela je operacija Crna linija (Black Line): kolonisti su mobilisani da pohvataju tasmanijske Aboridžine", "d2ffdfcb"], "d": ["Proglasom Kolonijalnog sekretarijata od 25. septembra 1830. guvernera Arthura objavljeno je da će stanovništvo 7. oktobra 1830. masovno krenuti u akciju, a major Douglas će istog dana duž linije zauzeti osmatračke tačke. Cilj je bio pohvatati aboridžinska plemena i potjerati ih prema Tasmanovom poluotoku.", "a7114cb5"]},
"OLAYLAR_UMIT19_ASIRET_1119:1830-11-26:0":{"b": ["Prvi niz operacija Crne linije zvanično je završen: Vladina naredba br. 13", "861ffa50"], "d": ["Vladinom naredbom br. 13 od 26. novembra 1830. objavljeno je da je prvi niz operacija usmjerenih na hvatanje domorodačkih plemena zaključen dolaskom vojnih i civilnih jedinica do East Bay Necka.", "a4f38ca9"]},
"OLAYLAR_UMIT19_ASIRET_1119:1850-07-18:0":{"b": ["Ekspedicija Richardson–Barth–Overweg stigla je do Gata (Ghat), druge velike postaje na saharskom putu nakon Murzuka", "f52b2fa6"], "d": ["U dnevničkom zapisu od 18. jula 1850. Heinrich Barth, koji je prelazio Saharu s britanskom vladinom ekspedicijom na čelu s Richardsonom, opisuje približavanje i dolazak u Gat (Ghat), koji smatra drugom velikom postajom ekspedicije; neki od mještana prepoznali su Richardsona, koji je to mjesto ranije već posjetio, i dočekali ga. To nije prva evropska posjeta tom kraju.", "2e9bb2a4"]},
"OLAYLAR_UMIT19_ASIRET_1119:1869-07-13:0":{"b": ["Gustav Nachtigal stigao je do Taoa (Täo), jedne od glavnih dolina Tibestija", "bc67c7f0"], "d": ["Gustav Nachtigal je sa svojim karavanom, koji je dolazio iz Murzuka, napredovao jugozapadnim podnožjem planinskog masiva Tibesti; u knjizi Sahara i Sudan pod 13. julom opisuje dolazak u dolinu Tao (poglavlje knjige «Ankunft in Täo»), koju opisuje kao jednu od glavnih dolina Tibestija i pravu postojbinu plemićkih porodica. Piše da su ujutro istog dana stupili na ravnicu riječnih korita Taoa, a zatim sreli Galmu, rođaka Bü Zeida.", "f8941a27"]},
"OLAYLAR_UMIT19_ASIRET_1119:1874-05-06:0":{"b": ["Ernest Giles je pustinju zapadno od planinskog lanca Rawlinson nazvao «Gibson's Desert» u spomen na nestalog saputnika Alfreda Gibsona", "7ad5e61f"], "d": ["Zapadnoaustralijska ekspedicija Ernesta Gilesa (započeta u augustu 1873.) ušla je od planinskog lanca Rawlinson na zapad u pustinju; njegov saputnik Alfred Gibson nestao je u toj pustinji na Gilesovom konju. Giles u dnevniku pod 6. majem 1874. piše da je tom području, koje se prostire između lanca Rawlinson i sljedeće stalne vode, dao ime «Gibson's Desert».", "58bd64e7"]},
"OLAYLAR_UMIT19_ASIRET_1119:1879-08-02:0":{"b": ["Ekspedicija Gerharda Rohlfsa ušla je u Taiserbo, sjeverni kraj arhipelaga oaza Kufre", "577b4205"], "d": ["Ekspedicija Gerharda Rohlfsa za Njemačko afričko društvo, koja je krenula iz Tripolija, nakon ugovora sklopljenog sa Sujom u julu 1879. krenula je na jug i u 2 sata noću ušla u oazu Taiserbo, najsjeverniji otok Kufre. Rohlfs to opisuje kao «konačan dolazak do tajanstvene oaze Kufre»; do bunara Djrängedi stiglo se tek sljedećeg jutra u 11 sati.", "ca155f46"]},
"OLAYLAR_UMIT19_ASIRET_1119:1896-12-04:0":{"b": ["Kamilja ekspedicija Davida Carnegieja stigla je u Halls Creek u Kimberleyu; prvi put od 21. jula susreo je bijelog čovjeka", "55b94bf8"], "d": ["Kamilja ekspedicija Davida Carnegieja, koja je 9. jula 1896. krenula iz Coolgardieja, stigla je 4. decembra u Halls Creek. Carnegie piše da je prva osoba koju je sreo bio policijski narednik Brophy i da od 21. jula nisu vidjeli nijedno bijelo lice; putovanje je, uključujući skretanja, trajalo 1.413 milja.", "82b25b9d"]}
});
